/* Banque de questions (533) – chargée uniquement par la page du maître du jeu. Généré depuis le fichier Excel du quiz. f = numéro de la fiche de révision liée. */
window.QPK_QUESTIONS = [{"c": "Développement", "q": "L'ostéopathie chez le prématuré hospitalisé a-t-elle fait la preuve de son efficacité ?", "a": "Une réduction de la durée d'hospitalisation et des coûts. Mais les essais sont peu nombreux et hétérogènes : une confirmation par des équipes indépendantes reste nécessaire avant d'en faire une recommandation. (Référence : Lanaro 2017.)", "s": "Lanaro et al. 2017 – Osteopathic manipulative treatment showed reduction of length of stay and costs in preterm infants: meta-analysis", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5371477/", "f": 47}, {"c": "Développement", "q": "Que sont les mouvements généraux de Prechtl (General Movements) ? Quel pattern à 3-4 mois est le plus prédictif de PC ?", "a": "Observation vidéo des mouvements spontanés : writhing jusqu'à 6-9 semaines post-terme, puis fidgety d'environ 6-9 à 20 semaines d'âge corrigé. Normal = variable, complexe, fluide. L'absence de fidgety à 3-4 mois est le signe le plus prédictif de PC (sensibilité et spécificité supérieures à 90 %, environ 98 % de sensibilité pour l'évaluation des GMs selon Novak 2017). Les mouvements « cramped-synchronized » sont aussi très prédictifs.", "s": "Morgan et al. 2020 – Pooled diagnostic accuracy of neuroimaging, GMs and HINE", "u": "https://publires.unicatt.it/it/publications/the-pooled-diagnostic-accuracy-of-neuroimaging-general-movements-/", "f": 3}, {"c": "Développement", "q": "Plagiocéphalie : mesures de prévention à transmettre dès la maternité ?", "a": "Couchage TOUJOURS sur le dos pour dormir (prévention de la mort inattendue du nourrisson). À l'éveil : temps sur le ventre surveillé plusieurs fois par jour, portage, peau à peau, alterner le côté des stimulations, limiter transat et cosy. Si torticolis : stimuler le côté à travailler.", "s": "La Revue du Praticien – Mort inattendue du nourrisson", "u": "https://www.larevuedupraticien.fr/article/mort-inattendue-du-nourrisson", "f": 4}, {"c": "Développement", "q": "Quand et comment débuter le temps sur le ventre (tummy time) ?", "a": "Dès les premiers jours, éveillé et sous surveillance, quelques minutes plusieurs fois par jour, en augmentant progressivement. L'OMS (2019) recommande au moins 30 minutes par jour sur le ventre, réparties sur les temps d'éveil, chez le nourrisson qui ne se déplace pas encore, et pas plus d'1 heure d'affilée attaché (transat, poussette, porte-bébé). Il prévient la plagiocéphalie et favorise le contrôle de la tête.", "s": "OMS 2019 – Lignes directrices activité physique, sédentarité et sommeil des moins de 5 ans", "u": "https://www.ncbi.nlm.nih.gov/books/NBK541173/", "f": 4}, {"c": "Développement", "q": "Quels sont les facteurs de risque de plagiocéphalie positionnelle ?", "a": "Position préférentielle de la tête, torticolis, peu de temps sur le ventre, prématurité, sexe masculin, premier-né, grossesse multiple, longues périodes en transat ou cosy.", "s": "Laughlin et al. 2011 (AAP) – Prevention and management of positional skull deformities in infants", "u": "https://pure.psu.edu/en/publications/prevention-and-management-of-positional-skull-deformities-in-infa/", "f": 4}, {"c": "Développement", "q": "Qu'est-ce que les soins de développement (type NIDCAP) en néonatologie ?", "a": "Une approche individualisée qui observe les signaux du prématuré pour adapter les soins, l'environnement (lumière, bruit, manipulations) et le positionnement, en impliquant les parents.", "s": "Encyclopédie sur le développement des jeunes enfants – Soins développementaux individualisés pour les prématurés", "u": "https://www.enfant-encyclopedie.com/pdf/expert/prematurite/selon-experts/soins-developpementaux-individualises-pour-les-enfants-prematures", "f": 2}, {"c": "Développement", "q": "Comment positionner un enfant prématuré en couveuse ?", "a": "En flexion globale, regroupé, membres rapprochés de la ligne médiane, contenu dans un « nid », en alternant les positions pour éviter les déformations.", "s": "Encyclopédie sur le développement des jeunes enfants – Soins développementaux individualisés pour les prématurés", "u": "https://www.enfant-encyclopedie.com/pdf/expert/prematurite/selon-experts/soins-developpementaux-individualises-pour-les-enfants-prematures", "f": 2}, {"c": "Développement", "q": "Quels bénéfices du peau à peau (méthode kangourou) chez le prématuré ?", "a": "Meilleure stabilité physiologique (température, rythme cardiaque, respiration), soutien du lien parent-enfant et de l'allaitement. L'OMS (2022) recommande de le débuter dès la naissance, sans séparation initiale en couveuse, pendant autant d'heures que possible : il améliore la survie et réduit infections et hypothermie.", "s": "OMS 2022 – Recommandations pour le prématuré et le petit poids de naissance (peau à peau immédiat)", "u": "https://www.paho.org/en/news/15-11-2022-who-advises-immediate-skin-skin-care-survival-small-and-preterm-babies", "f": 2}, {"c": "Développement", "q": "Quels signes de stress chercher chez un prématuré pendant un soin ?", "a": "Désaturation, changement de couleur, hyperextension, doigts écartés, hoquet, bâillements, détournement du regard. On adapte ou on fait une pause.", "s": "Encyclopédie sur le développement des jeunes enfants – Soins développementaux individualisés pour les prématurés", "u": "https://www.enfant-encyclopedie.com/pdf/expert/prematurite/selon-experts/soins-developpementaux-individualises-pour-les-enfants-prematures", "f": 2}, {"c": "Développement", "q": "Les thérapies manuelles (ostéopathie, chiropraxie) ont-elles fait la preuve de leur efficacité sur les pleurs du nourrisson qui a des coliques ?", "a": "Non. La revue Cochrane (2012) trouve en moyenne environ 1 h 12 de pleurs en moins par jour, mais l'effet disparaît dans les essais où les parents ne savaient pas si leur enfant était traité. Pas de conclusion définitive possible, et les données de sécurité sont insuffisantes.", "s": "Cochrane 2012 – Manipulative therapies for infantile colic (CD004796)", "u": "https://cochranelibrary.com/cdsr/doi/10.1002/14651858.CD004796.pub2/information", "f": 47}, {"c": "Développement", "q": "Le massage du nourrisson (moins de 6 mois) est-il recommandé chez les nourrissons sans facteur de risque pour améliorer leur croissance ou leur développement ?", "a": "Les preuves ne le soutiennent pas. La revue Cochrane (2013) conclut que les résultats, de qualité méthodologique faible, ne justifient pas son utilisation dans les populations à faible risque.", "s": "Cochrane 2013 – Massage intervention for promoting mental and physical health in infants aged under six months (CD005038)", "u": "https://cochranelibrary.com/cdsr/doi/10.1002/14651858.CD005038", "f": 47}, {"c": "Développement", "q": "Quelles sont les missions du MK auprès du prématuré, de la néonatologie au retour à la maison ?", "a": "Évaluer le comportement et la motricité. Participer aux soins de développement : positionnement, manipulations, organisation des soins. Intervenir quand c'est utile, en suivant les signaux de l'enfant. Éduquer les parents : portage, positions, lecture des signaux. Après la sortie, il suit le développement moteur et participe au repérage précoce.", "s": "NHS Greater Glasgow & Clyde – Developmental care guideline (néonatologie)", "u": "https://clinicalguidelines.scot.nhs.uk/nhsggc-guidelines/nhsggc-guidelines/neonatology/developmental-care-guideline", "g": 1, "f": 2}, {"c": "Développement", "q": "Cite trois réflexes archaïques avec leur âge habituel de disparition.", "a": "Âges indicatifs, variables selon les sources : marche automatique 1-2 mois. Grasping palmaire 3-6 mois. Succion et points cardinaux 3-4 mois. Moro 4-6 mois. RTAC 4-6 mois (persistance = alerte). Grasping plantaire 9-12 mois.", "s": "StatPearls – Primitive Reflexes", "u": "https://www.statpearls.com/point-of-care/27744", "f": 1}, {"c": "Développement", "q": "Un enfant de 10 mois (âge corrigé) ne tient pas assis sans appui. Est-ce dans la norme de l'OMS ?", "a": "Non. La fenêtre normale de l'OMS pour la tenue assise sans appui va d'environ 3,8 à 9,2 mois : à 10 mois, il sort de la fenêtre, ce qui est un signe d'alerte justifiant un bilan.", "s": "OMS – Repères du développement moteur (WHO Motor Development Study)", "u": "https://www.who.int/tools/child-growth-standards/standards/motor-development-milestones", "f": 1}, {"c": "Développement", "q": "Selon la recommandation de l'APTA, quels sont les trois types de torticolis congénital ?", "a": "Torticolis postural (préférence sans restriction), torticolis musculaire (raideur du SCM) et forme avec masse (olive) du SCM. La recommandation y ajoute une classification de sévérité en 8 grades, selon l'âge à l'examen, la présence d'une masse et la différence de rotation cervicale passive entre les deux côtés.", "s": "APTA 2018 – Physical therapy management of congenital muscular torticollis (résumé)", "u": "https://www.guidelinecentral.com/guideline/8564", "f": 4}, {"c": "Développement", "q": "Quel est le principal facteur pronostique dans le torticolis congénital ?", "a": "L'âge de début de la prise en charge : plus elle est précoce (idéalement le premier mois), plus la résolution est rapide et complète.", "s": "Kaplan et al. 2018 – APTA CPG : kinésithérapie du torticolis musculaire congénital", "u": "https://pubmed.ncbi.nlm.nih.gov/30277962/", "f": 4}, {"c": "Développement", "q": "Quelles pathologies associées rechercher devant un torticolis congénital ?", "a": "Plagiocéphalie, dysplasie de hanche, asymétrie de développement moteur. Un torticolis atypique impose d'éliminer une cause non musculaire (osseuse, oculaire, neurologique).", "s": "Kaplan et al. 2018 – APTA CPG : kinésithérapie du torticolis musculaire congénital", "u": "https://pubmed.ncbi.nlm.nih.gov/30277962/", "f": 4}, {"c": "Développement", "q": "Que signifie un réflexe de Moro persistant au-delà de 6 mois ?", "a": "Une persistance anormale du réflexe archaïque, qui évoque une atteinte du système nerveux central (par exemple une PC) et justifie un bilan.", "s": "StatPearls – Primitive Reflexes", "u": "https://www.statpearls.com/point-of-care/27744", "f": 1}, {"c": "Développement", "q": "Comment l'orientation du nourrisson dans son lit aide-t-elle à prévenir une plagiocéphalie ?", "a": "En l'alternant chaque jour : la tête vers la tête du lit un jour, vers le pied le lendemain. Le nourrisson, qui regarde vers la pièce, tourne ainsi la tête des deux côtés. Il reste toujours couché sur le dos pour dormir.", "s": "Cummings, Société canadienne de pédiatrie 2011 (Paediatr Child Health) – La plagiocéphalie positionnelle", "u": "https://doi.org/10.1093/pch/16.8.493", "f": 4}, {"c": "Développement", "q": "Qu'est-ce qu'une préférence manuelle précoce, et pourquoi alerter ?", "a": "Usage préférentiel d'une main avant 12-18 mois (latéralisation stable vers 3-4 ans seulement). Signe un déficit du côté négligé : hémiparésie (PC unilatérale) d'abord. Éliminer plexus brachial, fracture de clavicule.", "s": "HAS 2020 – Troubles du neurodéveloppement : repérage et orientation des enfants à risque", "u": "https://www.has-sante.fr/jcms/p_3161334/fr/troubles-du-neurodeveloppement-tnd-reperage-et-orientation-des-enfants-a-risque", "f": 3}, {"c": "Développement", "q": "Le quatre-pattes est-il une étape obligatoire du développement moteur ?", "a": "Non. Dans l'étude de l'OMS, une petite partie des enfants n'est jamais passée par le quatre-pattes, sans conséquence. Son absence isolée n'est pas un signe d'alerte.", "s": "OMS – Repères du développement moteur (WHO Motor Development Study)", "u": "https://www.who.int/tools/child-growth-standards/standards/motor-development-milestones", "f": 1}, {"c": "Développement", "q": "Qu'est-ce que l'Alberta Infant Motor Scale (AIMS) ?", "a": "Échelle observationnelle de 58 items évaluant la motricité spontanée de 0 à 18 mois dans 4 positions (ventre, dos, assis, debout). Elle situe l'enfant en percentiles et repère les retards moteurs.", "s": "Piper et al. 1992 – Construction and validation of the Alberta Infant Motor Scale", "u": "https://pubmed.ncbi.nlm.nih.gov/1468050/", "f": 3}, {"c": "Développement", "q": "À quel âge apparaissent la tenue assise sans appui et la marche autonome ? Jusqu'à quel âge la marche reste-t-elle normale ?", "a": "Assis sans appui vers 6-8 mois. Marche autonome vers 12-13 mois en moyenne. Au-delà de 18 mois, signe d'alerte justifiant un bilan.", "s": "OMS – Repères du développement moteur (WHO Motor Development Study)", "u": "https://www.who.int/tools/child-growth-standards/standards/motor-development-milestones", "f": 1}, {"c": "Développement", "q": "Qu'est-ce que l'âge corrigé chez le prématuré, et jusqu'à quel âge l'utilise-t-on ?", "a": "Âge qu'aurait l'enfant s'il était né à terme (âge chronologique moins les semaines de prématurité). Utilisé classiquement jusqu'à 2 ans.", "s": "Raising Children Network – Corrected age for premature babies", "u": "https://raisingchildren.net.au/newborns/premature-babies-sick-babies/development/corrected-age", "f": 1}, {"c": "Développement", "q": "Selon l'OMS, quels sont les six grands repères moteurs de la petite enfance ?", "a": "Assis sans appui, debout avec aide, quatre pattes, marche avec aide, debout seul, marche seul. Chacun a une « fenêtre » d'acquisition normale assez large.", "s": "OMS – Repères du développement moteur (WHO Motor Development Study)", "u": "https://www.who.int/tools/child-growth-standards/standards/motor-development-milestones", "f": 1}, {"c": "Développement", "q": "Selon l'OMS, quelle est la fenêtre normale d'acquisition de la marche seule ?", "a": "Environ 8,2 à 17,6 mois. Une marche absente à 18 mois sort de la fenêtre et justifie un bilan.", "s": "OMS – Repères du développement moteur (WHO Motor Development Study)", "u": "https://www.who.int/tools/child-growth-standards/standards/motor-development-milestones", "f": 1}, {"c": "Développement", "q": "Un enfant né à 32 SA a 6 mois. Quel est son âge corrigé ?", "a": "32 SA = 8 semaines (2 mois) avant terme. Âge corrigé : 6 − 2 = 4 mois. On compare ses acquisitions à celles d'un enfant de 4 mois.", "s": "Raising Children Network – Corrected age for premature babies", "u": "https://raisingchildren.net.au/newborns/premature-babies-sick-babies/development/corrected-age", "f": 1}, {"c": "Développement", "q": "Arthrogrypose : pourquoi un fœtus qui bouge peu naît-il avec des articulations raides ?", "a": "Le mouvement est nécessaire au développement normal des articulations. Le mécanisme commun des arthrogryposes est l'akinésie fœtale : un fœtus qui bouge peu développe des contractures articulaires, présentes dès la naissance dans au moins deux régions du corps.", "s": "Rehabilitation in arthrogryposis multiplex congenita: a systematic review", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10217713/", "f": 32}, {"c": "Développement", "q": "Pourquoi juge-t-on le développement moteur en fenêtres d'acquisition plutôt qu'en dates ?", "a": "Parce que la variabilité normale est grande : l'OMS a montré des fenêtres larges pour chacun des six grands repères. Une date isolée crée de fausses alertes. Ce qui alerte, c'est de sortir de la fenêtre (assis non acquis à 9 mois, marche seule non acquise à 18 mois), un réflexe archaïque qui persiste ou une réaction de protection qui n'apparaît pas. Chez le prématuré, on corrige l'âge jusqu'à 2 ans.", "s": "OMS – Repères du développement moteur (WHO Motor Development Study)", "u": "https://www.who.int/tools/child-growth-standards/standards/motor-development-milestones", "g": 1, "f": 1}, {"c": "Développement", "q": "Enfant né sans main : quand proposer une première prothèse ?", "a": "La première prothèse suit le développement : au membre supérieur quand l'enfant tient assis. Les enfants appareillés avant 2 ans semblent moins souvent rejeter leur prothèse, mais les preuves sont faibles. Le choix se fait avec la famille.", "s": "Meurs et al. 2006 (Prosthet Orthot Int) – First prosthesis and later use in congenital unilateral upper limb deficiency", "u": "https://research.rug.nl/en/publications/prescription-of-the-first-prosthesis-and-later-use-in-children-wi/", "f": 16}, {"c": "Développement", "q": "Que mesure la PDMS-2 ?", "a": "La motricité globale et fine de la naissance à 5 ans, à travers 6 sous-tests (réflexes, stationnaire, locomotion, manipulation d'objets, préhension, intégration visuo-motrice). La PDMS-3 (2023, 0-5 ans) la remplace progressivement : contrôle du corps, déplacements, contrôle d'objets, manipulation, coordination œil-main, et un sous-test de condition physique.", "s": "Pearson – Peabody Developmental Motor Scales, 3e éd. (PDMS-3, 2023)", "u": "https://www.pearsonassessments.com/store/en/usd/p/P100049000", "f": 3}, {"c": "Développement", "q": "Quelles particularités motrices chez l'enfant porteur de trisomie 21 ?", "a": "Hypotonie, laxité ligamentaire et acquisitions motrices plus tardives (la marche est souvent acquise après 2 ans).", "s": "JPOSNA – Orthopaedic management in Down syndrome: current concept review", "u": "https://jposna.org/index.php/jposna/article/view/283", "f": 32}, {"c": "Développement", "q": "Trisomie 21 : comment l'enfant compense-t-il son hypotonie et sa laxité, et qu'en tire la rééducation ?", "a": "Il élargit ses appuis et bloque ses postures pour compenser l'instabilité articulaire. La rééducation soutient les acquisitions motrices, renforce et travaille l'équilibre. L'activité physique régulière est encouragée tout au long de la vie.", "s": "JPOSNA – Orthopaedic management in Down syndrome: current concept review", "u": "https://jposna.org/index.php/jposna/article/view/283", "f": 32}, {"c": "Développement", "q": "Tapis de marche chez le tout-petit à risque de retard moteur : avance-t-il l'âge de la marche ?", "a": "Dans la trisomie 21, oui : les enfants entraînés marchent environ 4 mois plus tôt. Chez l'enfant à risque modéré de retard, non. Dans la PC et le retard global, il accélère peut-être les acquisitions, mais les essais sont trop petits pour conclure.", "s": "Valentín-Gudiol et al. 2017 (Cochrane) – Treadmill interventions in children under six years of age at risk of neuromotor delay", "u": "https://cochrane.org/es/CD009242/BEHAV_intervenciones-con-cintas-de-correr-en-ninos-menores-de-seis-anos-de-edad-con-riesgo-de-retraso-de", "f": 15}, {"c": "Développement", "q": "Quels aspects d'une brûlure doivent faire penser à une maltraitance ?", "a": "Une explication absente ou qui ne colle pas. Un enfant qui ne se déplace pas encore seul. Une brûlure sur le dos des mains, la plante des pieds, les fesses ou le dos, ou en forme d'objet (cigarette, fer). Un ébouillantement des fesses et des jambes, en gant ou en chaussette, symétrique ou à bords nets, évoque une immersion forcée.", "s": "NICE CG89 – Child maltreatment : when to suspect maltreatment in under 18s (recommandation 1.1.6, brûlures)", "u": "https://www.nice.org.uk/guidance/CG89/chapter/recommendations", "f": 23}, {"c": "Développement", "q": "Que recommande la HAS (2018) pour la motricité d'un enfant avec un trouble du spectre de l'autisme ?", "a": "Explorer la motricité globale et fine à chaque examen de suivi. Devant une difficulté motrice ou de coordination, prescrire un bilan du développement moteur par un psychomotricien, un masseur-kinésithérapeute ou un ergothérapeute. Les interventions commencent sans attendre un diagnostic définitif.", "s": "HAS 2018 – Trouble du spectre de l'autisme : signes d'alerte, repérage, diagnostic et évaluation chez l'enfant et l'adolescent", "u": "https://afpa.org/content/uploads/2018/02/201802161645160.reco_enfant.pdf", "f": 6}, {"c": "Développement", "q": "Que recommande la HAS quand un signe d'alerte de trouble du neurodéveloppement est repéré ?", "a": "Ne pas attendre : orienter vers une consultation dédiée et, si le doute persiste, vers une plateforme de coordination et d'orientation (PCO) pour des bilans précoces, sans attendre un diagnostic.", "s": "HAS 2020 – Troubles du neurodéveloppement : repérage et orientation des enfants à risque", "u": "https://www.has-sante.fr/jcms/p_3161334/fr/troubles-du-neurodeveloppement-tnd-reperage-et-orientation-des-enfants-a-risque", "f": 3}, {"c": "Développement", "q": "Quels facteurs de risque justifient un suivi renforcé du neurodéveloppement selon la HAS ?", "a": "Notamment la grande prématurité, un petit poids de naissance, une souffrance néonatale, une exposition prénatale toxique, des antécédents familiaux de TND.", "s": "HAS 2020 – Troubles du neurodéveloppement : repérage et orientation des enfants à risque", "u": "https://www.has-sante.fr/jcms/p_3161334/fr/troubles-du-neurodeveloppement-tnd-reperage-et-orientation-des-enfants-a-risque", "f": 3}, {"c": "Développement", "q": "Genu varum et genu valgum : évolution physiologique selon l'âge ?", "a": "Varum de la naissance à 18-24 mois. Genoux droits vers 2 ans. Valgum maximal vers 3-4 ans. Léger valgus adulte vers 7-8 ans. Alerte : asymétrie, excès, persistance, petite taille (rachitisme, maladie de Blount).", "s": "Acta Orthopaedica – Spontaneous correction of severe tibiofemoral deformity in growing children", "u": "https://actaorthop.org/actao/article/view/28707", "f": 19}, {"c": "Développement", "q": "Quels enfants avec une cardiopathie congénitale sont à haut risque de trouble du neurodéveloppement ?", "a": "Selon l'AHA (2012) : les enfants opérés à cœur ouvert dans la petite enfance, ceux avec une cardiopathie cyanogène, et ceux qui cumulent d'autres facteurs (prématurité, syndrome génétique, assistance circulatoire, réanimation cardio-pulmonaire, longue hospitalisation, convulsions, anomalie à l'imagerie). On les réévalue à 12-24 mois, 3-5 ans et 11-12 ans.", "s": "Marino et al. 2012 (Circulation) – Neurodevelopmental outcomes in children with congenital heart disease (AHA)", "u": "https://scienceblog.cincinnatichildrens.org/children-with-heart-defects-need-early-evaluation-for-related-disorders/", "f": 33}, {"c": "Développement", "q": "Trisomie 21 : quels troubles associés peuvent limiter l'activité motrice ?", "a": "Une cardiopathie congénitale, des troubles de la vision et des troubles de l'audition. Ils s'ajoutent à l'hypotonie et à la laxité ligamentaire, et sont à prendre en compte pour proposer l'activité.", "s": "JPOSNA – Orthopaedic management in Down syndrome: current concept review", "u": "https://jposna.org/index.php/jposna/article/view/283", "f": 32}, {"c": "Développement", "q": "À quoi sert le HINE, et à quel âge l'utilise-t-on ?", "a": "Examen neurologique standardisé de 26 items, de 2 à 24 mois. Avec IRM et GMs, permet un diagnostic de PC (ou « haut risque ») avant 5-6 mois d'âge corrigé (Novak 2017, sensibilité HINE 90 %).", "s": "Novak et al. 2017 – Early, accurate diagnosis and early intervention in CP (JAMA Pediatrics)", "u": "https://cpresource.org/topic/early-diagnosis/early-accurate-diagnosis-and-early-intervention-cerebral-palsy-advances", "f": 3}, {"c": "Développement", "q": "Quelle est la place de l'orthèse crânienne (casque) dans la plagiocéphalie positionnelle ?", "a": "Le repositionnement et la kinésithérapie (torticolis) viennent d'abord : c'est le traitement de choix des formes légères à modérées (Société canadienne de pédiatrie 2011). L'orthèse crânienne n'est discutée que pour une asymétrie marquée et persistante, pendant la croissance rapide du crâne : il accélère la correction sans améliorer le résultat final, et se discute rarement après 8 mois. Dans l'essai randomisé de van Wijk (2014), chez des nourrissons de 5-6 mois avec une déformation modérée à sévère, il n'a pas fait mieux que l'évolution naturelle à 24 mois, avec des effets indésirables fréquents.", "s": "van Wijk et al. 2014 (BMJ) – Helmet therapy in infants with positional skull deformation: RCT", "u": "https://www.bmj.com/content/348/bmj.g2741.full", "f": 4}, {"c": "Développement", "q": "Signes d'alerte d'un développement moteur atypique à 4 mois et à 9 mois ?", "a": "4 mois : pas de tenue de tête, pas de mains à la bouche ni à la ligne médiane, poings fermés, pas d'appui avant-bras, asymétrie, pas de sourire/poursuite, absence de fidgety. 9 mois : pas d'assis sans appui, pas de retournement, pas de transfert main-main, pas de parachutes latéraux, préférence manuelle, RTAC persistant.", "s": "HAS 2020 – Troubles du neurodéveloppement : repérage et orientation des enfants à risque", "u": "https://www.has-sante.fr/jcms/p_3161334/fr/troubles-du-neurodeveloppement-tnd-reperage-et-orientation-des-enfants-a-risque", "f": 3}, {"c": "Développement", "q": "Quand apparaissent les réactions parachutes, et pourquoi sont-elles importantes ?", "a": "Parachute antérieur vers 6 mois, latéral vers 7-8 mois, postérieur vers 9-10 mois. Ce sont des réactions de protection qui persistent toute la vie. Leur absence ou leur asymétrie est un signe d'alerte.", "s": "Child & Family Development – Protective extension (parachute) reactions", "u": "https://www.childandfamilydevelopment.com/blog/developmental-reflexes-in-1st-year-protective-extension/", "f": 1}, {"c": "Développement", "q": "Une fillette se développait normalement, puis perd l'usage de ses mains vers 2 ans. Pourquoi ce tableau n'évoque-t-il pas une PC ?", "a": "Parce qu'il y a une régression après un développement d'abord normal. La PC est une atteinte non progressive. Ce tableau évoque un syndrome de Rett (gène MECP2), avec souvent des stéréotypies de « lavage de mains ».", "s": "Child Development (Australie) – Rett syndrome : stades et prise en charge", "u": "https://childdevelopment.com.au/areas-of-concern/diagnoses/rett-syndrome/", "f": 32}, {"c": "Développement", "q": "Trisomie 21 : quel entraînement précoce aide le nourrisson à marcher plus tôt ?", "a": "Un tapis roulant à vitesse lente, l'enfant soutenu par un parent, 8 minutes par jour, 5 jours par semaine : les enfants entraînés ont marché environ 3 mois et demi plus tôt que les enfants non entraînés. (Référence : Ulrich 2001.)", "s": "Ulrich et al. 2001 (Pediatrics) – Treadmill training of infants with Down syndrome (communiqué)", "u": "https://www.sciencedaily.com/releases/2001/11/011105072819.htm", "f": 32}, {"c": "Développement", "q": "Comment suivre l'évolution d'un genu varum ou d'un genu valgum chez le jeune enfant, et quand demander un avis ?", "a": "Enfant debout, on mesure l'écart entre les genoux (varum) ou entre les chevilles (valgum), de la même façon à chaque bilan. Un avis est demandé devant une asymétrie, une déformation excessive, une persistance après l'âge attendu ou une petite taille associée (rachitisme, maladie de Blount).", "s": "Physiopedia – Blount's disease", "u": "https://www.physio-pedia.com/Blount%27s_Disease", "f": 19}, {"c": "Développement", "q": "Fractures répétées, ou mécanisme qui ne colle pas avec les lésions : à quoi faut-il penser ?", "a": "À une fragilité osseuse, comme une ostéogenèse imparfaite, ou à une maltraitance. Le MK le note dès l'anamnèse et en parle au médecin.", "s": "Campagne, Manuel MSD (version professionnels, mars 2025) – Fractures pédiatriques physaires", "u": "https://www.msdmanuals.com/fr/professional/blessures-empoisonnement/fractures/fractures-pédiatriques-physaires-des-cartilages-de-croissance", "f": 22}, {"c": "Développement", "q": "Chez l'enfant autiste, pour quel objectif l'intégration sensorielle d'Ayres est-elle soutenue par les preuves, et pour lequel ne l'est-elle pas ?", "a": "Soutenue pour atteindre des objectifs individualisés de participation (objectifs fixés avec l'enfant et la famille en ergothérapie). Non soutenue pour réduire les comportements problématiques. Il faut davantage de recherche pour les autres populations. (Référence : revue systématique 2025.)", "s": "Revue 2025 – Ayres Sensory Integration : synthèse des preuves", "u": "https://pubmed.ncbi.nlm.nih.gov/40193295/", "f": 5}, {"c": "Développement", "q": "Enfant autiste de 6 ans qui marche sur la pointe et évite les jeux de ballon : comment l'aider ?", "a": "Faire un bilan moteur standardisé, adapté à l'enfant, en mesurant la flexion dorsale de cheville. Fixer avec la famille des objectifs concrets, comme attraper un ballon ou faire du vélo. Rendre les séances prévisibles et visuelles, partir de ses intérêts. Traiter la marche sur la pointe selon la rétraction. Encourager une activité physique régulière, qui améliore la motricité.", "s": "Bhat 2020 (Phys Ther) – Motor impairment in autism: report from the SPARK study", "u": "https://sparkforautism.org/discover_article/motor-challenges-autism/", "g": 1, "f": 6}, {"c": "Développement", "q": "Les troubles moteurs sont-ils fréquents chez l'enfant autiste ?", "a": "Oui, très. Ils ne font pas partie des critères du diagnostic, mais dans une cohorte de près de 12 000 enfants, 87 % étaient à risque de trouble de la coordination. Seuls 30 % environ étaient suivis en kinésithérapie.", "s": "Bhat 2020 (Phys Ther) – Motor impairment in autism: report from the SPARK study", "u": "https://sparkforautism.org/discover_article/motor-challenges-autism/", "f": 6}, {"c": "Développement", "q": "L'exercice physique améliore-t-il la motricité des enfants autistes ?", "a": "Oui. Une méta-analyse de 23 essais montre un effet moyen sur la motricité et la coordination, et une baisse des troubles du comportement. L'effet sur les compétences sociales n'est pas démontré dans l'ensemble. Les activités étaient variées : ballon, natation, arts martiaux, trampoline, vélo, équitation.", "s": "Wang et al. 2025 (Front Pediatr) – Physical exercise interventions in children with autism: meta-analysis of RCTs", "u": "https://www.frontiersin.org/articles/10.3389/fped.2025.1475019/full", "f": 6}, {"c": "Développement", "q": "Quelle hypothèse explique le mieux le trouble développemental de la coordination ?", "a": "Un déficit du modèle interne du mouvement : l'enfant prédit moins bien les conséquences de son geste et le corrige plus tard. Il automatise aussi plus difficilement les apprentissages moteurs. Le geste reste lent, coûteux en attention et variable. Le TDC s'associe souvent à d'autres troubles, comme le TDAH.", "s": "Blank et al. 2019 – International recommendations on DCD (DMCN)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6850610", "f": 5}, {"c": "Développement", "q": "Quelle activité physique l'OMS recommande-t-elle entre 5 et 17 ans ?", "a": "En moyenne 60 minutes par jour d'activité modérée à soutenue, avec des activités intenses et de renforcement musculaire au moins 3 jours par semaine, et moins de temps sédentaire devant les écrans.", "s": "OMS 2020 – Lignes directrices sur l'activité physique et la sédentarité", "u": "https://www.ncbi.nlm.nih.gov/books/NBK566046/", "f": 24}, {"c": "Développement", "q": "Les recommandations OMS d'activité physique s'appliquent-elles aux enfants en situation de handicap ?", "a": "Oui : les mêmes objectifs sont recommandés, adaptés aux capacités de l'enfant. Toute activité vaut mieux qu'aucune.", "s": "OMS 2020 – Lignes directrices sur l'activité physique et la sédentarité", "u": "https://www.ncbi.nlm.nih.gov/books/NBK566046/", "f": 24}, {"c": "Développement", "q": "La commotion cérébrale récupère-t-elle aussi vite chez l'enfant que chez l'adulte ?", "a": "Non, la récupération est souvent plus lente chez l'enfant. La plupart récupèrent en moins de 4 semaines. Au-delà de 4 semaines de symptômes, une évaluation pluridisciplinaire est justifiée.", "s": "Patricios et al. 2023 (BJSM) – Consensus statement on concussion in sport : 6th International Conference, Amsterdam 2022", "u": "https://bjsm.bmj.com/content/57/11/695", "f": 26}, {"c": "Développement", "q": "Le trouble développemental de la coordination est-il rare ?", "a": "Non : il concerne environ 5 à 6 % des enfants d'âge scolaire. Il s'associe souvent à d'autres troubles du neurodéveloppement, comme le TDAH.", "s": "Blank et al. 2019 – International recommendations on DCD (DMCN)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6850610", "f": 5}, {"c": "Développement", "q": "À partir de quand parle-t-on d'incontinence urinaire chez l'enfant ?", "a": "À partir de 5 ans, si les fuites surviennent au moins une fois par mois pendant au moins 3 mois. Avant, les fuites font partie de l'acquisition normale de la propreté.", "s": "Austin et al. 2015 (Neurourol Urodyn) – The standardization of terminology of lower urinary tract function in children and adolescents: update report from the ICCS", "u": "https://www.ics.org/folder/standardisation/current-ics-standardisations/lower-urinary-tract-function/d/lower-urinary-tract-function-in-children-and-adolescents-update-report/download", "f": 35}, {"c": "Développement", "q": "Énurésie : quels conseils, et quel traitement de première intention ?", "a": "On ne restreint pas les boissons. On valorise les comportements (boire assez, aller aux toilettes), pas les nuits sèches. L'alarme est le traitement de première intention, car ses résultats durent mieux. La desmopressine agit plus vite mais rechute plus souvent.", "s": "O'Flynn 2011 (Br J Gen Pract) – The management of bedwetting in children (synthèse de NICE CG111)", "u": "https://bjgp.org/content/61/586/360", "f": 35}, {"c": "Développement", "q": "Enfant de 7 ans qui a des fuites dans la journée : quelle démarche ?", "a": "Vérifier les critères (au moins une fuite par mois depuis 3 mois). Faire remplir un calendrier mictionnel et des selles. Rechercher et traiter une constipation. Commencer par l'urothérapie standard : explications, mictions régulières, boissons, posture aux toilettes. Ajouter le biofeedback en cas de dyssynergie. Adresser en cas de signe d'alerte neurologique ou digestif.", "s": "Austin et al. 2015 (Neurourol Urodyn) – The standardization of terminology of lower urinary tract function in children and adolescents: update report from the ICCS", "u": "https://www.ics.org/folder/standardisation/current-ics-standardisations/lower-urinary-tract-function/d/lower-urinary-tract-function-in-children-and-adolescents-update-report/download", "g": 1, "f": 35}, {"c": "Développement", "q": "Trouble développemental de la coordination : en quoi un tapis à obstacles peut-il aider ?", "a": "Il entraîne directement la tâche : adapter son pas pour éviter des obstacles. Dans une étude, la marche adaptative s'est améliorée, s'est transférée à la marche au sol et s'est maintenue à 6 mois. Une seule étude, sans groupe témoin.", "s": "Kuijpers et al. 2022 (Gait Posture) – Walking adaptability improves after treadmill training in children with DCD: a proof-of-concept study", "u": "https://radboudumc.nl/en/news-items/2022/training-improves-walking-adaptability", "f": 15}, {"c": "Développement", "q": "Chez l'enfant plus jeune, quelle lésion le mécanisme d'une rupture du LCA peut-il provoquer à la place ?", "a": "Un arrachement de l'insertion osseuse du ligament : la fracture de l'épine tibiale. Le mécanisme est le même, le plus souvent sans contact : réception de saut, changement de direction, genou qui part en valgus.", "s": "Return to sport after pediatric and adolescent ACL injury: current evidence", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5876277/", "f": 25}, {"c": "Développement", "q": "Un jeune sportif en pleine croissance se plaint d'une « douleur de croissance ». Faut-il le rassurer d'emblée ?", "a": "Non : il faut l'examiner. Chez le sportif, cette douleur peut être une fracture de fatigue ou une apophysite. Des fractures de fatigue répétées doivent faire rechercher un déficit énergétique relatif dans le sport (REDs).", "s": "Mountjoy et al. 2023 (BJSM) – IOC consensus statement on Relative Energy Deficiency in Sport (REDs)", "u": "https://pubmed.ncbi.nlm.nih.gov/37752011/", "f": 25}, {"c": "Développement", "q": "Pourquoi les apophysites surviennent-elles surtout pendant la poussée pubertaire ?", "a": "Le cartilage de croissance de l'apophyse est plus fragile que le tendon qui s'y insère. Pendant le pic de croissance, les os s'allongent plus vite que les muscles, qui se tendent. Les tractions répétées du sport irritent alors l'apophyse. Elles touchent plus souvent les garçons, et plus tôt les filles, dont la puberté est plus précoce.", "s": "Atanda, Shah & O'Brien 2011 (Am Fam Physician) – Osteochondrosis: common causes of pain in growing bones", "u": "https://www.aafp.org/pubs/afp/issues/2011/0201/p285.pdf", "f": 19}, {"c": "Développement", "q": "Scoliose idiopathique : pourquoi la croissance restante est-elle déterminante ?", "a": "Le risque d'aggravation dépend de la croissance restante et de l'angle. La croissance restante s'estime par le Risser, de 0 à 5. Les plus à risque sont les filles en pleine croissance pubertaire, avec une courbure déjà importante et un Risser bas. Au-delà de 30°, le risque d'évolution augmente nettement. Au-delà de 50°, la courbure continuera presque certainement d'évoluer à l'âge adulte.", "s": "Negrini et al. 2018 (Scoliosis Spinal Disord) – 2016 SOSORT guidelines: orthopaedic and rehabilitation treatment of idiopathic scoliosis during growth", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5795289", "f": 20}, {"c": "Développement", "q": "Au bilan d'une scoliose idiopathique, quels éléments de croissance recueille-t-on, en plus de la radiographie ?", "a": "La taille debout et assise, le stade pubertaire et la date des premières règles. Avec le Risser, ils estiment la croissance restante. Plus elle est importante, plus le risque d'aggravation est grand.", "s": "Negrini et al. 2018 (Scoliosis Spinal Disord) – 2016 SOSORT guidelines: orthopaedic and rehabilitation treatment of idiopathic scoliosis during growth", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5795289", "f": 20}, {"c": "Neurologie", "q": "Hypotonie du nourrisson : origine centrale ou périphérique à l'examen ?", "a": "Centrale (la plus fréquente) : hypotonie axiale ± hypertonie des membres, ROT normaux ou vifs, force relativement conservée, troubles de vigilance, convulsions, dysmorphie. Périphérique : faiblesse marquée, ROT abolis, regard vif, position en grenouille, fasciculations de langue (SMA). Manœuvres : suspension ventrale, tiré-assis, suspension verticale.", "s": "NHS GGC – Evaluation of the floppy infant", "u": "https://www.clinicalguidelines.scot.nhs.uk/nhsggc-guidelines/nhsggc-guidelines/neonatology/evaluation-of-the-floppy-infant/", "f": 3}, {"c": "Neurologie", "q": "Un nourrisson présente un signe d'alerte moteur à 4 mois. Faut-il parler de paralysie cérébrale aux parents ?", "a": "Non : un signe d'alerte n'est pas un diagnostic. On oriente sans attendre vers une consultation dédiée (HAS 2020), sans conclure trop vite. Si les éléments convergent (mouvements généraux, HINE, IRM), on parle de « haut risque de PC » pour démarrer l'intervention précoce.", "s": "Novak et al. 2017 – Early, accurate diagnosis and early intervention in CP (JAMA Pediatrics)", "u": "https://cpresource.org/topic/early-diagnosis/early-accurate-diagnosis-and-early-intervention-cerebral-palsy-advances", "f": 3}, {"c": "Neurologie", "q": "Torticolis du nourrisson : quels éléments doivent faire chercher une cause non musculaire ?", "a": "Un torticolis sans raideur du sterno-cléido-mastoïdien, d'apparition tardive ou avec des signes neurologiques. On recherche alors une cause osseuse, cervicale, oculaire ou neurologique.", "s": "APTA 2018 – Physical therapy management of congenital muscular torticollis (résumé)", "u": "https://www.guidelinecentral.com/guideline/8564", "f": 4}, {"c": "Neurologie", "q": "Paralysie du plexus brachial : quel signe fait suspecter un arrachement de racine ?", "a": "Un syndrome de Claude Bernard-Horner du même côté : pupille plus petite et paupière tombante. L'arrachement de la racine au ras de la moelle ne récupère pas seul. L'enfant est adressé tôt à une équipe spécialisée.", "s": "Hand Surgery Resource – Brachial plexus birth palsy (synthèse)", "u": "https://www.handsurgeryresource.net/bpbp", "f": 28}, {"c": "Neurologie", "q": "Principes de l'intervention précoce dans la PC (type GAME) ?", "a": "Goals-Activity-Motor Enrichment : démarrage dès le « haut risque », objectifs fixés par les parents, pratique intensive de tâches initiées par l'enfant, enrichissement de l'environnement, coaching parental à domicile.", "s": "Morgan et al. 2015 – GAME : pilot study (BMC Pediatrics)", "u": "https://bmcpediatr.biomedcentral.com/track/pdf/10.1186/s12887-015-0347-2", "f": 3}, {"c": "Neurologie", "q": "Pourquoi poser un diagnostic de PC (ou « haut risque ») avant 6 mois ?", "a": "Pour démarrer une intervention précoce pendant la période de plus forte plasticité cérébrale, soutenir les parents et surveiller les complications.", "s": "Novak et al. 2017 – Early, accurate diagnosis and early intervention in CP (JAMA Pediatrics)", "u": "https://cpresource.org/topic/early-diagnosis/early-accurate-diagnosis-and-early-intervention-cerebral-palsy-advances", "f": 3}, {"c": "Neurologie", "q": "Un ancien grand prématuré de 4 mois garde les poings fermés et une asymétrie. Décris le parcours, du repérage à l'intervention.", "a": "Ce signe d'alerte n'est pas un diagnostic. On oriente sans attendre vers une consultation dédiée, puis vers une plateforme de coordination et d'orientation si le doute persiste. Mouvements généraux, HINE et IRM permettent de conclure à un « haut risque de PC » avant 5-6 mois d'âge corrigé. L'intervention précoce démarre alors : objectifs choisis par les parents, tâches initiées par l'enfant, environnement enrichi, accompagnement à domicile.", "s": "Novak et al. 2017 – Early, accurate diagnosis and early intervention in CP (JAMA Pediatrics)", "u": "https://cpresource.org/topic/early-diagnosis/early-accurate-diagnosis-and-early-intervention-cerebral-palsy-advances", "g": 1, "f": 3}, {"c": "Neurologie", "q": "Enfant GMFCS IV-V : à partir de quand l'installer couché, assis puis debout ?", "a": "Couché dès que possible après la naissance, assis dès 6 mois, debout dès 12 mois, selon le consensus de 2006 sur la gestion posturale. La nuit compte autant que le jour.", "s": "Mac Keith Meeting 2006 (Dev Med Child Neurol) – Postural management for children with cerebral palsy: consensus statement", "u": "https://cambridge.org/core/services/aop-cambridge-core/content/view/AE89240FCAF0B5DA4431F54C316E1A9D/S0012162206000685a.pdf/postural_management_for_children_with_cerebral_palsy_consensus_statement.pdf", "f": 11}, {"c": "Neurologie", "q": "Spasticité, dystonie, athétose : différences cliniques, comment les distinguer ?", "a": "Spasticité : réflexe d'étirement vitesse-dépendant. Dystonie : contractions involontaires soutenues ou intermittentes, postures/torsions, déclenchées par mouvement, posture, émotion, fluctuantes. Athétose : mouvements lents, sinueux, continus, distaux. Chorée : brefs, rapides, irréguliers, non rythmiques. Outil : HAT (Hypertonia Assessment Tool).", "s": "Holland Bloorview – Hypertonia Assessment Tool (HAT)", "u": "https://hollandbloorview.ca/research-education/bloorview-research-institute/outcome-measures/hypertonia-assessment-tool-hat-0", "f": 8}, {"c": "Neurologie", "q": "Quelle est la définition internationale de la paralysie cérébrale ?", "a": "Groupe de troubles permanents du développement du mouvement et de la posture, limitant l'activité, attribués à des atteintes non progressives du cerveau fœtal ou du nourrisson. Souvent associés à des troubles sensoriels, cognitifs, de communication, du comportement, à une épilepsie et à des problèmes musculo-squelettiques secondaires. (Référence : Rosenbaum 2007.)", "s": "Rosenbaum et al. 2007 – Définition et classification de la PC (IAACD)", "u": "https://iaacd.net/2019/04/13/proposed-definition-and-classification-of-cerebral-palsy/", "f": 7}, {"c": "Neurologie", "q": "Quelle est la prévalence de la paralysie cérébrale ?", "a": "Environ 1,6 pour 1 000 naissances vivantes dans les pays à haut revenu (en baisse d'environ 25 % depuis 2013) et 3 à 4 pour 1 000 dans les pays à revenu faible ou intermédiaire (McIntyre 2022). C'est le handicap physique le plus fréquent de l'enfance.", "s": "McIntyre et al. 2022 – Global prevalence of cerebral palsy (résumé Cerebral Palsy Alliance)", "u": "https://cerebralpalsy.org.au/news-stories/new-research-reveals-steady-decline-in-rate-of-cerebral-palsy/", "f": 7}, {"c": "Neurologie", "q": "Quels sont les grands types cliniques de PC ?", "a": "Spastique (le plus fréquent, uni ou bilatéral), dyskinétique (dystonie, choréo-athétose) et ataxique. Des formes mixtes existent.", "s": "Rosenbaum et al. 2007 – Définition et classification de la PC (IAACD)", "u": "https://iaacd.net/2019/04/13/proposed-definition-and-classification-of-cerebral-palsy/", "f": 7}, {"c": "Neurologie", "q": "Dans la PC, quelles interventions ont le meilleur niveau de preuve (« feu vert ») ?", "a": "Notamment les approches actives orientées vers des objectifs et des tâches : CIMT, entraînement bimanuel, entraînement orienté vers les objectifs, programmes à domicile, ainsi que la toxine botulique et la surveillance de hanche. (Référence : Novak 2020.)", "s": "Novak et al. 2020 (Curr Neurol Neurosci Rep 20:3) – State of the evidence traffic lights 2019 : systematic review of interventions for children with cerebral palsy", "u": "https://doi.org/10.1007/s11910-020-1022-z", "f": 47}, {"c": "Neurologie", "q": "Que recommande la littérature : approches passives ou actives ?", "a": "Les approches actives, initiées par l'enfant, intensives et orientées vers ses objectifs fonctionnels ont le meilleur niveau de preuve. Les approches passives seules sont moins efficaces.", "s": "Novak et al. 2020 – State of the Evidence Traffic Lights 2019 (interventions dans la PC)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7035308/", "f": 47}, {"c": "Neurologie", "q": "Qu'est-ce que la gestion posturale sur 24 heures ?", "a": "Organiser les positions de l'enfant jour et nuit (couché, assis, debout) avec des équipements adaptés, pour préserver la symétrie, prévenir les déformations (hanche, rachis) et favoriser la fonction.", "s": "Evidence for 24-hour posture management: a scoping review", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12033628/", "f": 14}, {"c": "Neurologie", "q": "Quel est le niveau de preuve de la gestion posturale sur 24 heures ?", "a": "Les preuves restent limitées et hétérogènes, mais l'approche est largement recommandée en pratique, notamment chez les enfants GMFCS IV-V.", "s": "Evidence for 24-hour posture management: a scoping review", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12033628/", "f": 14}, {"c": "Neurologie", "q": "Quels sont les principes de la rééducation après un traumatisme crânien chez l'enfant ?", "a": "Prise en charge précoce et pluridisciplinaire, gestion de la fatigue, prise en compte des troubles cognitifs et comportementaux associés, objectifs fonctionnels et retour progressif à l'école.", "s": "Pediatric traumatic brain injury: medical management and physiotherapy (revue narrative)", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC11486524/", "f": 9}, {"c": "Neurologie", "q": "Quelles sont les causes fréquentes d'AVC ischémique chez l'enfant ?", "a": "Cardiopathies, artériopathies, drépanocytose, infections, troubles de la coagulation. L'AVC périnatal est souvent révélé plus tard par une préférence manuelle précoce.", "s": "Introduction to the special issue on ischemic stroke in children", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9221936/", "f": 9}, {"c": "Neurologie", "q": "Comment rééduquer une hémiparésie après un AVC de l'enfant ?", "a": "Avec les mêmes approches que la PC unilatérale : thérapie par contrainte induite, entraînement bimanuel intensif, objectifs fonctionnels.", "s": "Introduction to the special issue on ischemic stroke in children", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9221936/", "f": 9}, {"c": "Neurologie", "q": "Trisomie 21 : quels signes d'instabilité atlanto-axoïdienne doivent alerter ?", "a": "Douleurs cervicales, torticolis, modification de la marche, faiblesse ou maladresse nouvelles, troubles sphinctériens. Il faut un avis médical urgent.", "s": "JPOSNA – Orthopaedic management in Down syndrome: current concept review", "u": "https://jposna.org/index.php/jposna/article/view/283", "f": 32}, {"c": "Neurologie", "q": "Spina bifida : quelles atteintes associées connaître, et pourquoi le matériel doit-il être sans latex ?", "a": "Hydrocéphalie traitée par une dérivation, malformation de Chiari II, moelle attachée, troubles de la vessie et de l'intestin. L'allergie au latex est fréquente chez ces enfants : tout le matériel utilisé est donc sans latex.", "s": "NICHD (NIH) – Disorders and conditions associated with spina bifida", "u": "https://www.nichd.nih.gov/health/topics/spinabifida/conditioninfo/disorders-conditions", "f": 28}, {"c": "Neurologie", "q": "La PC est due à une lésion « non progressive ». Pourquoi faut-il pourtant suivre l'enfant toute sa croissance ?", "a": "La lésion cérébrale est fixe, mais ses conséquences évoluent. L'appareil locomoteur change avec la croissance : rétractions, hanches, rachis. Le suivi combine des classifications (GMFCS, MACS, CFCS), qui décrivent le profil et prédisent la trajectoire, et des mesures (GMFM), qui quantifient le changement.", "s": "Rosenbaum et al. 2007 – Définition et classification de la PC (IAACD)", "u": "https://iaacd.net/2019/04/13/proposed-definition-and-classification-of-cerebral-palsy/", "g": 1, "f": 7}, {"c": "Neurologie", "q": "Lésion cérébrale acquise : en quoi diffère-t-elle d'une PC, et pourquoi une bonne récupération motrice ne suffit-elle pas ?", "a": "Elle survient après la période néonatale, chez un enfant jusque-là en bonne santé : il y a un avant et un après. Les troubles invisibles (fatigue, attention, mémoire, fonctions exécutives, comportement) pèsent souvent plus lourd que les troubles moteurs. Un enfant « récupéré » sur le plan moteur peut rester en difficulté. Le retour à l'école se prépare, progressif, avec la famille et les enseignants.", "s": "Pediatric traumatic brain injury: medical management and physiotherapy (revue narrative)", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC11486524/", "g": 1, "f": 9}, {"c": "Neurologie", "q": "Qu'est-ce que le polyhandicap ?", "a": "Une atteinte précoce du cerveau qui associe des troubles moteurs graves, une déficience intellectuelle sévère et une extrême vulnérabilité physique, psychique et sociale (décret de 2017). Sa prévalence est d'environ 0,5 à 0,7 pour 1 000. La cause est connue dans environ 70 % des cas, le plus souvent avant la naissance.", "s": "HAS 2020 – L'accompagnement de la personne polyhandicapée dans sa spécificité (synthèse)", "u": "https://has-sante.fr/upload/docs/application/pdf/2020-11/polyhandicap_synthese_vdef.pdf", "f": 11}, {"c": "Neurologie", "q": "Enfant polyhandicapé : quel est le rôle du MK au quotidien ?", "a": "Installer l'enfant jour et nuit pour prévenir les déformations et permettre de regarder, manger et interagir. Mettre debout régulièrement. Proposer tôt une mobilité, motorisée si besoin. Choisir et revoir les appareils avec la famille. Chercher la douleur avec une échelle adaptée, en comparant au comportement habituel.", "s": "HAS 2020 – L'accompagnement de la personne polyhandicapée dans sa spécificité (synthèse)", "u": "https://has-sante.fr/upload/docs/application/pdf/2020-11/polyhandicap_synthese_vdef.pdf", "g": 1, "f": 11}, {"c": "Neurologie", "q": "Comment dépister le délire chez l'enfant en réanimation ?", "a": "Chaque jour, de l'entrée à la sortie, avec un outil validé comme la CAPD (Cornell Assessment of Pediatric Delirium). C'est une recommandation forte de PANDEM (2022). Réduire le bruit, protéger le sommeil et favoriser la présence des parents aident à le prévenir.", "s": "Smith et al. 2022 (Pediatr Crit Care Med) – PANDEM guidelines (SCCM)", "u": "https://sccm.org/clinical-resources/guidelines/guidelines/pandem-guidelines-for-infants-and-children", "f": 39}, {"c": "Neurologie", "q": "Quelle est la différence entre la GMFM et la GMFCS ?", "a": "GMFM (88 ou 66 items) : mesure critériée de la motricité globale, validée dans la PC de 5 mois à 16 ans, sensible au changement. GMFCS : classification de la motricité habituelle, cotée par le clinicien, stable et pronostique.", "s": "Shirley Ryan AbilityLab – Gross Motor Function Measure-66", "u": "https://www.sralab.org/rehabilitation-measures/gross-motor-function-measure-66", "f": 7}, {"c": "Neurologie", "q": "Mobilité motorisée : faut-il attendre que l'enfant soit « prêt » ?", "a": "Non. Elle se propose à tout enfant qui ne peut pas se déplacer et explorer seul, parfois dès l'âge du quatre-pattes. Ni un niveau cognitif ni un test de conduite ne sont des préalables. Le but est d'explorer, d'initier et de participer, pas forcément de conduire seul.", "s": "PMG UK 2014 – Best practice guidelines BPG7 : early powered mobility for children (d'après Livingstone et Paleg 2014)", "u": "https://www.pmguk.co.uk/resources/best-practice-guidelines/bpg7-early-powered-mobility", "f": 11}, {"c": "Neurologie", "q": "Quelles sont les caractéristiques du syndrome de Rett ?", "a": "Il touche surtout les filles (gène MECP2). Après un développement initial normal, une stagnation apparaît vers 6-18 mois, puis une régression entre 1 et 4 ans : perte de l'usage fonctionnel des mains et du langage, stéréotypies (« lavage de mains »), troubles de la marche, risque de scoliose.", "s": "Patient.info – Rett syndrome (critères diagnostiques révisés 2010)", "u": "https://patient.info/doctor/rett-syndrome", "f": 32}, {"c": "Neurologie", "q": "Quels objectifs de kinésithérapie dans le syndrome de Rett ?", "a": "Maintenir la marche et la mobilité le plus longtemps possible, prévenir la scoliose et les rétractions, favoriser la participation.", "s": "IDEAS – Rett syndrome : fiche d'information", "u": "https://www.ideas.org.au/facts/ndis-disability-type-rett-syndrome.html", "f": 32}, {"c": "Neurologie", "q": "Quels sont les quatre stades du syndrome de Rett ?", "a": "Stagnation précoce vers 6-18 mois. Régression rapide entre 1 et 4 ans, avec perte de l'usage des mains et du langage. Phase pseudo-stationnaire entre 2 et 10 ans. Détérioration motrice tardive.", "s": "Child Development (Australie) – Rett syndrome : stades et prise en charge", "u": "https://childdevelopment.com.au/areas-of-concern/diagnoses/rett-syndrome/", "f": 32}, {"c": "Neurologie", "q": "Station debout soutenue chez l'enfant avec une PC qui ne marche pas : quelle durée viser selon l'objectif ?", "a": "Environ 5 jours par semaine, dès 9-12 mois. Densité osseuse : 60 à 90 minutes par jour. Hanche : environ 60 minutes en abduction. Amplitudes de hanche, genou et cheville : 45 à 60 minutes. Spasticité : 30 à 45 minutes, avec un effet de courte durée. 30 minutes par jour ne suffisent pas pour protéger la hanche.", "s": "Paleg, Smith & Glickman 2013 (Pediatr Phys Ther) – Dosing of pediatric supported standing programs: systematic review and recommendations", "u": "https://braceworks.ca/wp-content/uploads/2015/09/Systematic_Review_and_Evidence_Based_Clinical.2.pdf", "f": 14}, {"c": "Neurologie", "q": "Qu'est-ce que la Mini-MACS ?", "a": "Version de la MACS adaptée aux enfants de 1 à 4 ans : elle classe en 5 niveaux la façon dont l'enfant manipule les objets au quotidien.", "s": "CanChild – Mini-MACS", "u": "https://canchild.ca/shop/mini-macs/", "f": 7}, {"c": "Neurologie", "q": "Enfant avec une PC classé GMFCS à 18 mois : ce niveau est-il définitif ?", "a": "Non. Avant 2 ans, la GMFCS est moins sûre. Dans une étude, 42 % des enfants classés vers 19 mois ont changé de niveau entre 2 et 4 ans. On peut classer tôt, mais on reclasse après 2 ans.", "s": "Gorter et al. 2009 (Dev Med Child Neurol) – Use of the GMFCS in infants with CP: the need for reclassification at age 2 years or older", "u": "https://acuresearchbank.acu.edu.au/item/87956/use-of-the-gmfcs-in-infants-with-cp-the-need-for-reclassification-at-age-2-years-or-older", "f": 46}, {"c": "Neurologie", "q": "Chez l'enfant de moins de 6 ans, pourquoi le syndrome de Guillain-Barré est-il difficile à reconnaître ?", "a": "Le tableau trompe : douleurs mal localisées, refus de marcher, irritabilité, marche instable. Un jeune enfant qui refuse de marcher et a mal aux jambes doit aussi faire penser au syndrome de Guillain-Barré, qui est une urgence hospitalière.", "s": "Leonhard et al. 2019 (Nat Rev Neurol) – Diagnosis and management of Guillain–Barré syndrome in ten steps", "u": "https://doi.org/10.1038/s41582-019-0250-9", "f": 28}, {"c": "Neurologie", "q": "Un enfant de 3 ans marche soudain de façon ébrieuse, deux semaines après une varicelle. Que suspecter, et quels signes doivent alerter ?", "a": "Une ataxie post-infectieuse, la cause la plus fréquente d'ataxie aiguë chez l'enfant, souvent avant 6 ans. Elle s'améliore en 2 à 3 semaines et guérit en général en 3 mois. Doivent faire chercher une autre cause en urgence : trouble de la conscience, céphalées et vomissements, convulsions, fièvre, raideur de nuque, signes asymétriques, début progressif ou absence d'amélioration.", "s": "PedsCases – Acute post-infectious cerebellar ataxia", "u": "https://pedscases.com/sites/default/files/Acute%20Post-Infectious%20Cerebellar%20Ataxia.pdf", "f": 30}, {"c": "Neurologie", "q": "Que classifient la MACS et la CFCS, et en quoi complètent-elles la GMFCS ?", "a": "MACS : manipulation d'objets au quotidien (Mini-MACS 1-4 ans). CFCS : efficacité de la communication. + EDACS (alimentation), VFCS (vision). Niveaux non corrélés : profil fonctionnel complet.", "s": "CanChild – Manual Ability Classification System (MACS)", "u": "https://canchild.ca/shop/macs/", "f": 7}, {"c": "Neurologie", "q": "Surveillance de hanche dans la PC : quel index, quel seuil ?", "a": "Index de migration de Reimers : % de tête fémorale non couverte. Au-delà de 30 %, la hanche est à risque : avis orthopédique. Au-delà de 40 %, la chirurgie est souvent discutée. Surveillance radiologique systématique dès 12-24 mois selon GMFCS.", "s": "AACPDM 2017 – Hip surveillance care pathway", "u": "https://www.aacpdm.org/UserFiles/file/hip-surveillance-care-pathway.pdf", "f": 14}, {"c": "Neurologie", "q": "Hémiparésie : principe de la CIMT, différence avec la HABIT ?", "a": "CIMT : contrainte du membre sain + pratique intensive. HABIT : pratique bimanuelle intensive sans contrainte (HABIT-ILE + membres inférieurs). À dose égale, efficaces toutes deux. Choix selon objectifs uni- ou bimanuels.", "s": "Novak et al. 2020 – State of the Evidence Traffic Lights 2019 (interventions dans la PC)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7035308/", "f": 10}, {"c": "Neurologie", "q": "À quelle fréquence surveiller les hanches d'un enfant avec une PC de niveau GMFCS V ?", "a": "Radiographie du bassin dès 12-24 mois, environ tous les 6 mois jusqu'à 7 ans, puis tous les ans jusqu'à la maturité osseuse si l'index de migration est stable et inférieur à 30 % (consensus australien). Le rythme exact dépend du protocole local. Le risque de luxation est maximal à ce niveau.", "s": "Wynter et al. 2008 – Consensus australien de surveillance des hanches dans la PC", "u": "https://ar.unmhealth.org/services/development-disabilities/programs/other-disability-programs/cerebral-palsy-taskforce/_media/wynter-et-al-2008.pdf", "f": 14}, {"c": "Neurologie", "q": "Comment se présente un syndrome de Guillain-Barré chez l'enfant ?", "a": "Faiblesse ascendante rapidement progressive, aréflexie, douleurs des membres, parfois atteinte respiratoire ou de déglutition. C'est une urgence hospitalière.", "s": "Texas Children's Hospital – Guillain-Barré syndrome in children", "u": "https://www.texaschildrens.org/content/conditions/guillain-barre-syndrome-children", "f": 28}, {"c": "Neurologie", "q": "Quelles précautions de kinésithérapie dans la phase aiguë d'un syndrome de Guillain-Barré ?", "a": "Surveiller la fonction respiratoire, positionner, prévenir rétractions et escarres, éviter la fatigue excessive. La récupération est généralement bonne chez l'enfant.", "s": "Texas Children's Hospital – Guillain-Barré syndrome in children", "u": "https://www.texaschildrens.org/content/conditions/guillain-barre-syndrome-children", "f": 28}, {"c": "Neurologie", "q": "L'oxygénothérapie hyperbare est-elle recommandée chez l'enfant avec une paralysie cérébrale ?", "a": "Non. Son efficacité n'est pas prouvée et elle n'est pas recommandée (consensus international). Elle expose à des risques et retarde parfois d'autres soins.", "s": "KidsHealth NZ – Cerebral palsy and hyperbaric oxygen therapy", "u": "https://kidshealth.org.nz/cerebral-palsy-hyperbaric-oxygen-therapy", "f": 47}, {"c": "Neurologie", "q": "Oxygénothérapie hyperbare dans la PC : quel effet indésirable fréquent a été rapporté ?", "a": "Le barotraumatisme de l'oreille : dans une étude, plus de la moitié des enfants ont eu besoin de drains transtympaniques (yoyos). Sont aussi décrits des fausses routes, des crises d'épilepsie et un accès retardé aux soins d'urgence en caisson.", "s": "KidsHealth NZ – Cerebral palsy and hyperbaric oxygen therapy", "u": "https://kidshealth.org.nz/cerebral-palsy-hyperbaric-oxygen-therapy", "f": 47}, {"c": "Neurologie", "q": "Pourquoi surveille-t-on les hanches d'un enfant avec une PC par radiographie régulière, et pas sur symptômes ?", "a": "Parce que la luxation progresse longtemps sans douleur. L'absence de douleur ne rassure pas. Le risque suit le niveau GMFCS : plus il est élevé, plus la surveillance est rapprochée. L'index de migration guide la décision (avis orthopédique au-delà de 30 %). La gestion posturale sur 24 heures et la station debout en abduction complètent la prévention.", "s": "Paleg, Smith & Glickman 2013 (Pediatr Phys Ther) – Dosing of pediatric supported standing programs: systematic review and recommendations", "u": "https://braceworks.ca/wp-content/uploads/2015/09/Systematic_Review_and_Evidence_Based_Clinical.2.pdf", "g": 1, "f": 14}, {"c": "Neurologie", "q": "Que décrit la VFCS ?", "a": "Elle classe en 5 niveaux l'usage de la vision dans les activités de l'enfant avec une PC. Au niveau I, il utilise sa vision facilement et avec succès. Au niveau V, il ne l'utilise pas, même dans un environnement très adapté. Elle a été validée de 1 à 19 ans.", "s": "Baranello et al. 2020 (Dev Med Child Neurol) – Visual Function Classification System for children with cerebral palsy", "u": "https://doi.org/10.1111/dmcn.14270", "f": 46}, {"c": "Neurologie", "q": "Comment la motricité globale d'un enfant avec une PC évolue-t-elle selon son niveau GMFCS ?", "a": "La GMFM-66 progresse puis atteint un plateau dont le niveau et l'âge dépendent du niveau GMFCS. L'enfant atteint environ 90 % de son potentiel moteur vers 5 ans (plus tôt pour les niveaux sévères). (Référence : courbes de Rosenbaum 2002.)", "s": "Rosenbaum et al. 2002 – Prognosis for gross motor function in CP: motor development curves (JAMA)", "u": "https://pubmed.ncbi.nlm.nih.gov/12234229/", "f": 7}, {"c": "Neurologie", "q": "Que recommande la HAS pour le tapis de marche chez l'enfant marchant avec une PC ?", "a": "Elle le recommande chez l'enfant marchant de 2 à 12 ans, pour améliorer la vitesse de marche, la longueur du pas et la motricité globale (grade B). Chez l'adolescent, les preuves sont insuffisantes. Aucune dose précise n'est fixée.", "s": "HAS 2021 – Rééducation et réadaptation de la fonction motrice de l'appareil locomoteur des personnes diagnostiquées de paralysie cérébrale (argumentaire)", "u": "https://www.has-sante.fr/upload/docs/application/pdf/2021-12/_reco355_argumentaire_paralysie_cerebrale_cd_2021_10_21_post-endossement_lg.pdf", "f": 15}, {"c": "Neurologie", "q": "Décris les 5 niveaux de la GMFCS.", "a": "I : marche sans restriction. II : marche sans aide technique mais limitée (terrain, distance, escaliers). III : marche avec aide technique manuelle, fauteuil pour les longues distances. IV : mobilité autonome très limitée, souvent fauteuil électrique. V : transporté par un tiers, contrôle tête/tronc très limité.", "s": "Palisano et al. 2007 – GMFCS-E&R (CanChild)", "u": "https://depts.washington.edu/dbpeds/Screening%20Tools/GMFCS-ER.pdf", "f": 7}, {"c": "Neurologie", "q": "Que mesurent R1 et R2 dans l'échelle de Tardieu, et comment interpréter l'écart ?", "a": "R2 : amplitude en étirement lent (longueur musculaire). R1 : angle d'accrochage en étirement rapide (spasticité). R2 − R1 grand = composante spastique (toxine). Petit avec R2 limité = rétraction (plâtres, postures, chirurgie).", "s": "Heinen et al. – The updated European Consensus 2009 on botulinum toxin in CP", "u": "https://boris.unibe.ch/182", "f": 8}, {"c": "Neurologie", "q": "Toxine botulique et plâtres successifs : quelle différence, et pourquoi les associer ?", "a": "Toxine : bloque l'acétylcholine à la jonction neuromusculaire, réduit la spasticité. Plâtres : allongent le complexe muscle-tendon (surtout le muscle). Plâtre souvent 1-2 semaines après l'injection : mieux toléré et plus efficace.", "s": "Heinen et al. – The updated European Consensus 2009 on botulinum toxin in CP", "u": "https://boris.unibe.ch/182", "f": 8}, {"c": "Neurologie", "q": "Ashworth modifiée vs Tardieu : différence, et pourquoi préférer Tardieu chez l'enfant ?", "a": "Ashworth : résistance cotée 0-4 à une seule vitesse, ne distingue pas spasticité/rétraction, reproductibilité médiocre chez l'enfant. Tardieu : vitesse standardisée, R1/R2, recommandée par les consensus internationaux sur la toxine dans la PC.", "s": "Heinen et al. – The updated European Consensus 2009 on botulinum toxin in CP", "u": "https://boris.unibe.ch/182", "f": 8}, {"c": "Neurologie", "q": "Pourquoi le niveau GMFCS est-il un outil pronostique ?", "a": "Il est relativement stable dans le temps et prédit la trajectoire motrice et la mobilité future, notamment la marche (courbes de Rosenbaum).", "s": "Rosenbaum et al. 2002 – Prognosis for gross motor function in CP: motor development curves (JAMA)", "u": "https://pubmed.ncbi.nlm.nih.gov/12234229/", "f": 7}, {"c": "Neurologie", "q": "Toxine botulique : délai d'action et durée d'effet ?", "a": "L'effet apparaît en quelques jours, culmine vers 2 à 4 semaines et dure environ 3 à 6 mois. L'intervalle minimal entre deux injections est de 3 mois. Le consensus international de 2010 recommande plutôt d'espacer les réinjections d'au moins 6 mois dans la PC.", "s": "Love et al. 2010 – BoNT assessment, intervention and after-care for lower limb spasticity in children with CP: international consensus", "u": "https://lirias.kuleuven.be/retrieve/438467", "f": 8}, {"c": "Neurologie", "q": "Quels muscles du membre inférieur sont les plus souvent injectés en toxine dans la PC ?", "a": "Triceps sural (gastrocnémiens surtout), ischio-jambiers, adducteurs, parfois psoas, selon l'analyse de la marche et les objectifs.", "s": "Heinen et al. – The updated European Consensus 2009 on botulinum toxin in CP", "u": "https://boris.unibe.ch/182", "f": 8}, {"c": "Neurologie", "q": "Quel est le rôle du MK après une injection de toxine ?", "a": "Exploiter la fenêtre d'effet : étirements, orthèses ou plâtres, renforcement des antagonistes et entraînement moteur orienté vers les objectifs. La toxine seule, sans rééducation, a peu d'effet fonctionnel.", "s": "Heinen et al. – The updated European Consensus 2009 on botulinum toxin in CP", "u": "https://boris.unibe.ch/182", "f": 8}, {"c": "Neurologie", "q": "Hippothérapie dans la PC : quel principe, et pour quels résultats les preuves sont-elles les meilleures ?", "a": "Le pas du cheval transmet au bassin de l'enfant un mouvement en trois dimensions proche de celui de la marche, qui sollicite le contrôle postural. Novak (2020) la classe en vert pour l'équilibre et la symétrie posturale, en jaune (effet probable, preuves limitées) pour la motricité globale et la fonction de la main. Les études restent de taille modeste.", "s": "Novak et al. 2020 (Curr Neurol Neurosci Rep 20:3) – State of the evidence traffic lights 2019 : systematic review of interventions for children with cerebral palsy", "u": "https://doi.org/10.1007/s11910-020-1022-z", "f": 47}, {"c": "Neurologie", "q": "Les combinaisons de type TheraSuit ou Adeli (suit therapy) font-elles mieux qu'une rééducation classique de même intensité ?", "a": "Non démontré. La méta-analyse de Martins (2016) retrouve au mieux un petit effet sur la fonction motrice globale, sans différence avec une rééducation de même intensité. C'est l'intensité de l'entraînement qui semble compter.", "s": "Martins et al. 2016 – Efficacy of suit therapy on functioning in children and adolescents with CP: systematic review and meta-analysis", "u": "https://lcm.fmh.ulisboa.pt/publicacoes/artigos/item/138-efficacy-of-suit-therapy-on-functioning-in-children-and-adolescents-with-cerebral-palsy-a-systematic-review-and-meta-analysis", "f": 47}, {"c": "Neurologie", "q": "Les vibrations corps entier peuvent-elles remplacer la rééducation chez l'enfant avec une paralysie cérébrale ?", "a": "Non. Elles sont étudiées en complément (« additionnelles ») d'une rééducation, et les effets rapportés sur le système musculosquelettique restent modestes et de certitude limitée.", "s": "Méta-analyse – Additional whole-body vibration on musculoskeletal system in children with CP", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10648882/", "f": 47}, {"c": "Neurologie", "q": "Quels sont les principes de la HABIT-ILE ?", "a": "Une thérapie bimanuelle intensive qui engage aussi les membres inférieurs et le contrôle postural : l'enfant manipule à deux mains assis sur un ballon, debout, sur un plateau d'équilibre ou en marchant. Environ 90 heures sur 2 semaines, en petits groupes, avec au moins un intervenant par enfant. Elle applique les principes de l'apprentissage moteur : pratique structurée de difficulté croissante, engagement moteur élevé, résolution active de problèmes. Les objectifs fonctionnels sont fixés avec l'enfant et ses parents (COPM). Dans la PC unilatérale, elle améliore le membre supérieur autant que la HABIT, avec un gain supplémentaire en autonomie et sur les objectifs personnels.", "s": "Saussez, Brandão, Gordon & Bleyenheuft 2017 (Front Neurol) – HABIT-ILE versus HABIT in unilateral CP", "u": "https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2017.00495/pdf", "f": 10}, {"c": "Neurologie", "q": "Après un syndrome de Guillain-Barré, l'enfant reste très fatigué. Que proposer ?", "a": "Un programme d'exercice progressif et supervisé, qui réduit la fatigue. Elle touche 60 à 80 % des patients. On surveille l'intensité pour ne pas épuiser. La récupération est généralement meilleure chez l'enfant et peut se poursuivre au-delà d'un an.", "s": "Leonhard et al. 2019 (Nat Rev Neurol) – Diagnosis and management of Guillain–Barré syndrome in ten steps", "u": "https://doi.org/10.1038/s41582-019-0250-9", "f": 28}, {"c": "Neurologie", "q": "Syndrome de Rett, phase pseudo-stationnaire : qu'est-ce qui s'améliore souvent, et comment en tenir compte en séance ?", "a": "La communication par le regard s'améliore souvent. L'apraxie et les troubles moteurs persistent. Le MK propose donc les exercices en s'appuyant sur le regard. Le bilan suit aussi la marche, l'équilibre, l'usage des mains et le rachis, car le risque de scoliose est élevé.", "s": "Child Development (Australie) – Rett syndrome : stades et prise en charge", "u": "https://childdevelopment.com.au/areas-of-concern/diagnoses/rett-syndrome/", "f": 32}, {"c": "Neurologie", "q": "Avant de traiter une « hypertonie », quelles questions faut-il se poser pour choisir le traitement ?", "a": "Quel trouble du tonus (spasticité, dystonie, rigidité) ? Quelle distribution ? Quelle part dynamique ou fixée (écart R2 − R1 à la Tardieu) ? Quel niveau GMFCS ? Quels objectifs ? Spasticité focale et dynamique : toxine et rééducation. Spasticité bilatérale, GMFCS II-III, bonne sélectivité : rhizotomie discutée. Atteinte généralisée sévère : baclofène intrathécal. Rétraction fixée : plâtres puis chirurgie. Une dystonie ne se traite pas comme une spasticité.", "s": "Love et al. 2010 – BoNT assessment, intervention and after-care for lower limb spasticity in children with CP: international consensus", "u": "https://lirias.kuleuven.be/retrieve/438467", "g": 1, "f": 8}, {"c": "Neurologie", "q": "Quels sont les critères de sélection habituels pour une rhizotomie dorsale sélective ?", "a": "PC spastique bilatérale (diplégie), GMFCS II-III, spasticité gênante sans dystonie, bonne force et bonne sélectivité motrice, peu de rétractions fixes, famille prête à plusieurs mois de rééducation intensive. Les données portent surtout sur les enfants de 4 à 10 ans (NICE). La sélection se fait en équipe spécialisée.", "s": "NICE HTG245 (2010, maintenu en 2026) – Selective dorsal rhizotomy for spasticity in cerebral palsy", "u": "https://www.nice.org.uk/guidance/htg245/resources/selective-dorsal-rhizotomy-for-spasticity-in-cerebral-palsy-pdf-1809589881086917", "f": 8}, {"c": "Neurologie", "q": "Pourquoi la rééducation après rhizotomie est-elle longue et intensive ?", "a": "La réduction de la spasticité démasque une faiblesse musculaire sous-jacente. Il faut plusieurs mois de renforcement et de réentraînement fonctionnel pour transformer le gain de tonus en gain moteur.", "s": "D'Agostini et al. – Selective dorsal rhizotomy in CP: selection criteria and postoperative PT", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5849370/", "f": 8}, {"c": "Neurologie", "q": "Qu'est-ce que la sélectivité motrice ? Une échelle au membre inférieur ?", "a": "Capacité à contracter un muscle isolément, sans synergie de masse. Échelles : SCALE (Selective Control Assessment of the Lower Extremity, Fowler 2009), test de Boyd et Graham.", "s": "Fowler et al. 2009 – SCALE : reliability and validity (DMCN)", "u": "https://www.uclahealth.org/sites/default/files/documents/SCALE-reliability-and-validity_DMCN-Aug2009.pdf", "f": 8}, {"c": "Neurologie", "q": "Comment est cotée l'échelle SCALE ?", "a": "Elle teste 5 articulations par membre inférieur (hanche, genou, cheville, sous-talienne, orteils), cotées 0, 1 ou 2, soit un score maximal de 10 par membre.", "s": "Fowler et al. 2009 – SCALE : reliability and validity (DMCN)", "u": "https://www.uclahealth.org/sites/default/files/documents/SCALE-reliability-and-validity_DMCN-Aug2009.pdf", "f": 8}, {"c": "Neurologie", "q": "Oncologie pédiatrique : quelle complication neurologique de la chimiothérapie retentit sur la marche, et que suit le bilan ?", "a": "Une neuropathie périphérique, avec une faiblesse des releveurs et une raideur de cheville. Le bilan suit la dorsiflexion de cheville, la force, l'équilibre et l'endurance (test de marche de 6 minutes).", "s": "Exercise and childhood cancer: a historical review", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC8750946/", "f": 31}, {"c": "Neurologie", "q": "Que décrit l'EDACS, et sur quels deux critères repose-t-elle ?", "a": "Elle classe en 5 niveaux la façon de manger et de boire de la personne avec une PC, dès 3 ans. Elle repose sur la sécurité (risque de fausse route) et l'efficacité (temps, pertes d'aliments ou de liquide). Un enfant lent mais sûr est au niveau II. La Mini-EDACS couvre les 18 à 36 mois.", "s": "Sellers et al. 2014 (Dev Med Child Neurol) – Eating and Drinking Ability Classification System (EDACS)", "u": "https://eprints.ncl.ac.uk/203566", "f": 46}, {"c": "Neurologie", "q": "MACS et BFMF : quelle différence ?", "a": "Toutes deux classent en 5 niveaux l'usage des mains dans la PC. La MACS décrit la performance : ce que l'enfant fait d'habitude avec ses deux mains au quotidien, selon quelqu'un qui le connaît bien. La BFMF décrit la capacité des deux mains, observée sur une courte vidéo.", "s": "Elvrum et al. 2017 (Phys Occup Ther Pediatr) – Bimanual capacity of children with CP: reliability of the BFMF 2", "u": "https://pubmed.ncbi.nlm.nih.gov/27563732/", "f": 46}, {"c": "Neurologie", "q": "Rhizotomie dorsale sélective et baclofène intrathécal : principe et profil d'enfant ?", "a": "Rhizotomie : section de radicelles sensitives L2-S1, réduction définitive de la spasticité sans paralysie. PC bilatérale GMFCS II-III, spasticité pure, données surtout chez les 4-10 ans. Baclofène : pompe GABA-B continue, réglable et réversible. Spasticité sévère et/ou dystonie généralisées, souvent GMFCS IV-V.", "s": "D'Agostini et al. – Selective dorsal rhizotomy in CP: selection criteria and postoperative PT", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5849370/", "f": 8}, {"c": "Neurologie", "q": "Qu'est-ce que le test de Duncan-Ely, et qu'évalue-t-il ?", "a": "Décubitus ventral, flexion rapide du genou : si les fesses se soulèvent, test positif = spasticité ou rétraction du droit fémoral. Utilisé dans la marche genou raide (stiff-knee gait).", "s": "Marks et al. 2003 – Clinical utility of the Duncan-Ely test (DMCN)", "u": "https://pubmed.ncbi.nlm.nih.gov/14580132/", "f": 13}, {"c": "Neurologie", "q": "La MACS évalue-t-elle la meilleure capacité de la main atteinte ?", "a": "Non. Elle classe la performance habituelle des deux mains ensemble dans les activités quotidiennes, en 5 niveaux, de 4 à 18 ans.", "s": "CanChild – Manual Ability Classification System (MACS)", "u": "https://canchild.ca/shop/macs/", "f": 7}, {"c": "Neurologie", "q": "Que permet l'outil HAT (Hypertonia Assessment Tool) ?", "a": "Différencier cliniquement spasticité, dystonie et rigidité chez l'enfant, grâce à une série d'items simples à l'examen.", "s": "Holland Bloorview – Hypertonia Assessment Tool (HAT)", "u": "https://hollandbloorview.ca/research-education/bloorview-research-institute/outcome-measures/hypertonia-assessment-tool-hat-0", "f": 8}, {"c": "Neurologie", "q": "Robot de marche sur tapis (type Lokomat) dans la PC : fait-il mieux que la marche sans robot ?", "a": "Ce n'est pas démontré. La HAS juge les preuves insuffisantes pour le préférer à la marche sans robot chez les enfants GMFCS I à III. Une méta-analyse en réseau ne trouve pas de différence avec la kinésithérapie seule, que ce soit pour la marche, la vitesse ou l'endurance.", "s": "Olmos-Gómez et al. 2021 (J Clin Med) – Effects of robotic-assisted gait training in children and adolescents with cerebral palsy: a network meta-analysis", "u": "https://mdpi.com/2077-0383/10/21/4908/htm", "f": 15}, {"c": "Neurologie", "q": "Trouble neurologique fonctionnel de l'enfant : de quoi s'agit-il, et l'enfant simule-t-il ?", "a": "Ce sont des symptômes neurologiques réels (faiblesse, trouble de la marche, mouvements anormaux, crises) liés à un fonctionnement perturbé du système nerveux, sans lésion. L'enfant ne simule pas. Ils représentent jusqu'à 10 % des consultations de neurologie pédiatrique.", "s": "Vassilopoulos et al. 2022 (Curr Treat Options Neurol) – Treatment approaches for functional neurological disorders in children", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8958484", "f": 12}, {"c": "Neurologie", "q": "Pourquoi dit-on que le diagnostic d'un trouble neurologique fonctionnel est positif ?", "a": "Parce qu'il repose sur des signes propres, pas seulement sur des examens normaux : mouvement qui change quand l'attention s'en détourne, faiblesse qui ne suit pas un trajet neurologique, mouvement anormal qui disparaît quand l'enfant est distrait.", "s": "Vassilopoulos et al. 2022 (Curr Treat Options Neurol) – Treatment approaches for functional neurological disorders in children", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8958484", "f": 12}, {"c": "Neurologie", "q": "Trouble neurologique fonctionnel : quels principes guident la kinésithérapie ?", "a": "Une approche biopsychosociale et sans jugement, dans une équipe pluridisciplinaire. On explique le trouble, on travaille l'attention portée au mouvement et les schémas anormaux, on passe par le mouvement automatique (jeu, musique, double tâche) et on progresse vers des objectifs concrets.", "s": "Nielsen et al. 2015 (J Neurol Neurosurg Psychiatry) – Physiotherapy for functional motor disorders: a consensus recommendation", "u": "https://s4me.info/threads/physiotherapy-for-functional-motor-disorders-a-consensus-recommendation-2015-nielsen-et-al.22377/post-374097", "f": 12}, {"c": "Neurologie", "q": "Quel est le pronostic des troubles neurologiques fonctionnels de l'enfant ?", "a": "Plutôt bon. Dans les programmes pluridisciplinaires spécialisés, les symptômes disparaissent chez 63 à 95 % des enfants, et environ deux tiers reprennent l'école à temps plein. Des difficultés psychiques persistantes s'associent à un moins bon résultat.", "s": "Kim et al. 2022 (Semin Pediatr Neurol) – The role of physiotherapy in the management of functional neurological disorder in children and adolescents", "u": "https://www.iasp-pain.org/publications/pain-research-forum/papers-of-the-week/paper/195619-role-physiotherapy-management-functional-neurological-disorder-children-and", "f": 12}, {"c": "Neurologie", "q": "Un adolescent ne marche plus depuis une semaine, examens normaux, signe de Hoover positif. Comment le MK l'aide-t-il ?", "a": "Il s'appuie sur un diagnostic positif expliqué clairement : un trouble réel, sans simulation, qui peut guérir. Il travaille en équipe avec le psychologue, la famille et l'école. En séance, il passe par le mouvement automatique et des activités que l'adolescent aime, et progresse vers des objectifs concrets comme le retour à l'école.", "s": "Vassilopoulos et al. 2022 (Curr Treat Options Neurol) – Treatment approaches for functional neurological disorders in children", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8958484", "g": 1, "f": 12}, {"c": "Neurologie", "q": "Ataxie dégénérative de l'enfant : la rééducation peut-elle encore apporter quelque chose ?", "a": "Oui. Un entraînement intensif de la coordination et de l'équilibre peut diminuer le score d'ataxie. Chez 10 enfants, 8 semaines de jeux vidéo actifs, en grande partie à la maison, ont fait baisser le score SARA d'environ 2 points. Les gains se perdent si l'entraînement s'arrête.", "s": "Ilg et al. 2012 (Neurology) – Video game-based coordinative training improves ataxia in children with degenerative ataxia", "u": "https://www.compsens.uni-tuebingen.de/compsens//files/publications/Neurology-2012-Ilg-WNL.0b013e3182749e67.pdf", "f": 30}, {"c": "Analyse de la marche", "q": "Tapis, robot de marche, exosquelette : pour quels enfants, et avec quelles preuves ?", "a": "Le tapis a deux indications solides : avancer la marche dans la trisomie 21, et améliorer vitesse et motricité globale chez l'enfant PC marchant (HAS grade B, vert chez Novak). Le robot sur tapis ne fait pas mieux que la marche sans robot à dose égale. L'exosquelette portable est prometteur, surtout chez l'enfant très atteint, mais encore peu prouvé. Dans tous les cas, on mesure l'effet hors de l'appareil.", "s": "HAS 2021 – Rééducation et réadaptation de la fonction motrice de l'appareil locomoteur des personnes diagnostiquées de paralysie cérébrale (argumentaire)", "u": "https://www.has-sante.fr/upload/docs/application/pdf/2021-12/_reco355_argumentaire_paralysie_cerebrale_cd_2021_10_21_post-endossement_lg.pdf", "g": 1, "f": 15}, {"c": "Analyse de la marche", "q": "À quel âge la marche de l'enfant atteint-elle une maturité proche de l'adulte ?", "a": "Le contact talon et le balancement alterné des bras apparaissent vers 18 mois-2 ans. Vers 3 ans, la marche ressemble déjà à celle de l'adulte. Vers 7 ans, les différences restantes tiennent surtout à la taille.", "s": "Paediatric Musculoskeletal Matters – Walking (développement normal de la marche)", "u": "https://www.pmmonline.org/nurse/healthy-child/walking/", "f": 13}, {"c": "Analyse de la marche", "q": "Inégalité de longueur vraie ou apparente : comment les distinguer ?", "a": "L'inégalité vraie vient de la longueur des os. L'inégalité apparente vient d'une rétraction ou d'une instabilité : flessum de hanche ou de genou, équin. En clinique, on cale le pied court jusqu'à mettre le bassin à l'horizontale. La radiographie en charge mesure la longueur et l'axe.", "s": "Dayton Children's Hospital 2018 – Management of pediatric lower limb length inequality", "u": "https://childrensdayton.org/research-and-innovation/management-pediatric-lower-limb-length-inequality/", "f": 16}, {"c": "Analyse de la marche", "q": "Quels sont les principaux schémas de marche dans la PC spastique bilatérale ?", "a": "Rodda et Graham : équin vrai, marche en sautillement (jump gait), équin apparent, marche en triple flexion (crouch gait) (+ marche asymétrique). PC unilatérale : classification de Winters (types I à IV).", "s": "Rodda et Graham 2004 – Sagittal gait patterns in spastic diplegia (JBJS Br)", "u": "https://boneandjoint.org.uk/Article/10.1302/0301-620X.86B2.13878", "f": 13}, {"c": "Analyse de la marche", "q": "Enfant PC sur la pointe, mais cheville à 90° genou tendu en décubitus : quel schéma, quelle erreur éviter ?", "a": "Équin apparent : cheville normale, pointe due à la flexion de hanche et genou. Ne pas traiter le triceps (allongement, toxine, plâtres), sinon bascule en triple flexion. Cibler genou/hanche, renforcer soléaire et quadriceps.", "s": "Kim et al. 2011 – Visual classification of sagittal gait patterns in bilateral CP", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3309223", "f": 13}, {"c": "Analyse de la marche", "q": "Phases du cycle de marche et pourcentages approximatifs ?", "a": "Appui ~60 % : contact initial et mise en charge 0-10 % (double appui), milieu d'appui 10-30 %, fin d'appui 30-50 %, pré-oscillation 50-60 % (double appui). Oscillation ~40 % : initiale, milieu, terminale. Genou légèrement fléchi au contact, fléchit de 15-20° en mise en charge.", "s": "Perry J. – Gait Analysis: Normal and Pathological Function, 2e éd. (sommaire)", "u": "https://aaot.org.ar/wp-content/uploads/2026/07/Perry-J.-Gait-analysis.-Normal-and-pathological-function.-2nd-ed.-Slack-2010-Indice.pdf", "f": 13}, {"c": "Analyse de la marche", "q": "Les trois pivots de la cheville, et lequel est perturbé dans l'équin ?", "a": "1er pivot talonnier (contact talon → pied à plat, releveurs en excentrique). 2e pivot de cheville (tibia avance sur pied fixe, soléaire en excentrique). 3e pivot de l'avant-pied (décollement du talon, propulsion). Équin : 1er pivot absent, 2e perturbé (talon qui redescend ou recul du tibia → recurvatum).", "s": "Perry J. – Gait Analysis: Normal and Pathological Function, 2e éd. (sommaire)", "u": "https://aaot.org.ar/wp-content/uploads/2026/07/Perry-J.-Gait-analysis.-Normal-and-pathological-function.-2nd-ed.-Slack-2010-Indice.pdf", "f": 13}, {"c": "Analyse de la marche", "q": "Qu'est-ce que l'Edinburgh Visual Gait Score, et à quoi sert-il ?", "a": "Analyse vidéo de 17 paramètres par membre, cotés 0-1-2 (max 34 par membre, 0 = normal). Alternative clinique à l'analyse 3D, suivi avant/après traitement. Une différence d'environ 3 points par membre est considérée cliniquement significative.", "s": "Ramdharry et al. – Feasibility of the Edinburgh Visual Gait Score", "u": "https://eprints.kingston.ac.uk/40010/1/Ramdharry-G-40010-AAM.pdf", "f": 13}, {"c": "Analyse de la marche", "q": "Couple flexion plantaire / extension du genou : pourquoi un triceps trop allongé aggrave la marche en triple flexion ?", "a": "Le soléaire (mono-articulaire) freine l'avancée du tibia en milieu d'appui et garde la force de réaction du sol devant le genou : extension passive du genou. Les gastrocnémiens sont fléchisseurs du genou. Triceps trop long/faible → tibia part en avant → genou fléchit → quadriceps surchargé → triple flexion.", "s": "Effects of AFOs on gait patterns in spastic bilateral CP: a scoping review", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8534539/", "f": 13}, {"c": "Analyse de la marche", "q": "Quel est le rôle des releveurs du pied pendant la marche ?", "a": "En oscillation, ils assurent le passage du pied. Au contact initial, ils freinent la descente du pied. Leur faiblesse entraîne un pied tombant et un steppage.", "s": "Perry J. – Gait Analysis: Normal and Pathological Function, 2e éd. (sommaire)", "u": "https://aaot.org.ar/wp-content/uploads/2026/07/Perry-J.-Gait-analysis.-Normal-and-pathological-function.-2nd-ed.-Slack-2010-Indice.pdf", "f": 13}, {"c": "Analyse de la marche", "q": "Quels traitements pour un équin vrai dans la PC ?", "a": "Selon la part dynamique ou fixe : toxine, plâtres successifs, orthèses cheville-pied, et allongement chirurgical si la rétraction est fixée.", "s": "Rodda et Graham 2004 – Sagittal gait patterns in spastic diplegia (JBJS Br)", "u": "https://boneandjoint.org.uk/Article/10.1302/0301-620X.86B2.13878", "f": 13}, {"c": "Analyse de la marche", "q": "Qu'est-ce que la marche en sautillement (jump gait) ?", "a": "Un schéma avec équin de cheville associé à une flexion excessive du genou et de la hanche en début d'appui, puis une extension en fin d'appui.", "s": "Rodda et Graham 2004 – Sagittal gait patterns in spastic diplegia (JBJS Br)", "u": "https://boneandjoint.org.uk/Article/10.1302/0301-620X.86B2.13878", "f": 13}, {"c": "Analyse de la marche", "q": "Orthèse cheville-pied rigide ou articulée : quelles indications ?", "a": "La rigide bloque la cheville (contrôle global, triple flexion). L'articulée autorise la dorsiflexion tout en limitant la flexion plantaire : utile si l'amplitude passive en dorsiflexion est suffisante.", "s": "Effects of AFOs on gait patterns in spastic bilateral CP: a scoping review", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8534539/", "f": 13}, {"c": "Analyse de la marche", "q": "Quels effets des orthèses cheville-pied sur la marche dans la PC bilatérale ?", "a": "Elles améliorent surtout la cinématique de la cheville, la longueur du pas et la vitesse. L'effet dépend du type d'orthèse et du schéma de marche.", "s": "Effects of AFOs on gait patterns in spastic bilateral CP: a scoping review", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8534539/", "f": 13}, {"c": "Analyse de la marche", "q": "Quand préférer une analyse 3D de la marche à une analyse vidéo (EVGS) ?", "a": "Avant une décision lourde, comme une chirurgie multisite. L'EVGS est une alternative clinique fiable quand l'analyse 3D n'est pas disponible ou pour le suivi courant.", "s": "Ramdharry et al. – Feasibility of the Edinburgh Visual Gait Score", "u": "https://eprints.kingston.ac.uk/40010/1/Ramdharry-G-40010-AAM.pdf", "f": 13}, {"c": "Analyse de la marche", "q": "Quels traitements pour une marche idiopathique sur la pointe des pieds ?", "a": "Selon l'âge et la rétraction : surveillance, étirements, plâtres successifs, orthèses, parfois toxine, et allongement chirurgical si la rétraction est fixe.", "s": "Toe walking: causes, epidemiology, assessment and treatment (revue)", "u": "https://vivo.weill.cornell.edu/display/pubid26709689", "f": 13}, {"c": "Analyse de la marche", "q": "Quelle est la cause la plus fréquente de marche pieds en dedans (in-toeing) chez l'enfant d'âge scolaire ?", "a": "L'antéversion fémorale excessive, souvent familiale, qui se corrige spontanément dans la majorité des cas.", "s": "AAFP 2011 – Managing intoeing in children", "u": "https://www.aafp.org/afp/2011/1015/p937", "f": 18}, {"c": "Analyse de la marche", "q": "Pourquoi observer, mesurer et résumer la marche avant de décider d'un traitement ?", "a": "Un même signe a plusieurs causes : une marche sur la pointe peut être un équin vrai ou un équin apparent dû au genou fléchi. L'examen clinique (Silfverskiöld) et l'observation, vidéo (EVGS) ou 3D, identifient le mécanisme. Un indice global (GDI, GPS) résume la marche, mais ne dit pas quelle articulation traiter. Se tromper coûte cher : allonger isolément le triceps peut créer une marche en triple flexion.", "s": "Rodda et al. 2004 (J Bone Joint Surg Br) – Sagittal gait patterns in spastic diplegia", "u": "https://braceworks.ca/wp-content/uploads/2012/06/rodda_sagittalgaitpatterns.pdf", "g": 1, "f": 13}, {"c": "Analyse de la marche", "q": "Marche en triple flexion (crouch gait) : mécanismes, et rôle des orthèses de type GRAFO ?", "a": "Triceps sural faible ou trop long (souvent post-allongement isolé), ischio-jambiers courts, flessum de hanche, faiblesse quadriceps, troubles des bras de levier (torsion tibiale externe, pied plat valgus, antéversion), patella alta, croissance. GRAFO : bloque l'avancée du tibia → force de réaction devant le genou → moment extenseur. Si flessum fixe ≤ ~15° et leviers alignés.", "s": "Effects of AFOs on gait patterns in spastic bilateral CP: a scoping review", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8534539/", "f": 13}, {"c": "Analyse de la marche", "q": "Qu'est-ce qu'une marche genou raide (stiff-knee gait) ?", "a": "Un défaut de flexion du genou en oscillation, souvent lié à une activité anormale du droit fémoral. Il gêne le passage du pied. On l'évalue avec le test de Duncan-Ely et l'analyse de la marche.", "s": "Marks et al. 2003 – Clinical utility of the Duncan-Ely test (DMCN)", "u": "https://pubmed.ncbi.nlm.nih.gov/14580132/", "f": 13}, {"c": "Analyse de la marche", "q": "Marche en triple flexion dans la PC : qu'a apporté un exosquelette qui assiste l'extension du genou ?", "a": "Chez 7 enfants et jeunes marchant sans aide, l'extension du genou a gagné environ 13° en 6 séances, avec des pas plus longs et sans chute. L'assistance arrive au bon moment du pas, et l'enfant continue d'utiliser ses propres muscles. C'est une petite étude, à confirmer.", "s": "Lerner, Damiano & Bulea 2017 (Sci Transl Med) – A lower-extremity exoskeleton improves knee extension in children with crouch gait from cerebral palsy", "u": "https://directorsblog.nih.gov/2017/09/05/robotic-exoskeleton-could-be-right-step-forward-for-kids-with-cerebral-palsy/", "f": 15}, {"c": "Orthopédie", "q": "Ortolani et Barlow : que testent-elles, et jusqu'à quel âge sont-elles fiables ?", "a": "Barlow : hanche luxable (adduction + poussée postérieure, ressaut de sortie). Ortolani : hanche luxée réductible (abduction + pression trochanter, ressaut d'entrée). Fiables jusqu'à ~2-3 mois. Ensuite limitation d'abduction, asymétrie des plis, Galeazzi.", "s": "HAS 2013 – Luxation congénitale de la hanche : dépistage", "u": "https://www.has-sante.fr/upload/docs/application/pdf/2013-11/luxation_hanche_v2_mel.pdf", "f": 17}, {"c": "Orthopédie", "q": "Quels nourrissons doivent avoir une échographie de hanche selon la HAS ?", "a": "Ceux avec un examen clinique anormal (échographie en urgence) ou des facteurs de risque : présentation en siège, antécédent familial au 1er degré, anomalie orthopédique posturale (torticolis, genu recurvatum, déformation du pied). L'échographie se fait alors vers 1 mois.", "s": "HAS 2013 – Luxation congénitale de la hanche : dépistage", "u": "https://www.has-sante.fr/upload/docs/application/pdf/2013-11/luxation_hanche_v2_mel.pdf", "f": 17}, {"c": "Orthopédie", "q": "Quel est le traitement d'une luxation de hanche chez le jeune nourrisson ?", "a": "Avant 6 mois, une hanche instable ou dysplasique (Graf IIb à IV) se traite par une orthèse en flexion-abduction, le plus souvent un harnais de Pavlik, avec une échographie de contrôle toutes les deux semaines environ. Les taux de succès publiés vont de 70 à 95 %. En cas d'échec, réduction sous anesthésie et plâtre.", "s": "AAOS – CPG Pediatric developmental dysplasia of the hip", "u": "https://www.aaos.org/quality/quality-programs/pediatric-developmental-dysplasia-of-the-hip/", "f": 17}, {"c": "Orthopédie", "q": "Torticolis musculaire congénital : muscle en cause, attitude, prise en charge ?", "a": "Sterno-cléido-mastoïdien. Inclinaison homolatérale + rotation controlatérale. Étirements doux, positionnement, tummy time, guidance parentale. Rechercher plagiocéphalie et dysplasie de hanche. Chirurgie si échec après ~12 mois.", "s": "Kaplan et al. 2018 – APTA CPG : kinésithérapie du torticolis musculaire congénital", "u": "https://pubmed.ncbi.nlm.nih.gov/30277962/", "f": 4}, {"c": "Orthopédie", "q": "Comment distinguer une plagiocéphalie positionnelle d'une craniosténose ?", "a": "Vue de dessus. Positionnelle : parallélogramme, oreille homolatérale avancée, bosse frontale homolatérale. Synostose lambdoïde : trapèze, oreille homolatérale reculée et abaissée, bosse mastoïdienne, front peu touché.", "s": "Laughlin et al. 2011 (AAP) – Prevention and management of positional skull deformities in infants", "u": "https://pure.psu.edu/en/publications/prevention-and-management-of-positional-skull-deformities-in-infa/", "f": 4}, {"c": "Orthopédie", "q": "Comment se traite un metatarsus adductus ?", "a": "La plupart des formes souples se corrigent spontanément. Les formes rigides peuvent nécessiter étirements ou plâtres.", "s": "AAFP 2011 – Managing intoeing in children", "u": "https://www.aafp.org/afp/2011/1015/p937", "f": 18}, {"c": "Orthopédie", "q": "Torticolis congénital : comment évaluer la force des muscles inclinateurs du cou ?", "a": "Avec l'échelle MFS (Muscle Function Scale). Le nourrisson est tenu en suspension latérale et l'on observe comment il redresse la tête contre la pesanteur, des deux côtés.", "s": "APTA 2018 – Physical therapy management of congenital muscular torticollis (résumé)", "u": "https://www.guidelinecentral.com/guideline/8564", "f": 4}, {"c": "Orthopédie", "q": "Selon l'APTA, à quoi sert le grade de sévérité d'un torticolis congénital ?", "a": "L'APTA classe le torticolis en 8 grades, selon l'âge à la première prise en charge, la forme et le déficit de rotation. Ce grade guide le pronostic et le rythme des séances.", "s": "APTA 2018 – Physical therapy management of congenital muscular torticollis (résumé)", "u": "https://www.guidelinecentral.com/guideline/8564", "f": 4}, {"c": "Orthopédie", "q": "Plagiocéphalie positionnelle légère à modérée : la kinésithérapie apporte-t-elle plus que de simples conseils aux parents ?", "a": "Oui. Le repositionnement associé à la kinésithérapie est le traitement de choix. Dans un essai randomisé, la kinésithérapie faisait mieux que des conseils seuls aux parents. L'orthèse crânienne ne vient qu'en second.", "s": "van Vlimmeren et al. 2008 (Arch Pediatr Adolesc Med) – Effect of pediatric physical therapy on deformational plagiocephaly in children with positional preference: RCT", "u": "https://research.utwente.nl/en/publications/effect-of-pediatric-physical-therapy-on-deformational-plagiocepha/", "f": 4}, {"c": "Orthopédie", "q": "Pourquoi torticolis et plagiocéphalie se prennent-ils en charge ensemble, et dans quel ordre viennent les mesures ?", "a": "Une tête qui tourne toujours du même côté s'aplatit, et un crâne aplati entretient la position préférentielle. On agit tôt sur les deux : dormir sur le dos, jouer sur le ventre, varier les positions. Pour le torticolis : étirements doux, renforcement, positionnement, guidance parentale. Pour la plagiocéphalie : repositionnement et kinésithérapie d'abord, orthèse crânienne en second. On examine toujours les hanches et on écarte une craniosténose (crâne en trapèze).", "s": "Cummings, Société canadienne de pédiatrie 2011 (Paediatr Child Health) – La plagiocéphalie positionnelle", "u": "https://doi.org/10.1093/pch/16.8.493", "g": 1, "f": 4}, {"c": "Orthopédie", "q": "Qu'est-ce que le signe de Galeazzi ?", "a": "Enfant couché, hanches et genoux fléchis : un genou plus bas que l'autre traduit un raccourcissement, évocateur d'une luxation de hanche unilatérale chez l'enfant plus grand.", "s": "AAOS – CPG Pediatric developmental dysplasia of the hip", "u": "https://www.aaos.org/quality/quality-programs/pediatric-developmental-dysplasia-of-the-hip/", "f": 17}, {"c": "Orthopédie", "q": "Quelles sont les quatre composantes du pied bot varus équin ?", "a": "Cavus, adductus de l'avant-pied, varus de l'arrière-pied et équin (acronyme anglais CAVE).", "s": "Treatment of clubfoot using the Ponseti method (revue)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6135620", "f": 18}, {"c": "Orthopédie", "q": "Plagiocéphalie positionnelle : comment évolue-t-elle naturellement au cours des deux premières années ?", "a": "Elle est fréquente et souvent transitoire. Dans une cohorte de référence, elle touchait 16 % des nourrissons à 6 semaines, près de 20 % à 4 mois, puis 7 % à 12 mois et 3 % à 24 mois.", "s": "Laughlin et al. 2011 (AAP) – Prevention and management of positional skull deformities in infants", "u": "https://pure.psu.edu/en/publications/prevention-and-management-of-positional-skull-deformities-in-infa/", "f": 4}, {"c": "Orthopédie", "q": "Pied bot varus équin : qu'est-ce que le score de Pirani ?", "a": "Un score de 0 à 6. Six signes sont cotés 0, 0,5 ou 1 : trois pour le médio-pied (bord latéral, tête du talus, pli interne) et trois pour l'arrière-pied (pli postérieur, talon, équin). Il sert à suivre la correction du pied, par exemple plâtre après plâtre.", "s": "Epomedicine – Pirani score and Dimeglio classification for clubfoot", "u": "https://epomedicine.com/medical-students/pirani-score-for-clubfoot-assessment", "f": 46}, {"c": "Orthopédie", "q": "Quelles sont les grandes étapes de la méthode Ponseti pour le pied bot varus équin ?", "a": "Plâtres cruro-pédieux hebdomadaires (environ 5 à 7). Correction du cavus d'abord (supination de l'avant-pied), puis abduction autour de la tête du talus, sans jamais appuyer sur le calcanéum. Ténotomie d'Achille fréquente (de 40-50 % à plus de 90 % des pieds selon les séries), suivie de 3 semaines de plâtre. Attelle d'abduction (chaussures sur barre) 23 h/24 pendant 3 à 4 mois, puis la nuit et pendant les siestes jusqu'à 4-5 ans.", "s": "Treatment of clubfoot using the Ponseti method (revue)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6135620", "f": 18}, {"c": "Orthopédie", "q": "Quelle est la principale cause de récidive après traitement Ponseti ?", "a": "La mauvaise observance de l'attelle d'abduction, portée 23 h sur 24 puis la nuit jusqu'à environ 4-5 ans.", "s": "St George's Hospital (NHS) – What is the Ponseti method?", "u": "https://www.stgeorges.nhs.uk/service/trauma-and-orthopaedics/orthopaedic-outpatient-service-children/ponseti-service/what-is-the-ponseti-method/", "f": 18}, {"c": "Orthopédie", "q": "Marche pieds en dedans (in-toeing) à 4 ans : trois causes selon l'étage, et comment les examiner ?", "a": "Pied : metatarsus adductus (nourrisson, bissectrice du talon). Jambe : torsion tibiale interne (1-3 ans, angle cuisse-pied). Hanche : antéversion fémorale (3-8 ans, RI >> RE en procubitus, assis en W). Correction spontanée le plus souvent.", "s": "AAFP 2011 – Managing intoeing in children", "u": "https://www.aafp.org/afp/2011/1015/p937", "f": 18}, {"c": "Orthopédie", "q": "Synovite transitoire ou arthrite septique : quels éléments font craindre l'infection ?", "a": "Fièvre, refus d'appui, altération de l'état général, syndrome inflammatoire biologique. Les critères de Kocher (fièvre, refus d'appui, VS > 40 mm/h, leucocytes > 12 000/mm³, ± CRP selon Caird) orientent : plus il y en a, plus l'infection est probable. Prudence chez le jeune enfant (Kingella kingae). L'arthrite septique est une urgence.", "s": "EB Medicine – Kocher criteria for pediatric septic arthritis of the hip", "u": "https://www.ebmedicine.net/topics/musculoskeletal-emergencies/pediatric-septic-arthritis-osteomyelitis/calculators", "f": 17}, {"c": "Orthopédie", "q": "Pied et troubles de rotation : comment distinguer ce qui se corrige seul de ce qui doit être traité ?", "a": "La plupart des déformations se corrigent seules : metatarsus adductus souple, torsion tibiale interne vers 4-6 ans, antéversion fémorale, pied plat souple indolore (sans semelles). À traiter ou explorer : le pied bot (Ponseti ou méthode fonctionnelle, puis maintien, sinon récidive), le pied plat raide et douloureux (coalition tarsienne), le pied creux, souvent signe d'une atteinte neurologique.", "s": "Vandergugten, Acquaviva & Docquier (UCLouvain) – Pied bot varus équin : classification de Dimeglio, méthode fonctionnelle et méthode de Ponseti", "u": "https://oer.uclouvain.be/jspui/bitstream/20.500.12279/258/1/Raphael%20Acquaviva_Pied%20bot%20varus%20équin.pdf", "g": 1, "f": 18}, {"c": "Orthopédie", "q": "Hanche de l'enfant : quelles situations sont des urgences, et quels pièges éviter ?", "a": "Fièvre et refus d'appui font craindre une arthrite septique : ne pas l'étiqueter « synovite ». Chez l'adolescent, une épiphysiolyse impose la décharge immédiate, et elle peut se présenter comme une douleur de genou : toujours examiner la hanche. Chez le nourrisson, une hanche luxable se traite tôt, et le harnais ne se retire pas sans accord médical.", "s": "Herman & Martinek 2015 (Pediatrics in Review) – The limping child", "u": "https://www.uthsc.edu/pediatrics/clerkship/documents/limping-child-pir-2015.pdf", "g": 1, "f": 17}, {"c": "Orthopédie", "q": "Qu'est-ce que l'hypercroissance osseuse après une amputation chez l'enfant ?", "a": "Après une amputation à travers la diaphyse, l'os du moignon pousse plus vite que les parties molles. Le bout du moignon devient chaud et sensible, et la peau peut se percer. Elle touche 4 à 35 % des enfants, surtout à l'humérus, la fibula et le tibia, avant 12 ans. Elle peut demander plusieurs reprises chirurgicales jusqu'à la fin de la croissance.", "s": "The War Amps – Bony overgrowth", "u": "https://www.waramps.ca/pdf/english-site/ways-we-help/health-and-well-being/bony-overgrowth.pdf", "f": 16}, {"c": "Orthopédie", "q": "Boiterie non traumatique : quels diagnostics selon l'âge ?", "a": "< 3 ans : arthrite septique, ostéomyélite, luxation de hanche méconnue, fracture spiroïde du tibia, maltraitance. 3-10 ans : synovite transitoire, maladie de Legg-Calvé-Perthes, infection, arthrite juvénile, hémopathie. > 10 ans : épiphysiolyse (urgence), apophysites, tumeurs. Alerte : fièvre, douleur nocturne, AEG, refus d'appui.", "s": "Perth Children's Hospital – Limping child (guide pré-orientation)", "u": "https://pch.health.wa.gov.au/For-health-professionals/Referrals-to-PCH/Prereferral-guidelines/Limping-child", "f": 17}, {"c": "Orthopédie", "q": "Arthrogrypose : définition, principes de rééducation ?", "a": "Contractures articulaires congénitales dans au moins deux régions (amyoplasie la plus fréquente, akinésie fœtale). Rééducation très précoce, mobilisations pluriquotidiennes sans forcer (os fragiles), attelles, plâtres (pieds), renforcement, fonction et autonomie (aides techniques, verticalisation, orthèses).", "s": "Rehabilitation in arthrogryposis multiplex congenita: a systematic review", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10217713/", "f": 32}, {"c": "Orthopédie", "q": "Quel signe d'alerte devant une boiterie doit faire penser à une tumeur ou une hémopathie ?", "a": "Une douleur nocturne qui réveille l'enfant, une altération de l'état général, une perte de poids ou des douleurs persistantes inexpliquées.", "s": "Perth Children's Hospital – Limping child (guide pré-orientation)", "u": "https://pch.health.wa.gov.au/For-health-professionals/Referrals-to-PCH/Prereferral-guidelines/Limping-child", "f": 17}, {"c": "Orthopédie", "q": "Quelle est la présentation typique de l'amyoplasie (arthrogrypose) ?", "a": "Atteinte symétrique des quatre membres : épaules en rotation interne, coudes en extension, poignets fléchis, souvent pieds bots. Intelligence habituellement normale.", "s": "Rehabilitation in arthrogryposis multiplex congenita: a systematic review", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10217713/", "f": 32}, {"c": "Orthopédie", "q": "Quelles interventions de rééducation sont décrites dans l'arthrogrypose ?", "a": "Étirements, mobilisations, attelles et orthèses, plâtres, programmes fonctionnels et renforcement, avec un démarrage le plus précoce possible.", "s": "Rehabilitation in arthrogryposis multiplex congenita: a systematic review", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10217713/", "f": 32}, {"c": "Orthopédie", "q": "Hémophilie : quelles articulations saignent le plus, et comment s'installe l'arthropathie hémophilique ?", "a": "Les saignements articulaires représentent 70 à 80 % des saignements. Ils touchent surtout les chevilles, les coudes et les genoux. Des hémarthroses répétées entretiennent une synovite chronique, qui saigne à son tour : l'articulation s'abîme peu à peu. L'état articulaire se suit avec le score HJHS.", "s": "National Hemophilia Foundation – Physical therapy management of joint bleeds (guide)", "u": "https://www.bleeding.org/sites/default/files/document/files/Appendix-D-Joint-Bleeds-PT-Management.pdf", "f": 31}, {"c": "Orthopédie", "q": "Oncologie pédiatrique : quels risques pour l'os et le muscle avec les corticoïdes ?", "a": "Une perte musculaire et des ostéonécroses. L'alitement et la fatigue ajoutent un déconditionnement. L'activité physique adaptée, sûre pendant les traitements, limite fatigue et perte de force.", "s": "Exercise and childhood cancer: a historical review", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC8750946/", "f": 31}, {"c": "Orthopédie", "q": "Chez l'enfant brûlé, pourquoi dit-on que la position de confort est celle de la rétraction ?", "a": "Parce que l'enfant se replie spontanément en flexion et en adduction, et la cicatrice se rétracte dans cette position. On positionne donc à l'opposé : cou dans l'axe, aisselle à 90° d'abduction, coude et genou en extension, hanche à 20° d'abduction, cheville à angle droit.", "s": "Care of Burns in Scotland 2021 – Paediatric guideline : therapy management of burns", "u": "https://www.nn.nhs.scot/cobis//wp-content/uploads/sites/9/2022/05/NSD610-006.02.pdf", "f": 23}, {"c": "Orthopédie", "q": "Brûlure de la main chez l'enfant : dans quelle position placer l'attelle ?", "a": "Poignet à 30° d'extension, métacarpo-phalangiennes fléchies à 80-90°, interphalangiennes en extension, pouce en abduction palmaire. La main est surélevée.", "s": "Care of Burns in Scotland 2021 – Paediatric guideline : therapy management of burns", "u": "https://www.nn.nhs.scot/cobis//wp-content/uploads/sites/9/2022/05/NSD610-006.02.pdf", "f": 23}, {"c": "Orthopédie", "q": "Faut-il traiter une torsion tibiale interne ?", "a": "En général non : elle se corrige spontanément vers 4-6 ans. Attelles et chaussures n'ont pas d'intérêt. La chirurgie est exceptionnelle.", "s": "AAFP 2011 – Managing intoeing in children", "u": "https://www.aafp.org/afp/2011/1015/p937", "f": 18}, {"c": "Orthopédie", "q": "Arthrite juvénile idiopathique : quelles déformations et quel trouble de croissance rechercher ?", "a": "Les attitudes vicieuses, comme un flessum de genou ou de poignet. Et les inégalités de longueur, liées à une croissance accélérée près d'une articulation inflammatoire.", "s": "Makay et al. 2013 (World J Rheumatol) – Juvenile idiopathic arthritis", "u": "https://www.wjgnet.com/2220-3214/full/v3/i3/16.htm", "f": 31}, {"c": "Orthopédie", "q": "Quel signe radiographique oriente vers une maladie de Blount ?", "a": "Un angle métaphyso-diaphysaire tibial augmenté (au-delà d'environ 11°) et un bec métaphysaire interne.", "s": "Physiopedia – Blount's disease", "u": "https://www.physio-pedia.com/Blount%27s_Disease", "f": 19}, {"c": "Orthopédie", "q": "Maladie de Blount : définition, différence avec un genu varum physiologique ?", "a": "Trouble de croissance de la partie interne du cartilage de croissance tibial proximal (tibia vara). Formes infantile et de l'adolescent. Physiologique : symétrique, harmonieux, corrigé vers 2 ans. Maladie de Blount : persiste ou s'aggrave après 2 ans, angulation sous le genou, déjettement latéral du genou à l'appui, angle métaphyso-diaphysaire augmenté, bec métaphysaire interne.", "s": "Physiopedia – Blount's disease", "u": "https://www.physio-pedia.com/Blount%27s_Disease", "f": 19}, {"c": "Orthopédie", "q": "Comment traite-t-on la maladie de Blount ?", "a": "Chez le jeune enfant, une orthèse peut suffire. Sinon, chirurgie : épiphysiodèse temporaire (croissance guidée) ou ostéotomie.", "s": "Physiopedia – Blount's disease", "u": "https://www.physio-pedia.com/Blount%27s_Disease", "f": 19}, {"c": "Orthopédie", "q": "Marche idiopathique sur la pointe : quels diagnostics éliminer ?", "a": "PC légère, dystrophie musculaire de Duchenne (CPK), Charcot-Marie-Tooth, dysraphisme/moelle attachée, TSA, brièveté congénitale du triceps. Unilatérale = organique jusqu'à preuve du contraire. Idiopathique = bilatérale, symétrique, talon possible à la demande, neuro normal.", "s": "Toe walking: causes, epidemiology, assessment and treatment (revue)", "u": "https://vivo.weill.cornell.edu/display/pubid26709689", "f": 13}, {"c": "Orthopédie", "q": "Les déformations sévères des genoux se corrigent-elles toujours avec la croissance ?", "a": "Beaucoup de déformations physiologiques, même marquées, se corrigent spontanément, mais une asymétrie, une aggravation ou une persistance après l'âge habituel justifient un avis.", "s": "Acta Orthopaedica – Spontaneous correction of severe tibiofemoral deformity in growing children", "u": "https://actaorthop.org/actao/article/view/28707", "f": 19}, {"c": "Orthopédie", "q": "Pied plat souple vs rigide : comment les distinguer, quelle conduite ?", "a": "Test pointe des pieds (arche reformée, talon en varus) et test de Jack. Souple : physiologique jusqu'à 6-8 ans, abstention sans douleur. Rigide : coalition tarsienne, talus vertical congénital, cause neuro. Imagerie et avis orthopédique.", "s": "OrthoInfo (AAOS) – Flexible flatfoot in children", "u": "https://orthoinfo.aaos.org/en/diseases--conditions/flexible-flatfoot-in-children", "f": 18}, {"c": "Orthopédie", "q": "Faut-il des semelles pour un pied plat souple non douloureux ?", "a": "Non. Le pied plat souple asymptomatique ne nécessite pas de semelles. On peut étirer le triceps s'il est court.", "s": "OrthoInfo (AAOS) – Flexible flatfoot in children", "u": "https://orthoinfo.aaos.org/en/diseases--conditions/flexible-flatfoot-in-children", "f": 18}, {"c": "Orthopédie", "q": "Inégalité de longueur des membres inférieurs : quel traitement selon l'inégalité prévue en fin de croissance ?", "a": "2 cm ou moins : surveillance ou cale dans la chaussure. De 2 à 5 cm : épiphysiodèse du côté long avant la fin de la croissance, ou raccourcissement après. Plus de 5 cm : allongement osseux. Au-delà de 20 cm avec des articulations peu fonctionnelles, une amputation avec prothèse peut se discuter. La taille, la stabilité des articulations et le projet de l'enfant comptent aussi.", "s": "Dayton Children's Hospital 2018 – Management of pediatric lower limb length inequality", "u": "https://childrensdayton.org/research-and-innovation/management-pediatric-lower-limb-length-inequality/", "f": 16}, {"c": "Orthopédie", "q": "Enfant avec une inégalité de longueur ou une amputation : quel est le rôle du MK au fil de la croissance ?", "a": "Mesurer l'inégalité et distinguer vraie et apparente, observer la marche et le rachis. Avant une petite épiphysiodèse ou une cale, traiter la part apparente (flessum, équin). Pendant un allongement, adapter la mobilisation au montage, prévenir l'équin et le flessum par des étirements et des attelles, et repérer les signaux d'alerte. Avec une prothèse, préparer le moignon, travailler l'équilibre, la marche puis le sport, surveiller une hypercroissance osseuse, et revoir l'enfant tous les 3 à 6 mois pendant les poussées de croissance.", "s": "Dayton Children's Hospital 2018 – Management of pediatric lower limb length inequality", "u": "https://childrensdayton.org/research-and-innovation/management-pediatric-lower-limb-length-inequality/", "g": 1, "f": 16}, {"c": "Orthopédie", "q": "Pied creux de l'enfant : que rechercher en premier ?", "a": "Une cause neurologique, présente chez plus des deux tiers des enfants, surtout la maladie de Charcot-Marie-Tooth. Il faut un examen neurologique complet et les antécédents familiaux. Le test du bloc de Coleman montre si le varus de l'arrière-pied se corrige.", "s": "Rosenwasser, Judd & Hyman 2022 (JPOSNA) – Evidence-based management strategies for pediatric pes cavus", "u": "https://jposna.org/index.php/jposna/article/view/461", "f": 18}, {"c": "Orthopédie", "q": "Pendant un allongement osseux de jambe, quel est le principal risque, et que fait le MK ?", "a": "La rétraction des muscles, qui résistent à l'allongement : équin de la cheville et flessum du genou. Le MK regarde d'abord le montage. Si la cheville est libre, il étire le triceps en tirant le calcanéum et en poussant l'avant-pied, genou tendu, avec une attelle de pied au repos. Si le chirurgien a bloqué la cheville, il ne la mobilise pas et travaille genou, hanche, force et marche. Il encourage l'appui autorisé et signale une perte rapide d'amplitude, une douleur de nuit ou des signes nerveux.", "s": "UCSF Benioff Children's Hospitals – Physical therapy protocol for tibial lengthening", "u": "https://www.ucsfbenioffchildrens.org/-/media/project/ucsf/ucsf-bch/pdf/physical-therapy-protocol-for-tibial-lengthening.pdf", "f": 16}, {"c": "Orthopédie", "q": "Legg-Calvé-Perthes : mécanisme, profil type, objectifs de rééducation ?", "a": "Ostéonécrose de l'épiphyse fémorale, de cause inconnue, qui évolue en quatre stades (Waldenström) : nécrose, fragmentation, réossification, remodelage. Garçon de 4 à 8 ans. Principe : garder la tête fémorale centrée dans le cotyle. Rééducation : conserver abduction et rotation interne, entretenir les abducteurs, activités sans impact. Pronostic meilleur avant 6 ans.", "s": "OrthoInfo (AAOS) – Perthes disease", "u": "https://orthoinfo.aaos.org/en/diseases--conditions/perthes-disease", "f": 17}, {"c": "Orthopédie", "q": "Quels facteurs influencent le pronostic de la maladie de Legg-Calvé-Perthes ?", "a": "Surtout l'âge au début (meilleur avant 6 ans) et l'étendue de l'atteinte de la tête fémorale (classification de Herring).", "s": "OrthoInfo (AAOS) – Perthes disease", "u": "https://orthoinfo.aaos.org/en/diseases--conditions/perthes-disease", "f": 17}, {"c": "Orthopédie", "q": "Quels signes cliniques évoquent une maladie de Legg-Calvé-Perthes ?", "a": "Boiterie souvent peu douloureuse, douleur de hanche, de cuisse ou de genou, limitation de l'abduction et de la rotation interne.", "s": "OrthoInfo (AAOS) – Perthes disease", "u": "https://orthoinfo.aaos.org/en/diseases--conditions/perthes-disease", "f": 17}, {"c": "Orthopédie", "q": "Maladie de Sever : quels gestes reproduisent la douleur ?", "a": "La compression latérale du calcanéum et la montée sur la pointe des pieds. La douleur est souvent bilatérale et la radiographie est normale.", "s": "Gilmartin 2020 (Don't Forget the Bubbles) – Apophysitis", "u": "https://dontforgetthebubbles.com/apophysitis", "f": 19}, {"c": "Orthopédie", "q": "Maladies d'Osgood-Schlatter et de Sever : localisation, profil, conduite à tenir ?", "a": "Maladie d'Osgood-Schlatter : tubérosité tibiale antérieure, sports de saut, classiquement le garçon de 12-15 ans, la fille plutôt vers 8-12 ans (de plus en plus fréquente chez elle). Maladie de Sever : apophysite calcanéenne postérieure, vers 8-14 ans, sports d'impact. Bénins et auto-limités : adaptation de la charge guidée par la douleur, renforcement progressif, étirements, froid, talonnette pour Sever.", "s": "Gilmartin 2020 (Don't Forget the Bubbles) – Apophysitis", "u": "https://dontforgetthebubbles.com/apophysitis", "f": 19}, {"c": "Orthopédie", "q": "Comment se pose le diagnostic de maladie d'Osgood-Schlatter ?", "a": "Il est clinique : douleur et saillie de la tubérosité tibiale, majorées par l'effort et la pression. L'extension contrariée du genou reproduit la douleur. La radiographie ne sert que si le tableau est atypique (douleur nocturne, fièvre, gonflement important). Une bosse peut persister à l'âge adulte.", "s": "OrthoInfo (AAOS) – Osgood-Schlatter disease", "u": "https://orthoinfo.aaos.org/en/diseases--conditions/osgood-schlatter-disease-knee-pain", "f": 19}, {"c": "Orthopédie", "q": "Un jeune sportif a une apophysite. Comment construire une reprise guidée par la douleur ?", "a": "On réduit d'abord temporairement ce qui fait mal, en suivant une échelle d'activité, sans arrêter de bouger. On entretient la force (contractions statiques, ponts fessiers). Puis le renforcement progresse, le niveau suivant étant abordé quand l'exercice reste dans une douleur acceptable. Le sport reprend par étapes. Une douleur nocturne, au repos ou avec fièvre ne correspond pas à une apophysite : avis médical.", "s": "Rathleff et al. 2020 (Orthop J Sports Med) – Activity modification and knee strengthening for Osgood-Schlatter disease", "u": "https://vbn.aau.dk/ws/files/330945567/2325967120911106.pdf", "g": 1, "f": 19}, {"c": "Orthopédie", "q": "Qu'est-ce qu'une coalition tarsienne ?", "a": "Une fusion anormale entre deux os du tarse, révélée vers 9-16 ans par un pied plat rigide et douloureux ou des entorses répétées.", "s": "OrthoInfo (AAOS) – Flexible flatfoot in children", "u": "https://orthoinfo.aaos.org/en/diseases--conditions/flexible-flatfoot-in-children", "f": 18}, {"c": "Orthopédie", "q": "Adolescent obèse qui boite avec une douleur du genou : que suspecter ?", "a": "Une épiphysiolyse de la tête fémorale : la douleur de hanche est souvent ressentie au genou. On examine toujours la hanche et on adresse sans attendre. L'obésité expose aussi à la maladie de Blount, aux fractures et aux pieds plats douloureux.", "s": "OrthoInfo (AAOS) – The impact of childhood obesity on bone, joint and muscle health", "u": "https://www.orthoinfo.org/staying-healthy/the-impact-of-childhood-obesity-on-bone-joint-and-muscle-health", "f": 34}, {"c": "Orthopédie", "q": "Quand discute-t-on une chirurgie pour antéversion fémorale ?", "a": "Rarement : en cas de persistance après 8-10 ans avec une gêne fonctionnelle importante (ostéotomie de dérotation).", "s": "AAFP 2011 – Managing intoeing in children", "u": "https://www.aafp.org/afp/2011/1015/p937", "f": 18}, {"c": "Orthopédie", "q": "Quel examen clinique de dépistage de la scoliose ?", "a": "Le test d'Adams (penché en avant) à la recherche d'une gibbosité, mesurée au scoliomètre. Un angle de rotation du tronc d'environ 5-7° justifie une radiographie.", "s": "USPSTF 2018 – Screening for adolescent idiopathic scoliosis (AAFP)", "u": "https://www.aafp.org/pubs/afp/issues/2018/0515/od1.html", "f": 20}, {"c": "Orthopédie", "q": "Quelle population est la plus à risque de scoliose idiopathique évolutive ?", "a": "Les filles en période de croissance pubertaire rapide, d'autant plus que la courbure est importante et que la maturité osseuse est faible.", "s": "SOSORT 2016 – Orthopaedic and rehabilitation treatment of idiopathic scoliosis", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5795289/", "f": 20}, {"c": "Orthopédie", "q": "Qu'est-ce qui distingue une scoliose neuromusculaire d'une scoliose idiopathique ?", "a": "Elle est souvent longue, en C, avec bascule du bassin, apparaît plus tôt et continue d'évoluer après la croissance. Le corset ne stoppe pas son évolution.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 2 (respiratoire, cardiaque, orthopédie)", "u": "https://www.mda.org/sites/default/files/Duchenne_CareConsiderations_2018_Part2.pdf", "f": 20}, {"c": "Orthopédie", "q": "Scoliose : pourquoi faut-il examiner et mesurer toujours de la même façon d'un bilan à l'autre ?", "a": "Parce que l'erreur de mesure est réelle : environ 5° pour l'angle de Cobb. Une variation plus petite n'a pas de sens. Le MK reprend la même méthode à chaque bilan (inspection, fil à plomb, test d'Adams, scoliomètre). La radiographie n'est pas répétée à chaque consultation. C'est ce qui permet de décider sur une vraie aggravation.", "s": "Negrini et al. 2018 (Scoliosis Spinal Disord) – 2016 SOSORT guidelines: orthopaedic and rehabilitation treatment of idiopathic scoliosis during growth", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5795289", "g": 1, "f": 20}, {"c": "Orthopédie", "q": "Après une chirurgie orthopédique, quelles précautions avant de reprendre la marche en robot sur tapis ?", "a": "L'accord du chirurgien et un appui indolore. Des orthèses nouvellement ajustées et bien serrées, car l'exosquelette soutient peu le pied. Puis une surveillance de la douleur à chaque séance.", "s": "HAS 2021 – Rééducation et réadaptation de la fonction motrice de l'appareil locomoteur des personnes diagnostiquées de paralysie cérébrale (argumentaire)", "u": "https://www.has-sante.fr/upload/docs/application/pdf/2021-12/_reco355_argumentaire_paralysie_cerebrale_cd_2021_10_21_post-endossement_lg.pdf", "f": 15}, {"c": "Orthopédie", "q": "Épiphysiolyse fémorale supérieure : profil, signes, urgence ?", "a": "Adolescent 10-16 ans, plutôt garçon en surpoids, pic de croissance. Boiterie, douleur de hanche, cuisse ou genou (piège), signe de Drehmann, perte de RI. Urgence : décharge immédiate, vissage in situ. Risque de nécrose. Surveiller la hanche opposée.", "s": "HealthLinkBC – Slipped capital femoral epiphysis", "u": "https://www.healthlinkbc.ca/healthwise/slipped-capital-femoral-epiphysis", "f": 17}, {"c": "Orthopédie", "q": "Épiphysiolyse fémorale : différence entre forme stable et instable ?", "a": "Classification de Loder. Stable : l'enfant peut marcher, avec ou sans béquilles, et le risque de nécrose de la tête fémorale est inférieur à 10 %. Instable : appui impossible, et le risque monte à 24-47 %.", "s": "Ferry 2012 – Slipped capital femoral epiphysis (classification de Loder)", "u": "https://www.orthoillinois.com/wp-content/uploads/2012/11/Ferry-TraumaSymposium-2012-SCFE.pdf", "f": 17}, {"c": "Orthopédie", "q": "Après vissage d'une épiphysiolyse, quelles précautions de rééducation ?", "a": "Appui selon les consignes du chirurgien, reprise progressive, et pas de sport à risque pendant plusieurs mois. On surveille aussi la hanche opposée.", "s": "HealthLinkBC – Slipped capital femoral epiphysis", "u": "https://www.healthlinkbc.ca/healthwise/slipped-capital-femoral-epiphysis", "f": 17}, {"c": "Orthopédie", "q": "Scoliose idiopathique : que mesurent l'angle de Cobb et le test de Risser ? À partir de quel angle parle-t-on de scoliose ?", "a": "Cobb : angle entre les plateaux des vertèbres limites sur radio de face. Scoliose si > 10° avec rotation vertébrale. Risser (0-5) : maturité osseuse par ossification de la crête iliaque. Risser bas = risque d'aggravation élevé.", "s": "Weinstein et al. 2013 – Effects of bracing in AIS (NEJM, BrAIST)", "u": "https://pubmed.ncbi.nlm.nih.gov/24047455/", "f": 20}, {"c": "Orthopédie", "q": "Scoliose idiopathique : indications du corset, rôle de la kinésithérapie spécifique ?", "a": "Corset : Cobb 20-25° à 40°, Risser 0-2, ou aggravation > 5°. BrAIST : succès 72 % vs 48 %, effet dose-dépendant. PSSE (Schroth, SEAS, lyonnaise) : auto-correction 3D, stabilisation, observance du corset (SOSORT 2016). Chirurgie > 45-50°.", "s": "SOSORT 2016 – Orthopaedic and rehabilitation treatment of idiopathic scoliosis", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5795289/", "f": 20}, {"c": "Orthopédie", "q": "Scoliose opérée : à partir de quel angle discute-t-on habituellement une arthrodèse ?", "a": "Autour de 45-50° de Cobb : au-delà, la courbure risque de continuer à progresser même après la fin de croissance. BrAIST utilisait 50° comme seuil chirurgical.", "s": "Weinstein et al. 2013 – Effects of bracing in AIS (NEJM, BrAIST)", "u": "https://pubmed.ncbi.nlm.nih.gov/24047455/", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : en quoi consiste l'intervention la plus courante chez l'adolescent ?", "a": "Une arthrodèse postérieure instrumentée : vis pédiculaires et tiges corrigent la courbure, puis les vertèbres instrumentées fusionnent et ne bougent plus entre elles.", "s": "Rapid recovery pathway after spinal fusion for idiopathic scoliosis (Pediatrics, 2016)", "u": "https://pubmed.ncbi.nlm.nih.gov/27009035/", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quand lève-t-on le patient, et comment se retourne-t-il au lit ?", "a": "Les protocoles de récupération rapide visent un lever dès le lendemain de l'intervention. Le patient se retourne en bloc puis passe sur le côté pour s'asseoir.", "s": "Rapid recovery pathway after spinal fusion for idiopathic scoliosis (Pediatrics, 2016)", "u": "https://pubmed.ncbi.nlm.nih.gov/27009035/", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quelles restrictions pendant les 6 premières semaines ?", "a": "Ne pas soulever de charge lourde (environ 2 kg maximum), éviter les flexions et torsions du tronc, se pencher en pliant les genoux, dos droit.", "s": "Cambridge University Hospitals (NHS) – Guidance following scoliosis surgery", "u": "https://cuh.nhs.uk/patient-information/guidance-following-scoliosis-surgery", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quels signes d'alerte doivent faire reconsulter après la sortie ?", "a": "Fièvre, rougeur, gonflement ou écoulement de la cicatrice, douleur non contrôlée par les antalgiques, vomissements empêchant de s'alimenter.", "s": "CHOP – Spinal fusion post-op (AIS) : consignes de sortie", "u": "https://www.chop.edu/clinical-pathway/spinal-fusion-post-op-adolescent-idiopathic-scoliosis-ais-discharge-instructions", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quels exercices dès le retour à domicile ?", "a": "Exercices doux du cou et des épaules (sonnette scapulaire, cercles d'épaules, flexion), respiration profonde, plusieurs fois par jour, et marche progressive selon la douleur.", "s": "Cambridge University Hospitals (NHS) – Guidance following scoliosis surgery", "u": "https://cuh.nhs.uk/patient-information/guidance-following-scoliosis-surgery", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quand reprendre l'école ?", "a": "Quand l'adolescent tient une journée complète debout à la maison. Souvent vers 4 semaines, d'abord à temps partiel.", "s": "Cambridge University Hospitals (NHS) – Guidance following scoliosis surgery", "u": "https://cuh.nhs.uk/patient-information/guidance-following-scoliosis-surgery", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quand reprendre la natation et le vélo ?", "a": "Pas de bain ni de piscine avant cicatrisation complète. Reprise douce de la natation et du vélo vers 3 mois, puis progression vers 6 mois.", "s": "Cambridge University Hospitals (NHS) – Guidance following scoliosis surgery", "u": "https://cuh.nhs.uk/patient-information/guidance-following-scoliosis-surgery", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quand reprendre la course et les sports de contact ?", "a": "Course et sports sans contact vers 6 mois. Sports de contact en compétition vers 12 mois, avec l'accord du chirurgien. Les délais varient selon les équipes, d'où des travaux de consensus récents.", "s": "Cambridge University Hospitals (NHS) – Guidance following scoliosis surgery", "u": "https://cuh.nhs.uk/patient-information/guidance-following-scoliosis-surgery", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : les délais de reprise sportive sont-ils les mêmes partout ?", "a": "Non : ils varient beaucoup selon les chirurgiens. Un consensus international (e-Delphi) a été publié pour harmoniser les conseils de reprise d'activité physique et sportive.", "s": "International e-Delphi consensus on sport and physical activity after AIS surgery", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12928444", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : que recommande la SOSORT autour de la chirurgie ?", "a": "Un entraînement aérobie avant l'intervention, et des exercices spécifiques de kinésithérapie chez les patients opérés douloureux pour réduire la douleur et améliorer la fonction.", "s": "SOSORT 2016 – Tableau 12 : exercices spécifiques pendant le corset et après chirurgie", "u": "https://scoliosisjournal.biomedcentral.com/articles/10.1186/s13013-017-0145-8/tables/12", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quand commence la rééducation structurée ?", "a": "Souvent après la consultation de contrôle avec radiographie (vers 6-8 semaines), puis travail progressif de condition physique à partir de 3 mois.", "s": "Cambridge University Hospitals (NHS) – Guidance following scoliosis surgery", "u": "https://cuh.nhs.uk/patient-information/guidance-following-scoliosis-surgery", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : qu'est-ce que la cyphose jonctionnelle proximale ?", "a": "Une cyphose anormale qui se développe juste au-dessus de la zone arthrodésée. C'est une complication mécanique classique, surveillée sur les radiographies de suivi.", "s": "Proximal junctional kyphosis in AIS: systematic review and meta-analysis", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11350560", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : combien de temps dure le suivi ?", "a": "Des consultations avec radiographies pendant au moins 3 ans après l'intervention.", "s": "Cambridge University Hospitals (NHS) – Guidance following scoliosis surgery", "u": "https://cuh.nhs.uk/patient-information/guidance-following-scoliosis-surgery", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : pourquoi travailler la posture après l'arthrodèse ?", "a": "Le patient a tendance à reprendre son ancienne posture (en écrivant, en mangeant). Il faut l'entraîner consciemment à tenir la position corrigée.", "s": "Cambridge University Hospitals (NHS) – Guidance following scoliosis surgery", "u": "https://cuh.nhs.uk/patient-information/guidance-following-scoliosis-surgery", "f": 21}, {"c": "Orthopédie", "q": "Scoliose opérée : quel est le rôle du MK à chaque étape du parcours ?", "a": "Avant : condition physique, apprentissage des gestes (retournement en bloc, passage assis par le côté, respiration), information. À l'hôpital : lever dès le lendemain, transferts, marche, respiration. Après 6-8 semaines : mobilité des segments libres, renforcement, endurance, posture. Au retour au sport : progression par paliers, en lien avec le chirurgien.", "s": "Negrini et al. 2018 (Scoliosis Spinal Disord) – 2016 SOSORT guidelines: orthopaedic and rehabilitation treatment of idiopathic scoliosis during growth", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5795289", "g": 1, "f": 21}, {"c": "Traumatologie et sport", "q": "Pourquoi l'enfant fait-il plus de fractures-décollements que d'entorses ?", "a": "Le cartilage de croissance (physe) est plus fragile que les ligaments : un traumatisme qui donnerait une entorse chez l'adulte lèse plutôt la physe chez l'enfant.", "s": "StatPearls – Salter-Harris fractures", "u": "https://www.ncbi.nlm.nih.gov/books/NBK560546/", "f": 22}, {"c": "Traumatologie et sport", "q": "Quels sont les 5 types de fractures de Salter-Harris ?", "a": "I : décollement de la physe. II : physe et métaphyse (le plus fréquent). III : physe et épiphyse. IV : métaphyse, physe et épiphyse. V : écrasement de la physe.", "s": "StatPearls – Salter-Harris fractures", "u": "https://www.ncbi.nlm.nih.gov/books/NBK560546/", "f": 22}, {"c": "Traumatologie et sport", "q": "Quel est le risque des fractures de Salter-Harris III à V ?", "a": "Le risque de trouble de croissance augmente du type I au type V : fermeture prématurée de la physe, inégalité de longueur ou déformation angulaire. Les types III et IV demandent souvent une réduction chirurgicale avec ostéosynthèse. Le type V, le plus rare, entraîne presque toujours un trouble de croissance. Un suivi est nécessaire.", "s": "Campagne, Manuel MSD (version professionnels, mars 2025) – Fractures pédiatriques physaires", "u": "https://www.msdmanuals.com/fr/professional/blessures-empoisonnement/fractures/fractures-pédiatriques-physaires-des-cartilages-de-croissance", "f": 22}, {"c": "Traumatologie et sport", "q": "Salter-Harris de type I : la radiographie peut-elle être normale ?", "a": "Oui, comme dans le type V : le diagnostic est alors clinique (douleur et gonflement localisés sur le cartilage de croissance). On peut demander un cliché comparatif et, en cas de forte suspicion, immobiliser puis réexaminer quelques jours plus tard. À la cheville, l'IRM montre que c'est rarement une vraie fracture : 3 % seulement dans l'étude de Boutis (2016), la plupart étant des entorses. Une attelle amovible et une reprise selon la tolérance suffisent le plus souvent.", "s": "ALiEM – Radiograph-negative lateral ankle injuries in children (Boutis et al. 2016, IRM)", "u": "https://www.aliem.com/radiograph-negative-lateral-ankle-injuries-in-children/", "f": 22}, {"c": "Traumatologie et sport", "q": "Quelles particularités de l'os en croissance changent le bilan et la rééducation du MK après une fracture ?", "a": "La physe cède avant le ligament : une « entorse » de l'enfant est d'abord une fracture physaire possible, et une radiographie normale ne l'exclut pas. Les fractures qui traversent la physe exposent à des troubles de croissance. L'examen neurovasculaire se refait et se note à chaque séance. Une douleur disproportionnée avec anxiété et agitation fait craindre un syndrome des loges. Au coude, pas de mobilisation forcée.", "s": "Campagne, Manuel MSD (version professionnels, mars 2025) – Fractures pédiatriques physaires", "u": "https://www.msdmanuals.com/fr/professional/blessures-empoisonnement/fractures/fractures-pédiatriques-physaires-des-cartilages-de-croissance", "g": 1, "f": 22}, {"c": "Traumatologie et sport", "q": "Quels signes d'un syndrome des loges après une fracture ?", "a": "Douleur disproportionnée, douleur à l'étirement passif des doigts, loge tendue, paresthésies. Chez l'enfant, les « 3 A » sont plus précoces et plus fiables : anxiété, agitation et besoin croissant d'antalgiques. C'est une urgence chirurgicale.", "s": "POSNA – Compartment syndrome (study guide)", "u": "https://posna.org/physician-education/study-guide/compartment-syndrome", "f": 22}, {"c": "Traumatologie et sport", "q": "Premiers secours d'une brûlure chez l'enfant : que faire, et que ne pas faire ?", "a": "Refroidir à l'eau fraîche courante pendant 20 minutes, ce qui reste utile jusqu'à 3 heures après l'accident. Retirer vêtements et bijoux, puis couvrir sans serrer (film alimentaire). Pas de glace : elle aggrave la lésion et expose l'enfant à l'hypothermie.", "s": "London and South East of England Burn Network 2015 – Burns first aid guideline", "u": "https://www.qvh.nhs.uk/wp-content/uploads/2016/07/LSEBN-Burns-First-Aid-Guideline.pdf", "f": 23}, {"c": "Traumatologie et sport", "q": "Quelles brûlures de l'enfant doivent être adressées à un centre spécialisé ?", "a": "Plus de 5 % de la surface corporelle. Visage, mains, pieds, périnée ou grandes articulations. Brûlure circulaire d'un membre ou du thorax. Brûlure électrique ou chimique, inhalation de fumées. Enfant de moins d'un an. Doute sur les circonstances.", "s": "Tran, Jacques & Holland 2019 (Aust J Gen Pract) – Assessment and management of minor burns in children", "u": "https://www1.racgp.org.au/ajgp/2019/september/minor-burns-in-children-2", "f": 23}, {"c": "Traumatologie et sport", "q": "Après une greffe de peau, quand reprendre la mobilisation de la zone greffée ?", "a": "Quand la greffe est stable, en général 5 à 10 jours, et sur avis du chirurgien. Avant, on ne mobilise pas la zone greffée, mais on continue à bouger le reste du corps.", "s": "Care of Burns in Scotland 2021 – Paediatric guideline : therapy management of burns", "u": "https://www.nn.nhs.scot/cobis//wp-content/uploads/sites/9/2022/05/NSD610-006.02.pdf", "f": 23}, {"c": "Traumatologie et sport", "q": "Cicatrice de brûlure : combien de temps pour mûrir, et quelles protections au quotidien ?", "a": "Une à deux années. Sur une peau fermée, on hydrate et on masse 3 à 4 fois par jour. On évite le soleil sur la cicatrice pendant 9 mois, puis écran solaire et exposition réduite jusqu'à 2 ans.", "s": "Care of Burns in Scotland 2021 – Paediatric guideline : therapy management of burns", "u": "https://www.nn.nhs.scot/cobis//wp-content/uploads/sites/9/2022/05/NSD610-006.02.pdf", "f": 23}, {"c": "Traumatologie et sport", "q": "Une brûlure de l'enfant met plus de 3 semaines à cicatriser. Quel risque surveiller ?", "a": "Une cicatrice hypertrophique. Plus la cicatrisation est longue, plus ce risque augmente. Mais une cicatrisation en moins de 3 semaines ne l'exclut pas : la cicatrice se surveille chez tous les enfants.", "s": "Willoughby, Prelack & Moslander 2025 (J Burn Care Res, résumé) – Wound characteristics and predictive factors of hypertrophic scarring in pediatric burns", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11958538", "f": 23}, {"c": "Traumatologie et sport", "q": "Enfant brûlé : quel est le rôle du MK, de l'accident à la cicatrice mûre ?", "a": "À l'hôpital, il positionne contre la rétraction, pose ou adapte les attelles, mobilise dès que possible en respectant les greffes, et surveille la respiration. Ensuite, il accompagne la cicatrice (massage, silicone, vêtements compressifs), entretient les amplitudes et la condition physique, et suit l'enfant pendant 1 à 2 ans, en tenant compte de la croissance. Il reste attentif à la douleur des soins et aux signes de maltraitance.", "s": "Care of Burns in Scotland 2021 – Paediatric guideline : therapy management of burns", "u": "https://www.nn.nhs.scot/cobis//wp-content/uploads/sites/9/2022/05/NSD610-006.02.pdf", "g": 1, "f": 23}, {"c": "Traumatologie et sport", "q": "Vêtements compressifs après une brûlure : comment les porter, et que disent les preuves ?", "a": "Ils se portent 23 heures sur 24, jusqu'à 18 mois, avec deux jeux et un contrôle environ tous les 3 mois. Mais la revue Cochrane de 2024 juge les preuves insuffisantes pour les recommander. La préférence de l'enfant et de sa famille guide le choix, avec le silicone comme alternative ou complément.", "s": "Harris et al. 2024 (Cochrane) – Pressure garments for preventing hypertrophic scarring after burn injury", "u": "https://www.cochrane.org/evidence/CD013530_pressure-garments-preventing-hypertrophic-scarring-after-burn-injury", "f": 23}, {"c": "Traumatologie et sport", "q": "Fracture supracondylienne du coude : mécanisme et âge typique ?", "a": "Chute sur la main bras tendu, surtout entre 5 et 7 ans. C'est la fracture du coude la plus fréquente chez l'enfant.", "s": "StatPearls – Supracondylar humerus fractures", "u": "https://www.statpearls.com/point-of-care/23048", "f": 22}, {"c": "Traumatologie et sport", "q": "Comment classe-t-on les fractures supracondyliennes en extension ?", "a": "Classification de Gartland (modifiée) : I non déplacée, II déplacée avec corticale postérieure intacte, III complètement déplacée, IV instable en flexion et en extension (sans charnière périostée, reconnue lors de la réduction). Les types III et IV relèvent en général d'une stabilisation chirurgicale.", "s": "LITFL – Classification de Gartland modifiée", "u": "https://litfl.com/gartland-classification/", "f": 22}, {"c": "Traumatologie et sport", "q": "Après une fracture du coude chez l'enfant, faut-il mobiliser de façon forcée ?", "a": "Non. L'amplitude revient le plus souvent spontanément avec l'usage. Les mobilisations passives forcées sont à éviter.", "s": "StatPearls – Supracondylar humerus fractures", "u": "https://www.statpearls.com/point-of-care/23048", "f": 22}, {"c": "Traumatologie et sport", "q": "Les règles d'Ottawa pour la cheville sont-elles utilisables chez l'enfant ?", "a": "Oui, chez l'enfant d'âge scolaire (à partir d'environ 6 ans), avec une sensibilité d'environ 98,5 % pour repérer les fractures (méta-analyse de 2009), ce qui limite les radiographies inutiles.", "s": "WikEM – Ottawa ankle rules (Dowling 2009, enfants)", "u": "https://www.wikem.org/wiki/Ankle_(Ottowa)", "f": 22}, {"c": "Traumatologie et sport", "q": "Qu'est-ce qu'une spondylolyse, et chez qui la suspecter ?", "a": "Une fracture de fatigue de l'isthme vertébral, surtout L5, chez le jeune sportif en extension répétée (gymnastique, danse). Douleur lombaire majorée en extension.", "s": "StatPearls – Spondylolysis", "u": "https://statpearls.com/point-of-care/29395", "f": 20}, {"c": "Traumatologie et sport", "q": "Comment traite-t-on une spondylolyse du jeune sportif ?", "a": "Arrêt du sport en cause pendant environ 2 à 6 mois, avec une rééducation (stabilisation du tronc, souplesse des ischio-jambiers), puis reprise progressive. Le corset est parfois proposé mais son intérêt est peu démontré. Environ 85-90 % des jeunes sportifs reprennent leur sport, en moyenne après 3 à 6 mois, souvent même sans consolidation osseuse visible.", "s": "Breslow & Ackerman 2019 (Aspetar) – Spondylolysis in athletics", "u": "https://journal.aspetar.com/en/journals/volume-8-targeted-topic-sports-medicine-and-science-in-athletics/spondylolysis-in-athletics", "f": 20}, {"c": "Traumatologie et sport", "q": "Qu'est-ce que la maladie de Scheuermann ?", "a": "Une cyphose thoracique rigide de l'adolescent, avec au moins 3 vertèbres adjacentes cunéiformes de 5° ou plus. À distinguer d'une cyphose posturale, qui se corrige.", "s": "StatPearls – Scheuermann kyphosis", "u": "https://www.ncbi.nlm.nih.gov/books/NBK499966/", "f": 20}, {"c": "Traumatologie et sport", "q": "Quelle rééducation pour une maladie de Scheuermann ?", "a": "Renforcement des extenseurs du rachis, étirements des pectoraux et des ischio-jambiers, travail postural. Corset discuté pendant la croissance selon l'angle.", "s": "StatPearls – Scheuermann kyphosis", "u": "https://www.ncbi.nlm.nih.gov/books/NBK499966/", "f": 20}, {"c": "Traumatologie et sport", "q": "Première luxation de rotule chez l'adolescent : quelle prise en charge ?", "a": "Le plus souvent conservatrice : renforcement du quadriceps et de la hanche, proprioception. Il faut d'abord rechercher une fracture ostéochondrale (radiographie, IRM si doute) : un fragment libre relève d'une fixation chirurgicale précoce. Le risque de récidive est plus élevé chez le jeune, avec une trochlée dysplasique ou une rotule haute.", "s": "Fractures ostéochondrales de l'enfant après luxation de rotule ou entorse (Eur J Orthop Surg Traumatol 2024)", "u": "https://link.springer.com/article/10.1007/s00590-024-03852-7", "f": 22}, {"c": "Sport et renforcement musculaire", "q": "Le tapis de marche est-il adapté à l'enfant avec une paralysie cérébrale ?", "a": "Oui. Il est sûr et faisable quels que soient l'âge et le niveau. Il peut améliorer la vitesse de marche sur de courtes distances et la motricité globale. Le soutien partiel du poids du corps aide surtout les enfants GMFCS III et IV.", "s": "Willoughby, Dodd & Shields 2009 (Disabil Rehabil) – Treadmill training for children with cerebral palsy: systematic review", "u": "https://search.pedro.org.au/search-results/record-detail/25222", "f": 10}, {"c": "Sport et renforcement musculaire", "q": "CIMT, HABIT, HABIT-ILE : qu'est-ce qui compte le plus pour le résultat ?", "a": "À dose égale, ces approches donnent des résultats proches. La dose, l'engagement de l'enfant et la qualité des objectifs comptent plus que le nom de la méthode. Une méthode intensive faite à faible dose n'est plus une méthode intensive.", "s": "Hoare et al. 2019 (Cochrane) – Constraint-induced movement therapy in children with unilateral cerebral palsy", "u": "https://www.cochrane.org/evidence/CD004149_constraint-induced-movement-therapy-treatment-upper-limb-children-unilateral-cerebral-palsy", "f": 10}, {"c": "Sport et renforcement musculaire", "q": "Selon les principes de l'apprentissage moteur, faut-il travailler des « prérequis » ou la tâche elle-même ?", "a": "La tâche elle-même, dans son contexte. On répète et on varie, avec une difficulté qui progresse. L'enfant cherche ses propres solutions, le thérapeute guide. Les activités sont ludiques et les objectifs ont du sens pour l'enfant.", "s": "Saussez, Brandão, Gordon & Bleyenheuft 2017 (Front Neurol) – HABIT-ILE versus HABIT in unilateral CP", "u": "https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2017.00495/pdf", "f": 10}, {"c": "Sport et renforcement musculaire", "q": "La thérapie par contrainte induite (CIMT) est-elle sûre ? Quels effets indésirables rencontre-t-on ?", "a": "Oui, elle est sûre. Les effets indésirables sont surtout la frustration, le refus de la contrainte et des irritations cutanées réversibles sous plâtre. Sa forme modifiée (mCIMT) réduit la durée de contrainte pour être mieux acceptée.", "s": "Hoare et al. 2019 (Cochrane) – Constraint-induced movement therapy in children with unilateral cerebral palsy", "u": "https://www.cochrane.org/evidence/CD004149_constraint-induced-movement-therapy-treatment-upper-limb-children-unilateral-cerebral-palsy", "f": 10}, {"c": "Sport et renforcement musculaire", "q": "Qu'est-ce que l'entraînement orienté vers des objectifs ?", "a": "L'enfant pratique directement les objectifs qu'il a choisis, dans les lieux où il en a besoin : maison, école, loisirs. C'est une approche active, intensive et orientée vers des objectifs. Elle fait partie des interventions « feu vert » dans la PC.", "s": "Novak et al. 2020 (Curr Neurol Neurosci Rep 20:3) – State of the evidence traffic lights 2019 : systematic review of interventions for children with cerebral palsy", "u": "https://doi.org/10.1007/s11910-020-1022-z", "f": 10}, {"c": "Sport et renforcement musculaire", "q": "Actif, intensif, orienté vers des objectifs : que veulent dire concrètement ces trois mots en séance ?", "a": "Actif : c'est l'enfant qui initie le mouvement. Intensif : beaucoup de répétitions sur de nombreuses heures. Une méthode intensive faite à faible dose n'est plus intensive. Orienté vers des objectifs : des objectifs choisis avec l'enfant et sa famille, travaillés sur la tâche elle-même et dans son contexte, puis mesurés avant et après (GAS, COPM, AHA, Melbourne).", "s": "Hoare et al. 2019 (Cochrane) – Constraint-induced movement therapy in children with unilateral cerebral palsy", "u": "https://www.cochrane.org/evidence/CD004149_constraint-induced-movement-therapy-treatment-upper-limb-children-unilateral-cerebral-palsy", "g": 1, "f": 10}, {"c": "Sport et renforcement musculaire", "q": "Tapis, robot ou marche au sol : qu'est-ce qui compte le plus pour le résultat ?", "a": "Le nombre de pas et l'implication de l'enfant. À dose égale, le tapis ou le robot font rarement mieux que la marche au sol guidée par le MK. Leur intérêt est de faire marcher plus longtemps, avec moins d'effort pour le thérapeute.", "s": "Chiu, Ada & Bania 2020 (Cochrane) – Mechanically assisted walking training for walking, participation, and quality of life in children with cerebral palsy", "u": "https://www.cochrane.org/evidence/CD013114_mechanically-assisted-walking-training-children-cerebral-palsy", "f": 15}, {"c": "Sport et renforcement musculaire", "q": "Après une toxine dans le triceps sural pour un équin vrai, quelle rééducation proposer ?", "a": "Exploiter la « fenêtre » ouverte par l'injection (effet en quelques jours, pic vers 2 à 4 semaines, durée 3 à 6 mois) : renforcement musculaire (le seul complément avec un bon niveau de preuve) et entraînement moteur ciblé sur des objectifs fixés avec la famille (GAS), étirements prolongés ou plâtres en cas de rétraction fixée, orthèse cheville-pied pour la marche. Réévaluation des objectifs à 4-6 mois. (Référence : consensus international 2010.)", "s": "Love et al. 2010 – BoNT assessment, intervention and after-care for lower limb spasticity in children with CP: international consensus", "u": "https://lirias.kuleuven.be/retrieve/438467", "f": 8}, {"c": "Sport et renforcement musculaire", "q": "Le renforcement musculaire est-il utile dans la paralysie cérébrale ?", "a": "Il augmente la force, sans aggraver la spasticité. Son effet sur la fonction (marche, GMFM) est plus inconstant : il faut l'associer à un entraînement fonctionnel orienté vers les tâches.", "s": "Effects of strength-training trials for children with spastic CP: a systematic review", "u": "https://repository.uwc.ac.za/handle/10566/2770", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Renforcement musculaire d'un jeune avec une PC : quelle fréquence, quels muscles, en combien de temps ?", "a": "2 à 4 séances par semaine, sur des jours non consécutifs, en ciblant surtout les muscles antigravitaires (extenseurs de hanche, fléchisseurs plantaires). Les bénéfices demandent au moins 8 à 16 semaines d'entraînement régulier. (Référence : Verschuren 2016.)", "s": "Verschuren et al. 2016 – Exercise and physical activity recommendations for people with CP (résumé CPRN)", "u": "https://cprn.org/exercise-and-physical-activity-in-spastic-diplegia-part-2/", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Activité aérobie et temps assis : que conseiller à un jeune avec une PC ?", "a": "Exercice aérobie au moins 3 fois par semaine, plus de 20 minutes, à plus de 60 % de la fréquence cardiaque maximale. 60 minutes d'activité modérée à soutenue au moins 5 jours par semaine. Moins de 2 heures assis par jour, ou une pause active de 2 minutes toutes les 30 à 60 minutes. (Référence : Verschuren 2016.)", "s": "Verschuren et al. 2016 – Exercise and physical activity recommendations for people with CP (résumé CPRN)", "u": "https://cprn.org/exercise-and-physical-activity-in-spastic-diplegia-part-2/", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "La pliométrie est-elle adaptée à l'enfant ?", "a": "Oui, avec un faible volume, une progression graduelle, des surfaces adaptées et un apprentissage de la réception. Elle améliore saut, vitesse et coordination.", "s": "A systematic review: plyometric training programs for young children", "u": "https://digitalcommons.usu.edu/sped_facpub/639", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Commotion cérébrale chez l'enfant : dans quel ordre reprendre l'école et le sport ?", "a": "Le retour à l'école passe en premier. Le retour au sport suit une stratégie graduée par étapes, la reprise du sport de contact n'intervenant qu'après un retour scolaire complet sans symptômes.", "s": "Pediatric sport-related concussion: recommendations from the Amsterdam consensus", "u": "https://research.monash.edu/en/publications/pediatric-sport-related-concussion-recommendations-from-the-amste/", "f": 26}, {"c": "Sport et renforcement musculaire", "q": "Faut-il un repos strict prolongé après une commotion ?", "a": "Non : après une courte période de repos relatif (environ 24-48 h), une activité physique légère, sous le seuil des symptômes, est recommandée.", "s": "Pediatric sport-related concussion: recommendations from the Amsterdam consensus", "u": "https://research.monash.edu/en/publications/pediatric-sport-related-concussion-recommendations-from-the-amste/", "f": 26}, {"c": "Sport et renforcement musculaire", "q": "Quelles précautions pour l'enfant qui fait du sport à la chaleur ?", "a": "Acclimatation progressive, hydratation régulière, adaptation de l'intensité et des pauses, vêtements adaptés, et vigilance particulière chez les enfants malades ou en situation de handicap.", "s": "AAP – Climatic heat stress and exercising children and adolescents", "u": "https://heathealth.info/resources/climatic-heat-stress-and-exercising-children-and-adolescents/", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Après une commotion cérébrale, quels signes imposent un transfert en urgence ?", "a": "Douleur du cou, vision double, faiblesse ou fourmillements des membres, maux de tête sévères ou qui s'aggravent, convulsions, perte de connaissance, vomissements répétés, agitation, confusion ou somnolence croissantes.", "s": "Patricios et al. 2023 (BJSM) – Consensus statement on concussion in sport : 6th International Conference, Amsterdam 2022", "u": "https://bjsm.bmj.com/content/57/11/695", "f": 26}, {"c": "Sport et renforcement musculaire", "q": "Décris le parcours d'un enfant après une commotion cérébrale, du terrain au retour au sport de contact.", "a": "Il sort du jeu et ne reprend pas le jour même. Les signes d'alerte imposent l'urgence. Évaluation par un professionnel (Child SCAT6 ou SCAT6). Repos relatif de 24 à 48 heures, puis activité légère sous le seuil des symptômes. L'école d'abord, puis le sport en 6 étapes d'au moins 24 heures. Le contact attend un retour scolaire complet sans symptômes et un avis médical. Au-delà de 4 semaines : évaluation pluridisciplinaire.", "s": "Patricios et al. 2023 (BJSM) – Consensus statement on concussion in sport : 6th International Conference, Amsterdam 2022", "u": "https://bjsm.bmj.com/content/57/11/695", "g": 1, "f": 26}, {"c": "Sport et renforcement musculaire", "q": "Les programmes alimentation et activité physique font-ils maigrir les enfants obèses de 6 à 11 ans ?", "a": "Un peu, à court terme. Une revue Cochrane de 37 essais trouve une petite baisse de l'IMC exprimé en z-score, avec des preuves de faible certitude. On vise donc aussi la santé et le plaisir de bouger, pas seulement le poids.", "s": "Mead et al. 2017 (Cochrane) – Diet, physical activity and behavioural interventions for overweight or obese children aged 6 to 11", "u": "https://www.cochrane.org/evidence/CD012651_diet-physical-activity-and-behavioural-interventions-treatment-overweight-or-obese-children-age-6-11", "f": 34}, {"c": "Sport et renforcement musculaire", "q": "D'où vient le gain de force chez l'enfant prépubère ?", "a": "Surtout d'adaptations neuromusculaires (meilleur recrutement et coordination des unités motrices). L'hypertrophie musculaire reste faible avant la puberté.", "s": "NSCA 2009 – Youth resistance training: updated position statement", "u": "https://dxpprod.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Les échauffements neuromusculaires (type FIFA 11+ Kids) préviennent-ils les blessures ?", "a": "Oui : ces programmes structurés (équilibre, renforcement, technique de chute, pliométrie) réduisent les blessures chez l'enfant footballeur. Dans l'essai de Rössler (2018, 7-13 ans), le programme « FIFA 11+ Kids » a réduit les blessures d'environ 48 % et les blessures graves d'environ 74 %, à condition de le pratiquer au moins une, idéalement deux fois par semaine.", "s": "Rössler et al. 2018 – « FIFA 11+ Kids » cluster randomised trial (résumé)", "u": "https://medicalresearch.com/11-kids-program-reduces-soccer-injuries-in-children/", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Comment organiser la semaine sportive d'un enfant de 10 ans en bonne santé ?", "a": "Bouger chaque jour : en moyenne 60 minutes d'activité modérée à soutenue, avec des activités intenses et du renforcement au moins 3 jours par semaine, et moins d'écrans. Le renforcement se fait 2 à 3 fois par semaine, jours non consécutifs, la technique avant la charge. La pliométrie reste à faible volume. Un échauffement neuromusculaire régulier réduit les blessures.", "s": "OMS 2020 – Lignes directrices sur l'activité physique et la sédentarité", "u": "https://www.ncbi.nlm.nih.gov/books/NBK566046/", "g": 1, "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Le renforcement musculaire est-il sûr chez l'enfant ?", "a": "Oui, s'il est encadré par un professionnel qualifié, avec une technique correcte et une progression adaptée. Il est bénéfique pour la force, la santé osseuse et la prévention des blessures.", "s": "NSCA 2009 – Youth resistance training: updated position statement", "u": "https://dxpprod.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "À partir de quel âge peut-on commencer un renforcement musculaire ?", "a": "Dès que l'enfant est capable de suivre des consignes et d'appliquer une technique, souvent vers 7-8 ans, avec un programme adapté et encadré.", "s": "NSCA 2009 – Youth resistance training: updated position statement", "u": "https://dxpprod.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Le renforcement musculaire abîme-t-il les cartilages de croissance ?", "a": "Aucune preuve ne le montre avec un entraînement encadré. Les blessures surviennent surtout sans supervision, avec une mauvaise technique ou des charges excessives.", "s": "NSCA 2009 – Youth resistance training: updated position statement", "u": "https://dxpprod.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Quels paramètres pour un programme de renforcement chez l'enfant ?", "a": "En général 2 à 3 séances par semaine sur des jours non consécutifs, 1 à 3 séries de 6 à 15 répétitions, charges légères à modérées, la priorité étant la qualité technique.", "s": "NSCA 2009 – Youth resistance training: updated position statement", "u": "https://dxpprod.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Comment faire progresser la charge chez l'enfant ?", "a": "Progressivement (de l'ordre de 5 à 10 %), seulement quand la technique est maîtrisée sur toutes les répétitions.", "s": "NSCA 2009 – Youth resistance training: updated position statement", "u": "https://dxpprod.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Quels sont les grands messages actuels sur le renforcement musculaire des jeunes ?", "a": "Il est sûr et efficace s'il est bien encadré, apporte des bénéfices de santé (os, composition corporelle, prévention des blessures) et doit s'intégrer dans un développement athlétique à long terme. (Référence : consensus international 2014.)", "s": "Lloyd et al. – Position statement on youth resistance training: 2014 International Consensus", "u": "https://pure.southwales.ac.uk/en/publications/position-statement-on-youth-resistance-training-the-2014-internat/", "f": 24}, {"c": "Sport et renforcement musculaire", "q": "Quels sont les risques d'une spécialisation sportive précoce ?", "a": "Blessures de surmenage, épuisement et abandon du sport. On recommande de diversifier les activités et de retarder la spécialisation exclusive, souvent jusqu'à l'adolescence.", "s": "Australian Institute of Sport – Sport specialisation in young athletes (position statement)", "u": "https://www.ais.gov.au/__data/assets/pdf_file/0005/716747/Sport-Specialisation-in-Young-Athletes-Position-Statement.pdf", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Quelles règles simples pour limiter le surmenage chez le jeune sportif ?", "a": "Pas plus d'heures de sport organisé par semaine que l'âge de l'enfant, au moins 2 jours de repos par semaine, et des périodes sans le sport principal dans l'année.", "s": "NATA – Youth sports specialization recommendations", "u": "https://www.nata.org/sites/default/files/youth_sports_specialization_recommendations.pdf", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Quelles blessures de surmenage sont typiques de l'enfant sportif ?", "a": "Apophysites (maladies d'Osgood-Schlatter, de Sever, de Sinding-Larsen-Johansson), fractures de fatigue et spondylolyse, liées à la croissance et à la répétition des charges.", "s": "Aspetar Sports Medicine Journal – Growth and maturation as potential risk factors", "u": "https://www.aspetar.com/journal/viewarticle.aspx?id=470", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Comment protéger l'épaule et le coude du jeune lanceur ?", "a": "Limiter le nombre de lancers par jour et par semaine, respecter des jours de repos, éviter de lancer toute l'année et arrêter dès qu'une douleur apparaît.", "s": "Lurie Children's Hospital – Injury prevention for pitchers", "u": "https://www.luriechildrens.org/en/specialties-conditions/pediatric-sports-medicine/sports-injury-prevention-tips/injury-prevention-for-pitchers/", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Rupture du LCA chez l'enfant en croissance : quels enjeux ?", "a": "Sans prise en charge adaptée, risque de lésions secondaires (ménisques, cartilage). Le retour au sport est long et le risque de nouvelle rupture est élevé chez le jeune.", "s": "Return to sport after pediatric and adolescent ACL injury: current evidence", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5876277/", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Quels critères avant un retour au sport après une blessure du genou ?", "a": "Absence de douleur et d'épanchement, amplitude complète, force symétrique (environ 90 % du côté sain), tests fonctionnels de saut satisfaisants et préparation psychologique.", "s": "Return to sport after pediatric and adolescent ACL injury: current evidence", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5876277/", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Commotion cérébrale : quel outil d'évaluation utiliser selon l'âge ?", "a": "Le Child SCAT6 de 8 à 12 ans, le SCAT6 à partir de 13 ans. Ils sont faits pour les professionnels de santé, idéalement dans les 72 heures. L'outil CRT6 aide les entraîneurs et les parents à repérer une commotion.", "s": "Patricios et al. 2023 (BJSM) – Consensus statement on concussion in sport : 6th International Conference, Amsterdam 2022", "u": "https://bjsm.bmj.com/content/57/11/695", "f": 26}, {"c": "Sport et renforcement musculaire", "q": "Comment protéger le jeune sportif tout au long de sa croissance, de la prévention au retour au sport ?", "a": "Diversifier et retarder la spécialisation. Pas plus d'heures de sport organisé par semaine que l'âge, au moins 2 jours de repos. Adapter la charge pendant le pic de croissance. Débuter tôt l'entraînement neuromusculaire. Repérer le déficit énergétique (fractures de fatigue répétées, règles absentes). Après une blessure, revenir sur critères et non sur un délai.", "s": "Myer et al. 2013 (Am J Sports Med) – Neuromuscular training and ACL injury reduction by age (résumé DynaMed)", "u": "https://about.ebsco.com/clinical-decisions/dynamed-solutions/about/resident-focus/neuromuscular-training-may-be-effective", "g": 1, "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Pourquoi le pic de croissance pubertaire est-il une période à risque ?", "a": "Les os grandissent plus vite que les muscles et les tendons : raideur relative, coordination perturbée, apophyses fragiles. C'est une période de blessures plus fréquentes. On adapte la charge.", "s": "Aspetar Sports Medicine Journal – Growth and maturation as potential risk factors", "u": "https://www.aspetar.com/journal/viewarticle.aspx?id=470", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Qu'est-ce que le déficit énergétique relatif dans le sport (REDs) ?", "a": "Un apport énergétique insuffisant par rapport aux dépenses de l'entraînement, chez les filles comme chez les garçons. Il retentit sur les hormones, l'os (fractures de fatigue), le cycle menstruel, la croissance et la performance. Signes d'alerte : fractures de fatigue répétées, absence de règles, perte de poids. Le CIO propose un outil médical, le REDs CAT2. Prise en charge pluridisciplinaire.", "s": "IOC 2023 – Consensus statement on Relative Energy Deficiency in Sport (REDs)", "u": "https://pubmed.ncbi.nlm.nih.gov/37752011/", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Quel est le test clinique de référence de la rupture du LCA ?", "a": "Le test de Lachman : tiroir antérieur du tibia à 20-30° de flexion, avec un arrêt mou. Le tiroir antérieur à 90° et le ressaut rotatoire complètent l'examen. L'IRM confirme la rupture et recherche les lésions associées.", "s": "Return to sport after pediatric and adolescent ACL injury: current evidence", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5876277/", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Les programmes d'entraînement neuromusculaire préviennent-ils les ruptures du LCA chez les adolescentes sportives, et à quel âge sont-ils le plus efficaces ?", "a": "Oui : renforcement, contrôle du tronc et de la hanche, réception des sauts. Dans la méta-analyse de Myer (2013), le risque baisse d'environ 70 % chez les 14-18 ans, sans effet significatif après 18 ans : mieux vaut commencer tôt, avant ou pendant la puberté.", "s": "Myer et al. 2013 (Am J Sports Med) – Neuromuscular training and ACL injury reduction by age (résumé DynaMed)", "u": "https://about.ebsco.com/clinical-decisions/dynamed-solutions/about/resident-focus/neuromuscular-training-may-be-effective", "f": 25}, {"c": "Sport et renforcement musculaire", "q": "Après une commotion, quel type d'exercice aide l'adolescent à récupérer plus vite ?", "a": "Un exercice aérobie sous le seuil des symptômes, débuté dans la première semaine après quelques jours de repos : environ 20 minutes par jour à 80 % de la fréquence cardiaque qui déclenche les symptômes sur un test d'effort (Buffalo Concussion Treadmill Test). Récupération en 13 jours en moyenne, contre 17 avec des étirements. (Référence : Leddy 2019.)", "s": "Leddy et al. 2019 (JAMA Pediatrics) – Early subthreshold aerobic exercise for sport-related concussion (communiqué)", "u": "https://www.buffalo.edu/news/releases/2019/02/002.html", "f": 26}, {"c": "Neuromusculaire", "q": "Quel élément clinique est un bon indicateur pronostique dans la paralysie du plexus brachial ?", "a": "La récupération de la flexion active du coude (biceps) vers 3 mois. Son absence fait discuter un avis chirurgical précoce.", "s": "APCP – Obstetric brachial plexus palsy (guide kiné)", "u": "https://apcp.csp.org.uk/system/files/obstetric_brachial_plexus_palsy_1.pdf", "f": 28}, {"c": "Neuromusculaire", "q": "Paralysie obstétricale du plexus brachial de type Erb-Duchenne : racines touchées et attitude caractéristique ?", "a": "C5-C6 (± C7). « Pourboire du serveur » : adduction-rotation interne, coude en extension, pronation, poignet fléchi si C7. Prévenir la rétraction en rotation interne et la dysplasie gléno-humérale. Type Déjerine-Klumpke : C8-T1. Paralysie totale : C5-T1.", "s": "APCP – Obstetric brachial plexus palsy (guide kiné)", "u": "https://apcp.csp.org.uk/system/files/obstetric_brachial_plexus_palsy_1.pdf", "f": 28}, {"c": "Neuromusculaire", "q": "Quels sont les principes de la kinésithérapie dans la paralysie du plexus brachial ?", "a": "Mobilisations passives douces et quotidiennes, réalisées aussi par les parents (rotation externe, abduction, supination), stimulation sensori-motrice et intégration du membre dans le jeu. Pas de mobilisation forcée.", "s": "APCP – Obstetric brachial plexus palsy (guide kiné)", "u": "https://apcp.csp.org.uk/system/files/obstetric_brachial_plexus_palsy_1.pdf", "f": 28}, {"c": "Neuromusculaire", "q": "Paralysie obstétricale du plexus brachial : que décrit la classification de Narakas ?", "a": "Elle classe l'atteinte en 4 groupes : 1, C5-C6. 2, C5-C7. 3, C5-T1. 4, C5-T1 avec un syndrome de Claude Bernard-Horner. Plus le groupe est élevé, moins la récupération spontanée est bonne. Au groupe 4, la main reste souvent peu fonctionnelle.", "s": "Pondaag & Malessy 2021 (J Hand Surg Eur) – Nerve surgery and outcome in obstetric brachial plexus injury (classification de Narakas)", "u": "https://core.ac.uk/download/429680108.pdf", "f": 46}, {"c": "Neuromusculaire", "q": "Amyotrophie spinale : types cliniques, et qu'est-ce qui a changé ?", "a": "Type I < 6 mois, jamais assis. Type II 6-18 mois, assis sans marche. Type III > 18 mois, marche acquise (formes extrêmes : type 0 anténatal, type IV adulte). Traitements modificateurs (nusinersen, onasemnogène, risdiplam), plus efficaces s'ils sont précoces : nouveaux phénotypes. C'est pourquoi l'amyotrophie spinale fait partie du dépistage néonatal en France depuis le 1er septembre 2025. Échelles : CHOP INTEND, HFMSE, RULM.", "s": "VIDAL 2025 – Dépistage néonatal : trois nouvelles maladies intégrées, dont l'amyotrophie spinale", "u": "https://www.vidal.fr/actualites/36910-depistage-neonatal-trois-nouvelles-maladies-integrees-dont-l-amyotrophie-spinale.html", "f": 27}, {"c": "Neuromusculaire", "q": "Spina bifida : lien entre niveau lésionnel et pronostic de marche ?", "a": "Pivot = quadriceps (L3). T12-L1 : fauteuil au quotidien, marche à domicile ou thérapeutique avec grandes orthèses (HKAFO, RGO). L2-L3 : fauteuil pour l'extérieur. Avec un quadriceps actif (L3), marche aidée (KAFO ou AFO, cannes ou déambulateur) associée au fauteuil. L4-L5 : marche à domicile et à l'extérieur, souvent avec AFO, parfois des cannes. Sacré : marche, souvent avec orthèses. Toute dégradation doit faire chercher une moelle attachée, un Chiari ou une dérivation défaillante.", "s": "Spina Bifida Association 2024 – Mobility guidelines (version révisée)", "u": "https://www.spinabifidaassociation.org/wp-content/uploads/2025/08/MobilityJan2024.pdf", "f": 28}, {"c": "Neuromusculaire", "q": "Signes d'un syndrome de la moelle attachée chez un enfant opéré d'un spina bifida ?", "a": "Dégradation neurologique progressive : perte de force ou de niveau moteur, spasticité croissante, douleurs lombaires ou des membres, nouveaux troubles urinaires, scoliose rapidement évolutive, pied creux qui s'aggrave, marche qui se dégrade. IRM et avis neurochirurgical.", "s": "Sydney Children's Hospitals Network – Tethered cord syndrome factsheet", "u": "https://www.schn.health.nsw.gov.au/factsheets/tethered-cord-syndrome", "f": 28}, {"c": "Neuromusculaire", "q": "Quel est le mode de transmission de la dystrophie musculaire de Duchenne ?", "a": "Récessif lié à l'X : elle touche surtout les garçons. Elle est due à des mutations du gène de la dystrophine. Les CPK sont très élevées.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 1 (Lancet Neurol)", "u": "https://ern-euro-nmd.eu/publication/diagnosis-and-management-of-duchenne-muscular-dystrophy-part-one/", "f": 27}, {"c": "Neuromusculaire", "q": "Pourquoi le suivi cardiaque est-il indispensable dans la dystrophie musculaire de Duchenne ?", "a": "Une cardiomyopathie se développe chez presque tous les patients. Une évaluation cardiaque (ECG, échographie, IRM si besoin) est recommandée dès le diagnostic ou au plus tard vers 6 ans, puis chaque année. Un inhibiteur de l'enzyme de conversion est débuté au plus tard vers 10 ans, même si le cœur paraît normal.", "s": "DMD Care UK – Cardiac care in Duchenne (information basée sur le consensus britannique)", "u": "https://www.duchenneuk.org/wp-content/uploads/2022/11/DMD-Care-UK-Cardiac-patient-information-digital.pdf", "f": 27}, {"c": "Neuromusculaire", "q": "Amyotrophie spinale : comment adapter la rééducation à ce que l'enfant sait faire ?", "a": "Selon le statut fonctionnel : enfants qui ne tiennent pas assis (non-sitters), qui tiennent assis (sitters) et qui marchent (walkers), chacun avec des objectifs propres. (Référence : recommandations SMA 2018.)", "s": "Mercuri et al. 2018 – SMA standards of care, partie 1 (diagnostic, rééducation, orthopédie)", "u": "https://pubmed.ncbi.nlm.nih.gov/29290580/", "f": 27}, {"c": "Neuromusculaire", "q": "Quels sont les objectifs de kinésithérapie chez un enfant atteint de SMA qui ne tient pas assis ?", "a": "Positionnement, prévention des rétractions et des déformations, confort, soutien respiratoire et stimulation motrice adaptée.", "s": "Mercuri et al. 2018 – SMA standards of care, partie 1 (diagnostic, rééducation, orthopédie)", "u": "https://pubmed.ncbi.nlm.nih.gov/29290580/", "f": 27}, {"c": "Neuromusculaire", "q": "Quels sont les objectifs de kinésithérapie dans le spina bifida ?", "a": "Mobilité (marche avec orthèses ou fauteuil), prévention des déformations, protection cutanée des zones insensibles, autonomie et surveillance neurologique.", "s": "Spina Bifida Association – Mobility guidelines", "u": "https://pubmed.ncbi.nlm.nih.gov/33325411/", "f": 28}, {"c": "Neuromusculaire", "q": "Quels signes d'une dysfonction de dérivation doivent alerter chez un enfant spina bifida ?", "a": "Céphalées, vomissements, somnolence, irritabilité, troubles visuels, baisse des performances ou dégradation motrice. C'est une urgence.", "s": "Spina Bifida Association 2018 – Guidelines for the care of people with spina bifida", "u": "https://depts.washington.edu/dbpeds/Guidelines-for-the-Care-of-People-with-Spina-Bifida-2018.pdf", "f": 28}, {"c": "Neuromusculaire", "q": "POPB, spina bifida, syndrome de Guillain-Barré : qu'ont en commun ces paralysies, et en quoi leur évolution diffère-t-elle ?", "a": "L'atteinte est périphérique ou touche la moelle basse : la paralysie est plutôt flasque, souvent avec un trouble de la sensibilité, à l'inverse de la PC. La POPB récupère souvent : la flexion du coude vers 3 mois guide le pronostic. Le SGB récupère le plus souvent, mais la phase aiguë impose de surveiller la respiration. Le spina bifida est une lésion fixe : toute dégradation doit faire chercher une cause.", "s": "Spina Bifida Association 2024 – Mobility guidelines (version révisée)", "u": "https://www.spinabifidaassociation.org/wp-content/uploads/2025/08/MobilityJan2024.pdf", "g": 1, "f": 28}, {"c": "Neuromusculaire", "q": "Quels signes précoces doivent faire évoquer une dystrophie musculaire de Duchenne ?", "a": "Retard de marche, chutes fréquentes, difficulté à monter les escaliers ou à courir, mollets hypertrophiés, signe de Gowers, retard de langage possible. Le dosage des CPK oriente.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 1 (Lancet Neurol)", "u": "https://ern-euro-nmd.eu/publication/diagnosis-and-management-of-duchenne-muscular-dystrophy-part-one/", "f": 27}, {"c": "Neuromusculaire", "q": "Quel risque orthopédique majeur chez l'enfant atteint de SMA non marchant ?", "a": "La scoliose, très fréquente. Un corset souple peut aider la position assise. La surveillance est régulière et la chirurgie se discute selon l'évolution.", "s": "Mercuri et al. 2018 – SMA standards of care, partie 1 (diagnostic, rééducation, orthopédie)", "u": "https://pubmed.ncbi.nlm.nih.gov/29290580/", "f": 27}, {"c": "Neuromusculaire", "q": "Dystrophie de Duchenne et amyotrophie spinale : pourquoi la rééducation diffère-t-elle selon que le muscle ou le motoneurone est malade ?", "a": "Dans la DMD, le muscle lui-même est fragile : activité sous-maximale, pas d'excentrique intense, étirements réguliers et orthèses de nuit. Dans la SMA, c'est le motoneurone : les objectifs se fixent selon que l'enfant est couché, assis ou marchant, et les traitements modificateurs changent sa trajectoire, d'où des réévaluations régulières. Dans les deux, on suit le cœur, la respiration et le rachis.", "s": "Bushby et al. 2010 (Lancet Neurol) – Diagnosis and management of DMD, part 2 : implementation of multidisciplinary care", "u": "https://cdmd.ucla.edu/file/4482/dmd_protocol2.pdf", "g": 1, "f": 27}, {"c": "Neuromusculaire", "q": "Qu'est-ce que la manœuvre de Gowers, et dans quelle pathologie est-elle typique ?", "a": "L'enfant se relève en s'aidant des mains le long de ses jambes, compensant la faiblesse des extenseurs de hanche et des quadriceps. Typique de la DMD. Aussi SMA III, myopathies des ceintures.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 1 (Lancet Neurol)", "u": "https://ern-euro-nmd.eu/publication/diagnosis-and-management-of-duchenne-muscular-dystrophy-part-one/", "f": 27}, {"c": "Neuromusculaire", "q": "Dystrophie musculaire de Duchenne : âge de perte de la marche sans traitement, axes de la kinésithérapie ?", "a": "Vers 10 ans (7-13), retardée de 2-3 ans sous corticoïdes. De nouveaux traitements arrivent : le givinostat a reçu en 2025 une autorisation européenne conditionnelle (enfants marchants de 6 ans et plus, avec corticoïdes, accès au cas par cas en France). Kinésithérapie : prévenir rétractions (étirements, orthèses nocturnes, verticalisation), activité sous-maximale sans excentrique intense, respiratoire, surveillance scoliose et cardiomyopathie.", "s": "AFM-Téléthon 2025 – Myopathie de Duchenne : autorisation du givinostat en Europe", "u": "https://www.afm-telethon.fr/fr/actualites/myopathie-de-duchenne-autorisation-du-givinostat-en-europe", "f": 27}, {"c": "Neuromusculaire", "q": "Quelle est la place des orthèses de nuit dans la dystrophie musculaire de Duchenne ?", "a": "Des orthèses cheville-pied de nuit sont recommandées pour prévenir l'équin, associées à des étirements quotidiens de la cheville, du genou et de la hanche.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 1 (Lancet Neurol)", "u": "https://ern-euro-nmd.eu/publication/diagnosis-and-management-of-duchenne-muscular-dystrophy-part-one/", "f": 27}, {"c": "Neuromusculaire", "q": "Quelles activités physiques conseiller dans la dystrophie musculaire de Duchenne ?", "a": "Une activité régulière sous-maximale (natation, vélo, jeux), en évitant les exercices excentriques intenses et la fatigue excessive.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 1 (Lancet Neurol)", "u": "https://ern-euro-nmd.eu/publication/diagnosis-and-management-of-duchenne-muscular-dystrophy-part-one/", "f": 27}, {"c": "Neuromusculaire", "q": "Amyotrophie spinale : qu'a apporté l'exosquelette portable chez des enfants non marchants ?", "a": "Dans une série de 3 enfants SMA de type 2, traités par nusinersen, 9 séances ont augmenté la force à la hanche (fléchisseurs +60 %, extenseurs +48 %) et l'amplitude de hanche et de cheville. Sans groupe témoin, et avec des auteurs liés au fabricant.", "s": "Cumplido-Trasmonte et al. 2022 (J NeuroEng Rehabil) – Effects of ATLAS 2030 gait exoskeleton on strength and range of motion in children with SMA II: a case series", "u": "https://link.springer.com/10.1186/s12984-022-01055-x", "f": 15}, {"c": "Neuromusculaire", "q": "Dystrophie de Duchenne : quelles précautions si l'enfant marche sur tapis ?", "a": "Aucun essai n'existe. On applique les règles d'activité de la DMD : effort sous-maximal (l'enfant peut parler mais pas chanter), pas d'excentrique intense, donc pas de tapis en descente. On arrête en cas de crampes, d'urines foncées ou de fatigue qui dure plus de 24 à 36 heures.", "s": "Parent Project Muscular Dystrophy 2026 – Exercise in dystrophinopathy: frequently asked questions", "u": "https://www.parentprojectmd.org/wp-content/uploads/2026/06/Exercise-in-Dystrophinopathy_-What-Families-Need-to-Know-FAQs.pdf", "f": 15}, {"c": "Neuromusculaire", "q": "Qu'est-ce que la CMTPedS ?", "a": "L'échelle pédiatrique de la maladie de Charcot-Marie-Tooth, de 3 à 20 ans. Elle comprend 11 épreuves : force, dextérité, sensibilité, marche, équilibre, saut et endurance. Le score va de 0 à 44, plus il est haut plus l'atteinte est sévère.", "s": "Burns et al. 2012 (Ann Neurol) – Validation of the CMT pediatric scale (CMTPedS)", "u": "https://www.qxmd.com/r/22522479", "f": 30}, {"c": "Neuromusculaire", "q": "Ataxie de Friedreich : quels sont les principaux signes, et quelles atteintes surveiller en dehors du système nerveux ?", "a": "Elle débute en moyenne entre 10 et 15 ans : ataxie de la marche, réflexes abolis aux membres inférieurs, perte de la sensibilité vibratoire, dysarthrie. Il faut surveiller la scoliose (60 à 84 %), le pied creux, la cardiomyopathie, première cause de décès, et le diabète (8 à 32 %).", "s": "Friedreich Ataxia Guidelines Panel 2022 – Clinical management guidelines for Friedreich ataxia, chapitre 1", "u": "https://frdaguidelines.org/wp-content/uploads/2022/06/Chp1-Overview-of-Friedreich-ataxia-Final-30May22.pdf", "f": 30}, {"c": "Neuromusculaire", "q": "Enfant de 10 ans avec une maladie de Charcot-Marie-Tooth, qui trébuche et dont les pieds se creusent : que fait le MK ?", "a": "Il évalue la force des releveurs, la flexion dorsale de cheville, les pieds, l'équilibre et la marche, avec la CMTPedS. Il propose un renforcement progressif des releveurs, qui ralentit la perte de force sans surmenage. Il entretient la flexion dorsale par des étirements en charge, parfois des plâtres de nuit. Il discute orthèses et semelles, surveille le pied creux pour une éventuelle chirurgie, et encourage le sport.", "s": "Burns et al. 2017 (Lancet Child Adolesc Health) – Progressive resistance exercise for CMT in children: RCT", "u": "https://researchers.mq.edu.au/en/publications/safety-and-efficacy-of-progressive-resistance-exercise-for-charco/", "g": 1, "f": 30}, {"c": "Neuromusculaire", "q": "Charcot-Marie-Tooth chez l'enfant : le renforcement musculaire est-il utile et sans danger ?", "a": "Oui. Dans un essai chez 60 enfants de 6 à 17 ans, un renforcement progressif des releveurs du pied, 3 fois par semaine pendant 6 mois, a ralenti la perte de force sur 2 ans. Il n'a pas abîmé le muscle à l'IRM, ni entraîné de faiblesse de surmenage.", "s": "Burns et al. 2017 (Lancet Child Adolesc Health) – Progressive resistance exercise for CMT in children: RCT", "u": "https://researchers.mq.edu.au/en/publications/safety-and-efficacy-of-progressive-resistance-exercise-for-charco/", "f": 30}, {"c": "Neuromusculaire", "q": "Quand surveiller la scoliose dans la dystrophie musculaire de Duchenne ?", "a": "Surtout après la perte de la marche : examen clinique régulier et radiographies. Une arthrodèse est discutée en cas de progression. Les corticoïdes réduisent le risque.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 2 (respiratoire, cardiaque, orthopédie)", "u": "https://www.mda.org/sites/default/files/Duchenne_CareConsiderations_2018_Part2.pdf", "f": 27}, {"c": "Maladies chroniques et génétiques", "q": "Comment manipuler un nourrisson atteint d'ostéogenèse imparfaite ?", "a": "Mains larges qui soutiennent tronc et bassin, gestes lents et doux, jamais de torsion ni de traction sur un membre. Soulever les fesses (et non les jambes) pour changer la couche. Alterner les positions (dos, ventre, côté) et n'asseoir l'enfant qu'une fois le contrôle de la tête et du tronc acquis. Le MK apprend ces gestes aux parents, en sachant que des fractures restent possibles malgré une manipulation soigneuse.", "s": "Mueller et al. 2018 – Consensus statement on physical rehabilitation in children with osteogenesis imperfecta (OJRD)", "u": "https://ojrd.biomedcentral.com/articles/10.1186/s13023-018-0905-4", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "L'exercice est-il sûr dans l'arthrite juvénile idiopathique ?", "a": "Oui : l'exercice n'aggrave pas l'arthrite et aucun effet indésirable n'a été rapporté. La revue Cochrane (3 essais, 212 enfants) ne montre cependant pas de bénéfice significatif sur la fonction, la qualité de vie ou la capacité aérobie : les effets sont jugés prometteurs mais les essais trop peu nombreux. En pratique, le MK propose une activité régulière adaptée, en dehors des poussées.", "s": "Cochrane – Exercise therapy for juvenile idiopathic arthritis (CD005954)", "u": "https://cochranelibrary.com/cdsr/doi/10.1002/14651858.CD005954.pub2/pdf/CDSR/CD005954/CD005954_abstract.pdf", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Arthrite juvénile : que faire sur une articulation en poussée inflammatoire ?", "a": "Repos relatif et protection (attelle de repos si besoin), mobilisation douce pour garder l'amplitude, éviter les impacts sur l'articulation inflammée.", "s": "Cochrane – Exercise therapy for juvenile idiopathic arthritis", "u": "https://cochranelibrary.com/cdsr/doi/10.1002/14651858.CD005954/full", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Quels problèmes orthopédiques sont fréquents dans la trisomie 21 ?", "a": "Pieds plats, instabilité de la rotule, instabilité de hanche, scoliose, liés à la laxité ligamentaire.", "s": "JPOSNA – Orthopaedic management in Down syndrome: current concept review", "u": "https://jposna.org/index.php/jposna/article/view/283", "f": 32}, {"c": "Maladies chroniques et génétiques", "q": "Qu'est-ce que l'ostéogenèse imparfaite, et quels sont les objectifs de kinésithérapie ?", "a": "Une maladie génétique du collagène de type I (gènes COL1A1 ou COL1A2 le plus souvent), qui rend l'os fragile. Classification de Sillence : forme légère (I), létale (II), sévère et déformante (III), modérée (IV). Objectifs de rééducation (consensus 2018) : maximiser mobilité, fonction et participation en tenant compte de la peur de la fracture. Renforcer tronc et membres. Rééduquer tôt après une fracture pour éviter l'immobilisation. Proposer aides techniques et orthèses, sans que le fauteuil remplace la station debout et la marche.", "s": "Mueller et al. 2018 – Consensus statement on physical rehabilitation in children with osteogenesis imperfecta (OJRD)", "u": "https://ojrd.biomedcentral.com/articles/10.1186/s13023-018-0905-4", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Hémophilie : quels signes évoquent une hémarthrose ?", "a": "Picotement ou gêne au début, puis chaleur, gonflement, douleur et perte de mobilité. Traitement substitutif rapide. En phase aiguë, le MK applique la protection, le repos, le froid, la compression et la surélévation, avec attelle et décharge (aides techniques).", "s": "National Hemophilia Foundation – Physical therapy management of joint bleeds (guide)", "u": "https://www.bleeding.org/sites/default/files/document/files/Appendix-D-Joint-Bleeds-PT-Management.pdf", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Hémophilie : quel est l'objectif de la kinésithérapie après une hémarthrose ?", "a": "Récupérer amplitude, force et proprioception pour éviter récidive et arthropathie. Quand la douleur au repos disparaît : mobilisation active douce et indolore, reprise progressive de l'appui, renforcement progressif. Puis renforcement en chaîne ouverte et fermée, proprioception, sport adapté. Pas de retour au sport avant une amplitude complète et indolore et une force récupérée. Éviter les exercices agressifs et coordonner avec l'équipe d'hématologie.", "s": "National Hemophilia Foundation – Physical therapy management of joint bleeds (guide)", "u": "https://www.bleeding.org/sites/default/files/document/files/Appendix-D-Joint-Bleeds-PT-Management.pdf", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Oncologie pédiatrique : l'activité physique est-elle possible pendant le traitement ?", "a": "Oui : adaptée, elle est sûre et aide à limiter fatigue, déconditionnement et perte de force. Les recommandations internationales iPOEG (2021) affirment que bouger est important pour tous les enfants et adolescents atteints de cancer, avec un programme individualisé faute de données suffisantes sur la dose idéale.", "s": "Wurz et al. 2021 – International Pediatric Oncology Exercise Guidelines (iPOEG)", "u": "https://www.utupub.fi/items/95444c66-5a6f-4cfb-963e-3fcbe2502089/full", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Oncologie pédiatrique : quelles précautions avant une séance de kinésithérapie ?", "a": "Vérifier l'état du jour (plaquettes, neutrophiles, hémoglobine, fièvre), protéger le cathéter central et adapter : plaquettes basses → éviter chutes et chocs. Neutropénie → hygiène stricte du matériel et des mains. Anémie → faible intensité et pauses. Arrêter en cas de douleur nouvelle, vertiges, palpitations ou douleur thoracique.", "s": "Société de leucémie et lymphome du Canada – Activité physique de l'enfant atteint de cancer du sang (0-4 ans)", "u": "https://www.bloodcancers.ca/sites/default/files/2021-07/LLS834-F-Exercise-Guidelines-A-Final%20for%20the%20website.pdf", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Hémophilie : comment la sévérité est-elle définie ?", "a": "Par le taux de facteur VIII (hémophilie A) ou IX (hémophilie B). Sévère sous 1 %, modérée de 1 à 5 %, mineure de 5 à 40 %. Dans les formes sévères, les saignements surviennent sans traumatisme.", "s": "EAHAD – Clinical practice guideline for physiotherapy in haemophilia", "u": "https://www.eahad.org/wp-content/uploads/2024/05/Clinical-practice-guideline-for-physiotherapy-in-haemophilia.pdf", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "OI, AJI, hémophilie, cancer : pourquoi dit-on « adapter au jour, pas interdire » ?", "a": "Parce que bouger reste la règle dans ces maladies, et que les risques varient d'un jour à l'autre. OI : soutenir sans jamais tirer. AJI : repos relatif sur une articulation en poussée, renforcement hors poussée. Hémophilie : traiter d'abord le saignement, puis reprendre progressivement. Oncologie : séance adaptée au bilan du jour (plaquettes, neutrophiles, anémie, cathéter).", "s": "Wurz et al. 2021 – International Pediatric Oncology Exercise Guidelines (iPOEG)", "u": "https://www.utupub.fi/items/95444c66-5a6f-4cfb-963e-3fcbe2502089/full", "g": 1, "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Trisomie 21, syndrome de Rett, arthrogrypose : quel est le principal point de vigilance pour le MK dans chacun ?", "a": "Trisomie 21 : l'instabilité atlanto-axoïdienne. Douleur cervicale, changement de marche ou troubles sphinctériens imposent un avis urgent. Rett : la régression motrice et le risque de scoliose, d'où l'objectif de maintenir la marche. Arthrogrypose : ne jamais forcer une mobilisation, car l'os est fragile, et commencer très tôt.", "s": "Child Development (Australie) – Rett syndrome : stades et prise en charge", "u": "https://childdevelopment.com.au/areas-of-concern/diagnoses/rett-syndrome/", "g": 1, "f": 32}, {"c": "Maladies chroniques et génétiques", "q": "Enfant avec une cardiopathie congénitale : faut-il limiter son activité physique par précaution ?", "a": "Non. Selon l'American Heart Association (2013), par défaut, tout enfant avec une cardiopathie doit être autorisé et encouragé à bouger. Des précautions particulières, fixées par le cardiologue, concernent certaines situations : troubles du rythme, dysfonction ventriculaire, dilatation de l'aorte, malaise à l'effort, hypoxie, anticoagulants, appareils implantés. Les restrictions larges font plus de mal que de bien.", "s": "Longmuir et al. 2013 (Circulation) – Promotion of physical activity for children and adults with congenital heart disease (AHA)", "u": "https://professional.heart.org/en/science-news/Promotion-of-Physical-Activity-for-Children-and-Adults-with-Congenital-Heart-Disease/commentary", "f": 33}, {"c": "Maladies chroniques et génétiques", "q": "Enfant opéré d'une cardiopathie congénitale : quel est le rôle du MK, de la chirurgie au sport ?", "a": "Après la chirurgie, il privilégie les techniques actives : lever, marche, respiration profonde, jeux de souffle. Il suit le protocole sternal de l'équipe. Il surveille le développement des enfants à haut risque. Il évalue la tolérance à l'effort, connaît les consignes du cardiologue, puis encourage une activité physique régulière et rassure la famille, car les restrictions larges font plus de mal que de bien.", "s": "Longmuir et al. 2013 (Circulation) – Promotion of physical activity for children and adults with congenital heart disease (AHA)", "u": "https://professional.heart.org/en/science-news/Promotion-of-Physical-Activity-for-Children-and-Adults-with-Congenital-Heart-Disease/commentary", "g": 1, "f": 33}, {"c": "Maladies chroniques et génétiques", "q": "Comment définit-on l'arthrite juvénile idiopathique ?", "a": "Une arthrite qui débute avant 16 ans, dure au moins 6 semaines et n'a pas d'autre cause. L'ILAR distingue 7 catégories. La forme oligoarticulaire est la plus fréquente. Elle expose à une uvéite parfois silencieuse, d'où un suivi ophtalmologique régulier.", "s": "Makay et al. 2013 (World J Rheumatol) – Juvenile idiopathic arthritis", "u": "https://www.wjgnet.com/2220-3214/full/v3/i3/16.htm", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Enfant hémophile avec un flessum de hanche douloureux : à quoi penser ?", "a": "À un hématome du psoas, qui peut imiter une atteinte de hanche. Le traitement substitutif rapide passe en premier. La kinésithérapie reprend quand la douleur au repos a disparu.", "s": "EAHAD – Clinical practice guideline for physiotherapy in haemophilia", "u": "https://www.eahad.org/wp-content/uploads/2024/05/Clinical-practice-guideline-for-physiotherapy-in-haemophilia.pdf", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Pourquoi traiter la constipation chez un enfant qui a des fuites urinaires ?", "a": "Parce que vessie et intestin fonctionnent ensemble (dysfonction vésico-intestinale). Un rectum plein gêne la vessie. Sans traitement de la constipation, l'urothérapie échoue. La constipation fonctionnelle touche 5 à 30 % des enfants.", "s": "Singh & Connor 2018 (Aust J Gen Pract) – Paediatric constipation: an approach and evidence-based treatment regimen", "u": "https://www1.racgp.org.au/getattachment/40781468-f50c-4c9d-961d-b5621b14f17a/Paediatric-constipation.aspx", "f": 35}, {"c": "Maladies chroniques et génétiques", "q": "Quelle posture et quelles habitudes aux toilettes conseiller à un enfant constipé ?", "a": "Pieds bien posés au sol ou sur un marchepied, tronc légèrement penché en avant, ventre relâché. S'asseoir 5 minutes après chaque repas, avec un tableau de réussite. Viser des selles de type 5 ou 6 sur l'échelle de Bristol.", "s": "Singh & Connor 2018 (Aust J Gen Pract) – Paediatric constipation: an approach and evidence-based treatment regimen", "u": "https://www1.racgp.org.au/getattachment/40781468-f50c-4c9d-961d-b5621b14f17a/Paediatric-constipation.aspx", "f": 35}, {"c": "Maladies chroniques et génétiques", "q": "Comment diagnostiquer un surpoids ou une obésité chez l'enfant ?", "a": "Sur les courbes d'IMC du carnet de santé. Après 2 ans, le surpoids commence au seuil IOTF 25 et l'obésité au seuil IOTF 30. Doivent alerter : une courbe qui monte sans cesse, un rebond d'adiposité précoce, un changement rapide de couloir. En France, en 2015, 17 % des 6-17 ans étaient en surpoids, dont 4 % obèses.", "s": "HAS 2022 – Surpoids et obésité de l'enfant et de l'adolescent : fiche parcours", "u": "https://www.has-sante.fr/upload/docs/application/pdf/2022-02/fiche_parcours_surpoids_et_obesite_enfants_adolescents.pdf", "f": 34}, {"c": "Maladies chroniques et génétiques", "q": "Hémophilie : quels sports conseiller ?", "a": "Les activités à faible risque de choc (natation, vélo, marche) sont encouragées. Les sports de contact sont déconseillés.", "s": "EAHAD – Clinical practice guideline for physiotherapy in haemophilia", "u": "https://www.eahad.org/wp-content/uploads/2024/05/Clinical-practice-guideline-for-physiotherapy-in-haemophilia.pdf", "f": 31}, {"c": "Maladies chroniques et génétiques", "q": "Enfant hypermobile : quels signes doivent faire discuter un syndrome d'Ehlers-Danlos ?", "a": "Une hypermobilité associée à une peau fine, des cicatrices anormales ou des luxations. Ce tableau se discute avec le médecin.", "s": "Engelbert et al. 2017 – Evidence-based rationale for physical therapy of JHS/hEDS", "u": "https://www.ehlers-danlos.com/wp-content/uploads/2022/03/Engelbert_et_al-2017-American_Journal_of_Medical_Genetics_Part_C-_Seminars_in_Medical_Genetics.pdf", "f": 42}, {"c": "Maladies chroniques et génétiques", "q": "Pourquoi certains enfants hypermobiles ont-ils mal, alors que l'hypermobilité est souvent sans conséquence ?", "a": "Chez certains, un déconditionnement, une proprioception moins précise et un contrôle moteur moins efficace entretiennent les douleurs. D'où une prise en charge par l'éducation et l'exercice progressif, plutôt que l'arrêt des activités. L'hypermobilité diminue avec l'âge.", "s": "Engelbert et al. 2017 – Evidence-based rationale for physical therapy of JHS/hEDS", "u": "https://www.ehlers-danlos.com/wp-content/uploads/2022/03/Engelbert_et_al-2017-American_Journal_of_Medical_Genetics_Part_C-_Seminars_in_Medical_Genetics.pdf", "f": 42}, {"c": "Maladies chroniques et génétiques", "q": "Diabète de type 1 : comment l'effort agit-il sur la glycémie ?", "a": "L'effort aérobie (course, vélo, natation) la fait baisser. L'effort bref et intense (sprint, musculation) peut la faire monter. Après 45 minutes d'effort, le risque d'hypoglycémie dure 7 à 11 heures, surtout la nuit après un effort en fin d'après-midi.", "s": "Adolfsson et al. 2022 (Pediatr Diabetes) – ISPAD guidelines : exercise in children and adolescents with diabetes", "u": "https://www.chuv.ch/fileadmin/sites/dedop/ISPAD_clinical_practice_consensus_guidelines_2022.pdf", "f": 34}, {"c": "Maladies chroniques et génétiques", "q": "Enfant diabétique de type 1 : quelle glycémie avant l'effort, et quand ne pas faire d'effort ?", "a": "La zone conseillée pour commencer est de 1,26 à 1,80 g/L (7 à 10 mmol/L). Sous 0,70 g/L, on traite l'hypoglycémie et on attend plus de 0,90 g/L. Sous 0,54 g/L, pas d'effort. Au-dessus de 2,70 g/L, on mesure les cétones : à 1,5 mmol/L ou plus, pas d'effort.", "s": "Adolfsson et al. 2022 (Pediatr Diabetes) – ISPAD guidelines : exercise in children and adolescents with diabetes", "u": "https://www.chuv.ch/fileadmin/sites/dedop/ISPAD_clinical_practice_consensus_guidelines_2022.pdf", "f": 34}, {"c": "Maladies chroniques et génétiques", "q": "Enfant de 10 ans avec un diabète de type 1 qui veut jouer au foot : comment l'accompagner ?", "a": "Encourager l'activité, 60 minutes par jour comme tous les enfants. Connaître son plan de soins et les signes de son hypoglycémie. Vérifier la glycémie avant le match, viser 1,26 à 1,80 g/L, prévoir des glucides pendant l'effort et penser au risque d'hypoglycémie la nuit suivante. Ne pas jouer si les cétones sont à 1,5 mmol/L ou plus. Laisser les doses d'insuline à l'équipe de diabétologie.", "s": "Adolfsson et al. 2022 (Pediatr Diabetes) – ISPAD guidelines : exercise in children and adolescents with diabetes", "u": "https://www.chuv.ch/fileadmin/sites/dedop/ISPAD_clinical_practice_consensus_guidelines_2022.pdf", "g": 1, "f": 34}, {"c": "Maladies chroniques et génétiques", "q": "Comment se cote le score de Beighton, et quel seuil chez l'enfant ?", "a": "9 points (auriculaires, pouces, coudes, genoux, flexion du tronc mains à plat). Chez l'enfant prépubère, un score de 6 ou plus évoque une hypermobilité généralisée.", "s": "AJGP 2022 – Hypermobility syndromes in children and adolescents (figure Beighton)", "u": "https://www1.racgp.org.au/getattachment/AJGP/2022/June/Hypermobility-syndromes-in-children-and-adolescent/AJGP-06-2022-Focus-Nicholson-Hypermobility-Syndromes-Children-Fig-1.pdf.aspx?lang=en-AU", "f": 42}, {"c": "Maladies chroniques et génétiques", "q": "Comment prendre en charge un enfant hypermobile douloureux ?", "a": "Éducation (comprendre la douleur, impliquer la famille) et exercice progressif : renforcement, stabilité du tronc, endurance, proprioception, plutôt que l'arrêt des activités. Dans un essai chez 57 enfants, un programme général comme un programme ciblé sur les articulations douloureuses ont réduit la douleur. Progresser lentement, éviter ce qui majore la douleur. Semelles si pied plat douloureux.", "s": "Engelbert et al. 2017 – Evidence-based rationale for physical therapy of JHS/hEDS", "u": "https://www.ehlers-danlos.com/wp-content/uploads/2022/03/Engelbert_et_al-2017-American_Journal_of_Medical_Genetics_Part_C-_Seminars_in_Medical_Genetics.pdf", "f": 42}, {"c": "Maladies chroniques et génétiques", "q": "Enfant hypermobile douloureux : que recherche le bilan, en plus du score de Beighton ?", "a": "La douleur, la force, l'endurance, l'équilibre et le retentissement sur la vie quotidienne. Ces éléments servent à fixer les objectifs de l'exercice progressif.", "s": "AJGP 2022 – Hypermobility syndromes in children and adolescents (figure Beighton)", "u": "https://www1.racgp.org.au/getattachment/AJGP/2022/June/Hypermobility-syndromes-in-children-and-adolescent/AJGP-06-2022-Focus-Nicholson-Hypermobility-Syndromes-Children-Fig-1.pdf.aspx?lang=en-AU", "f": 42}, {"c": "Maladies chroniques et génétiques", "q": "Dyssynergie mictionnelle : qu'est-ce que c'est, et comment la rééduquer ?", "a": "L'enfant contracte le sphincter ou le plancher pelvien pendant qu'il urine, sans atteinte neurologique. Après l'urothérapie standard, le biofeedback lui apprend, par des signaux visuels ou sonores, à relâcher volontairement son plancher pelvien.", "s": "ESPU – Urotherapy book : standard urotherapy", "u": "https://www.espu.org/e-books/Urotherapy_book/12/", "f": 35}, {"c": "Maladies chroniques et génétiques", "q": "La capacité d'effort des enfants avec une cardiopathie congénitale est-elle diminuée ?", "a": "Souvent, oui. Dans une méta-analyse de 21 études, la VO2 pic était inférieure de 7,9 mL/kg/min à celle des enfants en bonne santé, et de 10 mL/kg/min chez l'adolescent. Le réentraînement est considéré comme sûr. Il allonge la durée d'effort, sans gain net démontré de VO2 pic.", "s": "Villaseca-Rojas et al. 2022 (Front Cardiovasc Med) – Exercise capacity in children and adolescents with congenital heart disease", "u": "https://repositorio.uchile.cl/handle/2250/195852", "f": 33}, {"c": "Respiratoire", "q": "Quelle est la position de la HAS sur la kinésithérapie respiratoire dans la bronchiolite ?", "a": "AFE non recommandée chez le nourrisson hospitalisé (grade B). Drainage postural, vibrations et clapping contre-indiqués (grade A). En ambulatoire, désencombrement bronchique non recommandé faute de données (accord d'experts), à discuter en cas de comorbidités. Recommandé : désobstruction rhinopharyngée (grade C), surveillance, éducation des parents.", "s": "HAS 2019 – Bronchiolite aiguë du nourrisson (synthèse AP-HP)", "u": "https://affairesjuridiques.aphp.fr/textes/recommandations-prise-en-charge-du-premier-episode-de-la-bronchiolite-aigue-chez-le-nourrisson-de-moins-de-12-mois-nov-2019/", "f": 36}, {"c": "Respiratoire", "q": "Comment la HAS définit-elle la bronchiolite aiguë ?", "a": "Premier épisode chez un nourrisson de moins de 12 mois : rhinite puis toux, signes respiratoires (polypnée, signes de lutte, sibilants ou crépitants), en contexte épidémique.", "s": "HAS 2019 – Bronchiolite aiguë du nourrisson (synthèse AP-HP)", "u": "https://affairesjuridiques.aphp.fr/textes/recommandations-prise-en-charge-du-premier-episode-de-la-bronchiolite-aigue-chez-le-nourrisson-de-moins-de-12-mois-nov-2019/", "f": 36}, {"c": "Respiratoire", "q": "Quels critères orientent vers une bronchiolite grave selon la HAS ?", "a": "Fréquence respiratoire très élevée ou basse, saturation basse (inférieure à environ 90 %), signes de lutte marqués, alimentation inférieure à 50 % de l'habituel, apnées, mauvaise tolérance clinique.", "s": "HAS 2019 – Bronchiolite aiguë du nourrisson (synthèse AP-HP)", "u": "https://affairesjuridiques.aphp.fr/textes/recommandations-prise-en-charge-du-premier-episode-de-la-bronchiolite-aigue-chez-le-nourrisson-de-moins-de-12-mois-nov-2019/", "f": 36}, {"c": "Respiratoire", "q": "Quels nourrissons sont à risque de bronchiolite grave ?", "a": "Âge inférieur à 2 mois, prématurité, cardiopathie, pathologie pulmonaire chronique, déficit immunitaire, contexte social défavorable.", "s": "HAS 2019 – Bronchiolite aiguë du nourrisson (synthèse AP-HP)", "u": "https://affairesjuridiques.aphp.fr/textes/recommandations-prise-en-charge-du-premier-episode-de-la-bronchiolite-aigue-chez-le-nourrisson-de-moins-de-12-mois-nov-2019/", "f": 36}, {"c": "Respiratoire", "q": "Qu'est-ce que la désobstruction rhinopharyngée (DRP) ?", "a": "Un lavage des fosses nasales au sérum physiologique, nourrisson sur le côté, plusieurs fois par jour, pour libérer les voies aériennes supérieures. La HAS la recommande comme mesure de soutien (grade C), avant d'évaluer la gravité. La SPLF (2024) ne peut pas conclure sur son efficacité avant 3 ans, faute d'études.", "s": "HAS 2019 – Bronchiolite aiguë du nourrisson (synthèse AP-HP)", "u": "https://affairesjuridiques.aphp.fr/textes/recommandations-prise-en-charge-du-premier-episode-de-la-bronchiolite-aigue-chez-le-nourrisson-de-moins-de-12-mois-nov-2019/", "f": 36}, {"c": "Respiratoire", "q": "Quel est le rôle du MK dans la bronchiolite selon le Collège de la masso-kinésithérapie ?", "a": "Évaluer la gravité, surveiller l'évolution, éduquer les parents (DRP, signes d'aggravation) et orienter si besoin, en accord avec les recommandations HAS.", "s": "CMK / Ordre des MK 2023 – Bronchiolite : prise en charge par le kiné", "u": "https://www.ordremk.fr/wp-content/uploads/2023/11/texte-definitif-2023.pdf", "f": 36}, {"c": "Respiratoire", "q": "Le MK voit un nourrisson de 6 semaines pour une bronchiolite. Quelle démarche suit-il ?", "a": "Il évalue d'abord la gravité : âge de moins de 2 mois, saturation inférieure à environ 90 %, alimentation inférieure à 50 % de l'habituel, terrain à risque. Un signe de gravité impose d'orienter. Il réalise la désobstruction rhinopharyngée et éduque les parents (lavage de nez, surveillance, signes d'aggravation). Il ne fait pas de désencombrement bronchique systématique en ville.", "s": "HAS et CNPP 2019 – Prise en charge du 1er épisode de bronchiolite aiguë chez le nourrisson de moins de 12 mois : texte des recommandations (grades)", "u": "https://has-sante.fr/upload/docs/application/pdf/2019-11/hascnpp_bronchiolite_texte_recommandations_2019.pdf", "g": 1, "f": 36}, {"c": "Respiratoire", "q": "Pourquoi éviter le drainage postural tête en bas chez le nourrisson atteint de mucoviscidose ?", "a": "Il peut favoriser le reflux gastro-œsophagien. On utilise un drainage modifié, sans inclinaison tête en bas.", "s": "CF Trust 2020 – Standards of care for physiotherapy in cystic fibrosis (4e éd.)", "u": "https://www.cysticfibrosis.org.uk/sites/default/files/2020-12/Standards%20of%20Care%20and%20Good%20Clinical%20Practice%20for%20the%20Physiotherapy%20Management%20of%20Cystic%20Fibrosis%20Fourth%20edition%20December%202020.pdf", "f": 37}, {"c": "Respiratoire", "q": "Bronchiolite du nourrisson hospitalisé : quelle place pour les techniques manuelles ?", "a": "Il n'est pas recommandé de pratiquer l'AFE rapide pour améliorer l'état clinique (recommandation faible) : l'essai de Gajdos (2010) n'a pas montré de bénéfice et a relevé plus de vomissements et de déstabilisations respiratoires. Il est en revanche proposé d'utiliser les techniques lentes (AFE lente, expiration lente prolongée, drainage autogène assisté) pour améliorer l'état clinique à court terme (recommandation faible), sans effet sur la SpO2. Aucune recommandation hors de l'hôpital, faute d'études suffisantes. (Référence : SPLF 2024.)", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 36}, {"c": "Respiratoire", "q": "Qu'est-ce que l'expiration lente prolongée (ELPr) et pourquoi fractionner la pression chez le nourrisson ?", "a": "Une pression manuelle lente et simultanée sur le thorax et l'abdomen, commencée à la capacité résiduelle fonctionnelle, qui mobilise le volume de réserve expiratoire pour obtenir la meilleure déflation. Souvent suivie d'une toux provoquée. La fréquence respiratoire du nourrisson étant élevée, la pression est répartie sur 2 ou 3 temps expiratoires successifs pour éviter le collapsus bronchique.", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 36}, {"c": "Respiratoire", "q": "Drainage autogène assisté (DAA) chez le nourrisson : quel est le principe ?", "a": "C'est la version passive du drainage autogène, quand l'enfant ne peut pas coopérer. Les mains du MK accompagnent et maintiennent la cage thoracique à différents niveaux de volume pulmonaire, du bas volume (périphérie) vers le haut volume (voies proximales), sans augmenter la pression motrice, pour faire migrer les sécrétions sans provoquer de fermeture bronchique.", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 36}, {"c": "Respiratoire", "q": "Quel dispositif d'inhalation chez l'enfant asthmatique de moins de 5 ans ?", "a": "Un aérosol-doseur avec chambre d'inhalation, avec masque facial chez le jeune enfant puis embout buccal dès qu'il en est capable.", "s": "Australian Asthma Handbook – Choisir un dispositif d'inhalation (1-5 ans)", "u": "https://www.asthmahandbook.org.au/management/children-1-5-years/principles-of-management/selecting-inhalers-for-children-1-5-years", "f": 37}, {"c": "Respiratoire", "q": "Comment utiliser une chambre d'inhalation chez le jeune enfant ?", "a": "Une bouffée à la fois, puis plusieurs respirations calmes dans la chambre (environ 5-6). Répéter pour chaque bouffée.", "s": "Australian Asthma Handbook – Choisir un dispositif d'inhalation (1-5 ans)", "u": "https://www.asthmahandbook.org.au/management/children-1-5-years/principles-of-management/selecting-inhalers-for-children-1-5-years", "f": 37}, {"c": "Respiratoire", "q": "Mucoviscidose : techniques de désencombrement selon l'âge, place de l'activité physique ?", "a": "Nourrisson : techniques passives, drainage autogène assisté. Dès 3-4 ans : PEP (masque, PEP oscillante), cycle actif, expirations lentes. Après 8-12 ans : drainage autogène autonome. Après les aérosols. Activité physique fortement recommandée, en complément. Besoins réévalués sous modulateurs de CFTR.", "s": "CF Trust 2020 – Standards of care for physiotherapy in cystic fibrosis (4e éd.)", "u": "https://www.cysticfibrosis.org.uk/sites/default/files/2020-12/Standards%20of%20Care%20and%20Good%20Clinical%20Practice%20for%20the%20Physiotherapy%20Management%20of%20Cystic%20Fibrosis%20Fourth%20edition%20December%202020.pdf", "f": 37}, {"c": "Respiratoire", "q": "Maladies neuromusculaires : mesures respiratoires à surveiller, quand une aide à la toux ?", "a": "CVF assis/couché, DEP toux, PImax/PEmax, SNIP, oxymétrie/capnographie nocturne. DMD, recommandations 2018 : recrutement de volume si CVF ≤ 60 %. Aide à la toux (manuelle ou mécanique) si CVF < 50 %, DEP toux < 270 L/min ou PEmax < 60 cmH2O.", "s": "Air stacking et toux assistée dans la DMD (seuils des recommandations 2018)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6912939/", "f": 29}, {"c": "Respiratoire", "q": "Quel est le mécanisme de la mucoviscidose ?", "a": "Une anomalie de la protéine CFTR qui altère les échanges d'eau et de sel : les sécrétions bronchiques sont épaisses, favorisant obstruction et infections.", "s": "CF Trust 2020 – Standards of care for physiotherapy in cystic fibrosis (4e éd.)", "u": "https://www.cysticfibrosis.org.uk/sites/default/files/2020-12/Standards%20of%20Care%20and%20Good%20Clinical%20Practice%20for%20the%20Physiotherapy%20Management%20of%20Cystic%20Fibrosis%20Fourth%20edition%20December%202020.pdf", "f": 37}, {"c": "Respiratoire", "q": "Une technique de désencombrement est-elle supérieure aux autres dans la mucoviscidose ?", "a": "Non : aucune technique n'a montré de supériorité nette, ni entre techniques manuelles, ni entre appareils de PEP (SPLF 2024 : pas de PEP à privilégier, recommandation faible). On choisit selon l'âge, la préférence et l'adhésion du patient. Tenir compte de sa préférence est recommandé (recommandation forte).", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 37}, {"c": "Respiratoire", "q": "Quels sont les bénéfices de l'activité physique dans la mucoviscidose ?", "a": "Amélioration de la capacité d'exercice, aide au désencombrement, meilleure qualité de vie et bien-être.", "s": "Physical activity in children with CF: a narrative review", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12293581/", "f": 37}, {"c": "Respiratoire", "q": "Pourquoi l'hygiène est-elle centrale en kinésithérapie respiratoire dans la mucoviscidose ?", "a": "Pour éviter les infections croisées entre patients : nettoyage et désinfection du matériel, séparation des patients.", "s": "CF Trust 2020 – Standards of care for physiotherapy in cystic fibrosis (4e éd.)", "u": "https://www.cysticfibrosis.org.uk/sites/default/files/2020-12/Standards%20of%20Care%20and%20Good%20Clinical%20Practice%20for%20the%20Physiotherapy%20Management%20of%20Cystic%20Fibrosis%20Fourth%20edition%20December%202020.pdf", "f": 37}, {"c": "Respiratoire", "q": "Quel seuil de débit de toux traduit une toux inefficace dans les maladies neuromusculaires ?", "a": "Un DEP toux inférieur à environ 160 L/min est inefficace. Sous 270 L/min, le risque d'encombrement augmente lors des infections. Les recommandations SPLF 2024 situent la toux efficace au-delà de 270-300 L/min et le recours à l'aide mécanique à la toux sous 160-180 L/min.", "s": "Air stacking et toux assistée dans la DMD (seuils des recommandations 2018)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6912939/", "f": 29}, {"c": "Respiratoire", "q": "Qu'est-ce que l'insufflation-exsufflation mécanique ?", "a": "Un appareil qui insuffle une pression positive puis applique rapidement une pression négative pour simuler une toux efficace.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 2 (respiratoire, cardiaque, orthopédie)", "u": "https://www.mda.org/sites/default/files/Duchenne_CareConsiderations_2018_Part2.pdf", "f": 29}, {"c": "Respiratoire", "q": "Quels signes doivent faire rechercher une hypoventilation nocturne chez un enfant neuromusculaire ?", "a": "Céphalées matinales, fatigue, somnolence diurne, réveils nocturnes, baisse des performances scolaires.", "s": "Birnkrant et al. 2018 – Duchenne care considerations, partie 2 (respiratoire, cardiaque, orthopédie)", "u": "https://www.mda.org/sites/default/files/Duchenne_CareConsiderations_2018_Part2.pdf", "f": 29}, {"c": "Respiratoire", "q": "Qu'est-ce que la dyskinésie ciliaire primitive ?", "a": "Une maladie génétique des cils respiratoires : encombrement bronchique chronique dès la naissance, rhinosinusites, otites, parfois situs inversus.", "s": "ACPRC – Physiotherapy national standards of care for children with primary ciliary dyskinesia", "u": "https://www.acprc.org.uk/physiotherapy-in-respiratory-care/editions/phys-resp-care-volume-1-1/physiotherapy-english-national-standards-of-care-for-children-and-young-people-with-primary-ciliary-dyskinesia/", "f": 37}, {"c": "Respiratoire", "q": "Pourquoi la toux et l'exercice sont-ils centraux dans la dyskinésie ciliaire primitive ?", "a": "Le transport mucociliaire étant inefficace, la toux devient le principal moyen d'évacuer les sécrétions. Désencombrement quotidien et activité physique sont donc essentiels.", "s": "ACPRC – Physiotherapy national standards of care for children with primary ciliary dyskinesia", "u": "https://www.acprc.org.uk/physiotherapy-in-respiratory-care/editions/phys-resp-care-volume-1-1/physiotherapy-english-national-standards-of-care-for-children-and-young-people-with-primary-ciliary-dyskinesia/", "f": 37}, {"c": "Respiratoire", "q": "Aspiration trachéale : comment choisir la taille de la sonde ?", "a": "En général environ deux fois le diamètre interne de la canule (sonde en charrière, Ch), pour ne pas obstruer la canule et limiter le risque d'hypoxie.", "s": "SickKids Connected Care – Taille de sonde pour l'aspiration trachéale", "u": "https://connectedcare.sickkids.ca/what-is-the-correct-catheter-size-when-suctioning-a-trach/", "f": 38}, {"c": "Respiratoire", "q": "Aspiration trachéale : jusqu'où et combien de temps aspirer ?", "a": "À une profondeur pré-mesurée sur une canule de même taille, sans dépasser son extrémité. Moins de 5 secondes, en aspirant pendant le retrait de la sonde, avec une dépression d'environ 80 à 100 mmHg. Pas d'instillation systématique de sérum.", "s": "Children's Health Ireland – Aspiration chez l'enfant trachéotomisé", "u": "https://childrenshealthireland.ie/documents/2173/CHI-_TRACHEOSTOMY_CARE-_SUCTIONING_A_SELF-VENTILATING_CHILD_WITH_A_TRACHEOSTOMY.pdf", "f": 38}, {"c": "Respiratoire", "q": "Quel est le principe de la ventilation à percussions intrapulmonaires (VPI), et faut-il l'utiliser de façon systématique pour désencombrer ?", "a": "Un appareil (phasitron couplé à un nébuliseur) délivre de petits volumes d'air à haute fréquence, environ 80 à 650 percussions par minute, à des pressions d'environ 10 à 30 cmH2O (5 à 35 selon les recommandations SPLF 2024), pendant 15 à 40 minutes. La revue (12 études, qualité faible à modérée) ne soutient pas son usage systématique comme technique de désencombrement. Elle recommande d'humidifier le gaz, froid et sec. (Référence : Reychler 2018.)", "s": "Reychler et al. 2018 (Respiratory Care) – Intrapulmonary percussive ventilation as an airway clearance technique: systematic review", "u": "https://arodes.hes-so.ch/record/3183/files/Reychler_2018_intrapulmonary_percussive_ventilation.pdf?version=1", "f": 29}, {"c": "Respiratoire", "q": "Chez l'enfant, quelles sont les contre-indications absolues de la VPI selon le protocole des HUG ?", "a": "Pneumothorax non drainé (ou drain clampé), hémoptysie massive, hémothorax et syndrome de Lyell. Parmi les contre-indications relatives : toux inefficace (débit de pointe < 180 L/min, car les sécrétions remontées risquent d'obstruer la trachée), troubles de la coagulation, épilepsie, hypertension intracrânienne, chirurgie ORL récente. Les recommandations SPLF 2024 ne retiennent que le pneumothorax non drainé comme contre-indication absolue. Antécédent de pneumothorax, hémoptysie, insuffisance cardiovasculaire, défaut de coopération et vomissements y sont relatifs.", "s": "HUG (Genève) – Ventilation à percussions intrapulmonaires chez l'enfant : protocole de physiothérapie", "u": "https://www.hug.ch/vdoc/HUG_000000719.pdf", "f": 29}, {"c": "Respiratoire", "q": "VPI chez l'enfant : comment choisir la fréquence des percussions selon l'objectif (protocole des HUG) ?", "a": "Fréquences rapides (> 300 cycles/min) pour le désencombrement distal ou les atélectasies, 60 à 250 cycles/min pour la ventilation, la compliance et l'élimination du CO2. Syndrome obstructif : pression faible et fréquence rapide. Restrictif : pression élevée et fréquence lente. Séance d'environ 20 minutes, sans dépasser 30, au moins une heure après le repas.", "s": "HUG (Genève) – Ventilation à percussions intrapulmonaires chez l'enfant : protocole de physiothérapie", "u": "https://www.hug.ch/vdoc/HUG_000000719.pdf", "f": 29}, {"c": "Respiratoire", "q": "In-exsufflateur (aide mécanique à la toux) : comment régler et ajuster les pressions ?", "a": "Les réglages de départ souvent cités sont +40/−40 cmH2O, à atteindre progressivement selon la tolérance. En Europe, on titre plutôt de façon individualisée, par exemple en partant de +20/−20 cmH2O et en augmentant par paliers de 5. Un temps d'insufflation plus long que l'exsufflation améliore volumes et débits. Si la glotte se ferme, on baisse la pression ou le débit d'insufflation et on allonge le temps inspiratoire. On vérifie avec les courbes ou l'auscultation de la trachée.", "s": "Chatwin et al. 2024 (J Clin Med) – Waves of precision: evaluating mechanical in-exsufflation efficacy in neuromuscular disorders", "u": "https://www.mdpi.com/2077-0383/13/9/2643", "f": 29}, {"c": "Respiratoire", "q": "Quelles sont les contre-indications de l'in-exsufflation mécanique ?", "a": "Emphysème bulleux, pneumothorax non drainé ou à risque, pneumomédiastin, barotraumatisme récent, instabilité cardiaque (surveiller pouls et saturation), fistule trachéo-œsophagienne. Elle n'est pas utile si le débit de pointe à la toux est élevé (au-delà d'environ 300 L/min), car le débit expiratoire du patient dépasse alors celui de l'appareil.", "s": "Chatwin & Wakeman 2023 (J Clin Med) – Mechanical insufflation-exsufflation: considerations for improving clinical practice", "u": "https://www.mdpi.com/2077-0383/12/7/2626", "f": 29}, {"c": "Respiratoire", "q": "Chez l'enfant neuromusculaire, l'usage quotidien d'un in-exsufflateur réduit-il les hospitalisations ?", "a": "Dans cette étude rétrospective de 37 enfants, les hospitalisations pour infection respiratoire sont passées de 3,7 à 0,9 pour 1 000 jours, et les jours d'hospitalisation de 33,6 à 2,7 pour 1 000 jours, avec une bonne satisfaction. Étude monocentrique sans groupe contrôle : association, pas preuve de causalité. (Référence : Veldhoen 2020.)", "s": "Veldhoen et al. 2020 (Pediatric Pulmonology) – Effect of mechanical insufflation-exsufflation in children with neuromuscular weakness", "u": "https://dspace.library.uu.nl/handle/1874/439294", "f": 29}, {"c": "Respiratoire", "q": "Aide à la toux chez l'enfant neuromusculaire : quels seuils de débit de toux, et que recommande la SPLF ?", "a": "Toux efficace au-delà de 270-300 L/min. Aide mécanique généralement envisagée sous 160-180 L/min. Recommandé : assistance expiratoire manuelle (recommandation forte), assistance inspiratoire, air stacking au ballon ou insufflation (recommandation forte), et surtout l'association inspiratoire + expiratoire manuelle (recommandation forte). Si l'assistance manuelle ne suffit pas : in-exsufflation mécanique (recommandation forte). L'exsufflation mécanique seule a augmenté le débit de toux chez l'adulte, pas chez l'enfant.", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 29}, {"c": "Respiratoire", "q": "VPI : quelles recommandations la SPLF formule-t-elle selon la pathologie ?", "a": "Proposée chez les patients neuromusculaires ou neurologiques avec complications respiratoires pour réduire hospitalisations et antibiotiques (recommandation faible), et chez les neuromusculaires hypersécrétants pour aider à éliminer les sécrétions (recommandation faible). Non recommandée dans la mucoviscidose et les bronchiectasies pour la fonction pulmonaire, les sécrétions ou la dyspnée (recommandation faible). Bronchiolite : pas de recommandation (une seule étude, plutôt favorable). Seule contre-indication absolue selon la SPLF : le pneumothorax non drainé (le protocole des HUG en ajoute d'autres, voir la fiche 29).", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 29}, {"c": "Respiratoire", "q": "Désobstruction rhinopharyngée rétrograde (DRR) et lavage nasal : quel niveau de preuve chez l'enfant selon la SPLF ?", "a": "Avant 3 ans (infection des voies aériennes supérieures ou bronchiolite), aucune recommandation ne peut être faite sur la DRR, inspiration nasale forcée obtenue en fermant brièvement la bouche après instillation, ni sur le lavage nasal seul. Après 3 ans, en cas de rhinosinusite aiguë, le lavage nasal au sérum physiologique est proposé pour diminuer l'obstruction (recommandation faible). Le lavage nasal reste par ailleurs la mesure de base de la HAS dans la bronchiolite.", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 36}, {"c": "Respiratoire", "q": "Recommandations de la SPLF : que signifient « il est recommandé » et « il est proposé », et quelles populations pédiatriques ne sont pas couvertes ?", "a": "« Il est recommandé de » ou « de ne pas » signale une recommandation forte (G1). « Il est proposé » ou « il n'est pas recommandé » signale une recommandation faible (G2). Les lettres A à D indiquent la confiance dans le niveau de preuve. Les recommandations fortes sont rares et concernent surtout les patients très sécrétants. La paralysie cérébrale, la prématurité, les patients intubés et la COVID-19 ont été exclus, faute d'études : pour eux, le raisonnement clinique prime.", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 29}, {"c": "Respiratoire", "q": "Quelles sont les deux complications vitales de la trachéotomie chez l'enfant ?", "a": "Le bouchon muqueux et la décanulation accidentelle. Ce sont des urgences vitales.", "s": "Ghelab & Robichon (Robert-Debré, Timone) – Les soins à l'enfant trachéotomisé, présentation SFORL", "u": "https://www.sforl.org/wp-content/uploads/2022/10/Zina-GHELAB_Faustine-ROBICHON_Les-soins-a-lenfant-tracheotomise_compressed-1.pdf", "f": 38}, {"c": "Respiratoire", "q": "Que contient le kit d'urgence de l'enfant trachéotomisé, et que faire en cas de décanulation accidentelle ?", "a": "Une canule de même taille, une canule de taille inférieure, des sondes d'aspiration, un aspirateur et un ballon d'insufflation. En cas de décanulation, recanuler immédiatement avec la canule de même taille, ou de taille inférieure si elle ne passe pas. En cas d'échec, ventiler au ballon et appeler les secours.", "s": "Ghelab & Robichon (Robert-Debré, Timone) – Les soins à l'enfant trachéotomisé, présentation SFORL", "u": "https://www.sforl.org/wp-content/uploads/2022/10/Zina-GHELAB_Faustine-ROBICHON_Les-soins-a-lenfant-tracheotomise_compressed-1.pdf", "f": 38}, {"c": "Respiratoire", "q": "Maladie neuromusculaire : pourquoi recruter le volume pulmonaire avant d'aider la toux ?", "a": "Une toux efficace demande une grande inspiration, une fermeture de la glotte puis une expiration explosive. Quand les muscles inspiratoires faiblissent, l'enfant respire à petits volumes et sa toux devient faible. Recruter le volume (ballon, relaxateur de pression) redonne l'air nécessaire à la toux. L'aide à la toux, manuelle ou mécanique, se choisit ensuite selon le débit de toux. On mesure avant l'encombrement.", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "g": 1, "f": 29}, {"c": "Respiratoire", "q": "Mucoviscidose, dyskinésie ciliaire primitive, asthme : en quoi le rôle du MK diffère-t-il dans ces trois maladies ?", "a": "Mucoviscidose : désencombrement quotidien, technique choisie selon l'âge et l'adhésion, activité physique en complément, hygiène stricte. Dyskinésie ciliaire primitive : les cils ne fonctionnent pas, la toux et l'exercice deviennent les moyens centraux de désencombrer. Asthme : éducation à l'inhalation (chambre d'inhalation chez le jeune enfant) et activité physique.", "s": "CF Trust 2020 – Standards of care for physiotherapy in cystic fibrosis (4e éd.)", "u": "https://www.cysticfibrosis.org.uk/sites/default/files/2020-12/Standards%20of%20Care%20and%20Good%20Clinical%20Practice%20for%20the%20Physiotherapy%20Management%20of%20Cystic%20Fibrosis%20Fourth%20edition%20December%202020.pdf", "g": 1, "f": 37}, {"c": "Respiratoire", "q": "Pourquoi la formation des aidants conditionne-t-elle le retour à domicile d'un enfant trachéotomisé ?", "a": "Parce que les deux urgences vitales, bouchon muqueux et décanulation accidentelle, surviennent n'importe où. Un aidant formé et éveillé doit toujours être présent, avec le kit d'urgence. Il sait aspirer sans dépasser la canule, humidifier, soigner l'orifice et changer la canule en urgence.", "s": "Volsko et al. 2021 (Respir Care) – AARC guideline : management of pediatric patients with tracheostomy in the acute care setting", "u": "https://www.aarc.org/wp-content/uploads/2025/03/volsko-et-al-2021-aarc-clinical-practice-guideline-management-of-pediatric-patients-with-tracheostomy-in-the-acute-care.pdf", "g": 1, "f": 38}, {"c": "Respiratoire", "q": "Après une chirurgie cardiaque chez l'enfant, quelles techniques de kinésithérapie respiratoire privilégier ?", "a": "Les techniques actives, où l'enfant agit lui-même : se lever, marcher, respirer profondément, souffler dans des jeux chez le petit, ou utiliser un spiromètre incitatif (il inspire lentement pour faire monter une bille) chez le plus grand. Dans une méta-analyse de 11 études, elles faisaient mieux que les techniques passives. La percussion, les vibrations et l'aspiration n'ont prévenu ni les atélectasies ni les pneumonies, et la percussion faisait désaturer.", "s": "Beningfield & Jones 2018 (Physiotherapy) – Peri-operative chest physiotherapy for paediatric cardiac patients", "u": "https://researchonline.jcu.edu.au/52971/", "f": 33}, {"c": "Respiratoire", "q": "Kinésithérapie respiratoire chez l'enfant ventilé : que disent les preuves ?", "a": "Elles sont peu concluantes. Une revue de 13 études trouve des effets à court terme, sur la compliance ou les atélectasies, sans bénéfice clinique démontré. On la réserve aux indications claires, comme un encombrement ou une atélectasie, en surveillant la saturation.", "s": "Shkurka et al. 2021 (J Pediatr Intensive Care) – Chest physiotherapy for mechanically ventilated children: systematic review", "u": "https://discovery.ucl.ac.uk/id/eprint/10137707/", "f": 39}, {"c": "Respiratoire", "q": "Relaxateur de pression (IPPB, type Alpha 300) chez l'enfant neuromusculaire : principe, objectifs et dose ?", "a": "L'enfant déclenche des hyperinsufflations, à des volumes supérieurs à sa capacité spontanée, puis expire librement. Objectifs : ventiler toutes les zones pulmonaires, garder la cage thoracique souple, prévenir les atélectasies, rendre la toux plus efficace et soutenir le développement pulmonaire. Dès 18 mois-2 ans environ. Chez l'enfant, environ 1 heure par jour en 3 séances de 15-20 minutes. L'assistance inspiratoire (insufflation mécanique ou air stacking) est recommandée pour augmenter le débit de toux dans les maladies neuromusculaires (recommandation forte, SPLF 2024).", "s": "AFM-Téléthon – Du bon usage de l'Alpha 300 et autres relaxateurs de pression", "u": "https://www.afm-telethon.fr/sites/default/files/media/documents/du_bon_usage_de_alpha_300_et_autres_relaxateurs_de_pression.pdf", "f": 29}, {"c": "Respiratoire", "q": "Relaxateur de pression (IPPB) : quelles contre-indications et quels effets indésirables surveiller ?", "a": "Contre-indications citées : troubles de la déglutition, reflux gastro-œsophagien, hypersalivation. Effets indésirables : air dans l'estomac (ceinture abdominale, ajustement des réglages), sécheresse buccale, fatigue de la mâchoire. Un enfant qui ne peut pas retirer seul son masque doit être surveillé. L'appareil ne remplace pas une ventilation.", "s": "AFM-Téléthon – Du bon usage de l'Alpha 300 et autres relaxateurs de pression", "u": "https://www.afm-telethon.fr/sites/default/files/media/documents/du_bon_usage_de_alpha_300_et_autres_relaxateurs_de_pression.pdf", "f": 29}, {"c": "Respiratoire", "q": "Recrutement de volume pulmonaire au ballon (air stacking) chez l'enfant : comment le réaliser ?", "a": "Avec un ballon muni d'une valve unidirectionnelle (à ne jamais utiliser pour la réanimation), par masque, embout ou trachéotomie : on insuffle sur 2 à 3 inspirations successives jusqu'à remplir les poumons au maximum, l'enfant retient l'air, puis tousse activement. 3 à 5 cycles par séance, en général 2 fois par jour, plus souvent en cas d'infection. Arrêter en cas de vertiges ou de douleur thoracique.", "s": "AboutKidsHealth (SickKids, Toronto) – Lung volume recruitment", "u": "https://www.aboutkidshealth.ca/lung-volume-recruitment", "f": 29}, {"c": "Respiratoire", "q": "Gilet à oscillations thoraciques (HFCWO) : est-il recommandé chez l'enfant ?", "a": "Non dans la plupart des situations : il est recommandé de ne pas l'utiliser pour augmenter les sécrétions dans la mucoviscidose en exacerbation, enfant comme adulte (une des rares recommandations fortes). Non recommandé non plus face aux autres techniques pour réduire les exacerbations dans la mucoviscidose (recommandation faible), ni dans les maladies neuromusculaires ou la paralysie cérébrale (recommandation faible).", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 37}, {"c": "Respiratoire", "q": "Comment fonctionne la PEP (pression expiratoire positive) en désencombrement ?", "a": "Une résistance expiratoire maintient les voies aériennes ouvertes et favorise la ventilation collatérale, ce qui aide à mobiliser les sécrétions vers les grosses bronches.", "s": "Flume et al. 2009 – CF pulmonary guidelines: airway clearance therapies", "u": "https://pure.psu.edu/en/publications/cystic-fibrosis-pulmonary-guidelines-airway-clearance-therapies/", "f": 37}, {"c": "Respiratoire", "q": "PEP et PEP oscillante : quel protocole classique, et qu'est-ce qui compte le plus pour l'efficacité ?", "a": "10 à 15 respirations dans l'appareil avec expiration active, puis 2 à 3 expirations forcées sans l'appareil, à répéter. PEP basse (10-20 cmH2O) ou haute (40-100 cmH2O). Sur 141 enfants suivis 16 mois, une utilisation optimale était rare (24 % des séances en PEP, 9 % en PEP-O). Le VEMS était meilleur au-delà d'environ 5 séances bien réalisées par semaine (20 par mois). La SPLF ne recommande pas un appareil plutôt qu'un autre (recommandation faible) : la qualité et la régularité priment. (Référence : Filipow.)", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 37}, {"c": "Respiratoire", "q": "Drainage autogène : principe, âge d'utilisation dans la mucoviscidose ?", "a": "Chevaillier : décoller (bas volume), rassembler (volume courant), évacuer (haut volume). Expiration active glotte ouverte. Autonomie vers 8-12 ans, apprentissage dès 6-8 ans. Avant, drainage autogène assisté.", "s": "CF Trust 2020 – Standards of care for physiotherapy in cystic fibrosis (4e éd.)", "u": "https://www.cysticfibrosis.org.uk/sites/default/files/2020-12/Standards%20of%20Care%20and%20Good%20Clinical%20Practice%20for%20the%20Physiotherapy%20Management%20of%20Cystic%20Fibrosis%20Fourth%20edition%20December%202020.pdf", "f": 37}, {"c": "Respiratoire", "q": "Mucoviscidose stable : l'activité physique peut-elle remplacer les séances de désencombrement ?", "a": "Non. Il est recommandé de l'ajouter en complément des techniques de désencombrement pour en optimiser l'efficacité (recommandation forte), mais les données ne permettent pas de remplacer les séances par du sport seul : une étude a même recueilli moins de sécrétions avec le vélo seul qu'avec le cycle actif. Le trampoline ou la marche sur tapis avant la séance augmentent l'expectoration.", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 37}, {"c": "Respiratoire", "q": "ELTGOL : en quoi consiste-t-elle et à partir de quel âge l'utiliser chez l'enfant ?", "a": "Expiration lente totale glotte ouverte en décubitus latéral : la zone à désencombrer est placée en dessous (poumon infra-latéral), où la déflation et la ventilation sont maximales. Pression bimanuelle thoraco-abdominale lente, de la capacité résiduelle fonctionnelle jusqu'au volume résiduel. Elle est utilisable à partir de 10-12 ans : avant, la ventilation du jeune enfant se répartit plutôt vers le poumon du dessus.", "s": "Reychler et al. 2024 (Rev Mal Respir, SPLF) – Recommandations pour la prise en charge de l'encombrement des voies aériennes par les techniques de désencombrement", "u": "https://doi.org/10.1016/j.rmr.2024.06.001", "f": 37}, {"c": "Douleur", "q": "Pour quels gestes douloureux chez le nouveau-né le saccharose oral a-t-il un niveau de preuve élevé, et pour lequel n'est-il pas efficace ?", "a": "Preuve élevée pour la ponction au talon, la ponction veineuse et l'injection intramusculaire (revue Cochrane 2016, 74 essais, plus de 7 000 nourrissons). Pas efficace pour la circoncision. L'association avec la succion non nutritive fait mieux. Aucune dose optimale n'a été identifiée.", "s": "Cochrane 2016 – Sucrose for analgesia in newborn infants undergoing painful procedures (CD001069)", "u": "https://www.cochrane.org/evidence/CD001069_sucrose-analgesia-pain-relief-newborn-infants-undergoing-painful-procedures", "f": 41}, {"c": "Douleur", "q": "L'échelle EDIN sert à évaluer quel type de douleur, chez qui, et comment ?", "a": "La douleur prolongée et l'inconfort du prématuré et du nouveau-né à terme (jusqu'à environ 3 mois). 5 items : visage, corps, sommeil, relation, réconfort. Score sur 15, observé sur 1 à 4 heures. Au-delà de 5, la douleur est probable.", "s": "HUG – Échelle EDIN : mode d'utilisation", "u": "https://www.hug.ch/sites/interhug/files/structures/reseau_douleur_/documents/le-bon-outil/echelle_edin_utilisation.pdf", "f": 41}, {"c": "Douleur", "q": "Pendant un vaccin chez un enfant de moins de 2 ans, quelles mesures simples réduisent la douleur selon la recommandation HELPinKids ?", "a": "Allaiter pendant l'injection (ou donner une solution sucrée avant), tenir l'enfant dans les bras plutôt qu'allongé, ne pas aspirer avant d'injecter, et faire le vaccin le plus douloureux en dernier.", "s": "Taddio et al. 2015 (CMAJ) – Reducing pain during vaccine injections: clinical practice guideline", "u": "https://www.cmaj.ca/content/187/13/975", "f": 41}, {"c": "Douleur", "q": "EVENDOL : pour quel âge, sur combien de points, et à partir de quel score faut-il traiter ?", "a": "De la naissance à 7 ans (validée jusqu'à 18 ans en cas de polyhandicap). Score sur 15. Au-delà de 4 à l'une des deux observations (au repos à distance, puis à la mobilisation), on donne un antalgique avant de poursuivre les soins.", "s": "HUG – Échelle EVENDOL : mode d'utilisation", "u": "https://www.hug.ch/sites/interhug/files/structures/reseau_douleur_/documents/le-bon-outil/echelle-evendol-utilisation.pdf", "f": 41}, {"c": "Douleur", "q": "Quelles échelles de douleur selon l'âge de l'enfant ?", "a": "Hétéro-évaluation chez le jeune enfant (EVENDOL, FLACC), échelle des visages dès environ 4 ans, EVA ou échelle numérique à partir d'environ 6 ans.", "s": "VIDAL Recos – Douleur de l'enfant", "u": "https://www.vidal.fr/maladies/recommandations/douleur-de-l-enfant-1778.html", "f": 41}, {"c": "Douleur", "q": "Comment limiter la douleur pendant un soin chez l'enfant ?", "a": "Préparer et expliquer, distraction, positionnement confortable, solution sucrée chez le nourrisson, MEOPA ou antalgiques si besoin.", "s": "La Revue du Praticien – Douleur chez l'enfant : évaluation et traitements", "u": "https://www.larevuedupraticien.fr/article/douleur-chez-lenfant-evaluation-et-traitements-antalgiques", "f": 41}, {"c": "Douleur", "q": "Peut-on évaluer la douleur d'un enfant qui ne communique pas verbalement ?", "a": "Oui, avec des échelles d'hétéro-évaluation comportementale adaptées (par exemple FLACC), en s'appuyant aussi sur la connaissance de l'enfant par ses proches.", "s": "VIDAL Recos – Douleur de l'enfant", "u": "https://www.vidal.fr/maladies/recommandations/douleur-de-l-enfant-1778.html", "f": 41}, {"c": "Douleur", "q": "Quelle est la définition actuelle de la douleur selon l'IASP ?", "a": "« Une expérience sensorielle et émotionnelle désagréable associée, ou ressemblant à celle associée, à une lésion tissulaire réelle ou potentielle. »", "s": "IASP 2020 – Revised definition of pain (Raja et al.)", "u": "https://www.iasp-pain.org/publications/iasp-news/iasp-announces-revised-definition-of-pain/", "f": 40}, {"c": "Douleur", "q": "Selon les notes de la définition de l'IASP, un enfant qui ne peut pas parler (nourrisson, polyhandicap) peut-il avoir mal ?", "a": "Oui. L'incapacité à communiquer ne signifie pas qu'une personne n'a pas mal. Le comportement est une forme d'expression de la douleur, et le récit de la personne, quand il existe, doit être respecté.", "s": "IASP 2020 – Revised definition of pain (Raja et al.)", "u": "https://www.iasp-pain.org/publications/iasp-news/iasp-announces-revised-definition-of-pain/", "f": 40}, {"c": "Douleur", "q": "Douleur et nociception, est-ce la même chose ?", "a": "Non. La douleur est une expérience personnelle influencée par des facteurs biologiques, psychologiques et sociaux. Elle ne peut pas être déduite uniquement de l'activité des neurones sensoriels.", "s": "IASP 2020 – Revised definition of pain (Raja et al.)", "u": "https://www.iasp-pain.org/publications/iasp-news/iasp-announces-revised-definition-of-pain/", "f": 40}, {"c": "Douleur", "q": "Selon l'OMS, à partir de quelle durée parle-t-on de douleur chronique chez l'enfant, et quelle proportion d'enfants est concernée ?", "a": "Au-delà de 3 mois. Elle toucherait environ un quart à un tiers des enfants et adolescents. Ces lignes directrices (0 à 19 ans) remplacent celles de 2012.", "s": "OMS 2020 – Guidelines on the management of chronic pain in children", "u": "https://www.who.int/news/item/01-02-2021-who-issues-new-guidelines-on-the-management-of-chronic-pain-in-children", "f": 40}, {"c": "Douleur", "q": "Quels sont les trois grands domaines d'intervention recommandés par l'OMS pour la douleur chronique de l'enfant ?", "a": "Physique, psychologique et pharmacologique, dans une approche biopsychosociale centrée sur l'enfant et sa famille, avec un usage encadré des opioïdes.", "s": "OMS 2020 – Guidelines on the management of chronic pain in children", "u": "https://www.who.int/news/item/01-02-2021-who-issues-new-guidelines-on-the-management-of-chronic-pain-in-children", "f": 40}, {"c": "Douleur", "q": "Quelle proportion de jeunes vit avec une douleur chronique invalidante jusqu'au début de l'âge adulte ?", "a": "Jusqu'à 10 %. La Commission rappelle que la douleur peut et doit être évaluée chez chaque enfant.", "s": "Lancet Child & Adolescent Health Commission 2021 – Delivering transformative action in paediatric pain", "u": "https://www.uottawa.ca/about-us/media/news/childrens-pain-too-long-ignored", "f": 40}, {"c": "Douleur", "q": "Quels sont les 4 grands objectifs proposés pour mieux prendre en charge la douleur de l'enfant ?", "a": "Que la douleur compte (make pain matter), soit comprise (understood), soit visible (visible) et soit mieux traitée (better). (Référence : Commission du Lancet 2021.)", "s": "Lancet Child & Adolescent Health Commission 2021 – Delivering transformative action in paediatric pain", "u": "https://www.uottawa.ca/about-us/media/news/childrens-pain-too-long-ignored", "f": 40}, {"c": "Douleur", "q": "Petit constat sur la formation : au Canada, qui reçoit plus d'enseignement sur la douleur que les étudiants en médecine ou en soins infirmiers ?", "a": "Les étudiants vétérinaires.", "s": "Lancet Child & Adolescent Health Commission 2021 – Delivering transformative action in paediatric pain", "u": "https://www.uottawa.ca/about-us/media/news/childrens-pain-too-long-ignored", "f": 40}, {"c": "Douleur", "q": "Selon la HAS, avant quel âge la codéine est-elle contre-indiquée chez l'enfant ?", "a": "Avant 12 ans. Elle est aussi contre-indiquée après amygdalectomie ou adénoïdectomie, et n'est utilisée qu'en 2e intention à partir de 12 ans.", "s": "HAS 2016 – Prise en charge médicamenteuse de la douleur chez l'enfant : alternatives à la codéine", "u": "https://www.has-sante.fr/jcms/c_2010340/fr/prise-en-charge-medicamenteuse-de-la-douleur-chez-l-enfant-alternatives-a-la-codeine", "f": 41}, {"c": "Douleur", "q": "Quelle échelle d'hétéro-évaluation peut-on utiliser chez un adolescent polyhandicapé qui ne communique pas verbalement ?", "a": "EVENDOL, validée jusqu'à 18 ans dans le polyhandicap. On cite aussi l'échelle San Salvadour (DESS) et la GED-DI, conçues pour l'enfant avec une déficience intellectuelle ou un polyhandicap.", "s": "HUG – Échelle EVENDOL : mode d'utilisation", "u": "https://www.hug.ch/sites/interhug/files/structures/reseau_douleur_/documents/le-bon-outil/echelle-evendol-utilisation.pdf", "f": 41}, {"c": "Douleur", "q": "Pourquoi la douleur de l'enfant doit-elle être abordée de façon biopsychosociale ?", "a": "Parce que douleur et nociception ne sont pas la même chose : la douleur est une expérience personnelle, influencée par des facteurs biologiques, psychologiques et sociaux. Un enfant qui ne parle pas peut avoir mal. Une douleur qui dure plus de 3 mois devient chronique. La prise en charge associe alors les volets physique, psychologique et pharmacologique, centrée sur l'enfant et sa famille.", "s": "OMS 2020 – Guidelines on the management of chronic pain in children", "u": "https://www.who.int/news/item/01-02-2021-who-issues-new-guidelines-on-the-management-of-chronic-pain-in-children", "g": 1, "f": 40}, {"c": "Douleur", "q": "Pourquoi le MK évalue-t-il la douleur au repos et à la mobilisation, avec une échelle adaptée à l'enfant ?", "a": "Parce qu'il mobilise : la douleur à la mobilisation guide le soin et l'antalgie. L'échelle suit l'âge et la communication : hétéro-évaluation chez le jeune enfant ou l'enfant qui ne communique pas, échelle des visages vers 4 ans, EVA ou échelle numérique vers 6 ans. Demander à un enfant de 3 ans de noter sa douleur sur 10 n'est pas fiable.", "s": "HAS 2016 – Prise en charge médicamenteuse de la douleur chez l'enfant : alternatives à la codéine", "u": "https://www.has-sante.fr/jcms/c_2010340/fr/prise-en-charge-medicamenteuse-de-la-douleur-chez-l-enfant-alternatives-a-la-codeine", "g": 1, "f": 41}, {"c": "Douleur", "q": "Chez l'enfant brûlé, quels moments sont les plus douloureux, et comment en tenir compte en séance ?", "a": "Les pansements et les mobilisations. On évalue la douleur avec une échelle adaptée à l'âge, au repos et pendant les soins, et on organise la séance avec l'équipe pour profiter de l'antalgie. Les démangeaisons et l'hypersensibilité de la peau sont aussi fréquentes.", "s": "Care of Burns in Scotland 2021 – Paediatric guideline : therapy management of burns", "u": "https://www.nn.nhs.scot/cobis//wp-content/uploads/sites/9/2022/05/NSD610-006.02.pdf", "f": 23}, {"c": "Douleur", "q": "Comment s'utilise l'échelle San Salvadour chez l'enfant polyhandicapé ?", "a": "On remplit d'abord avec les parents un dossier de base qui décrit le comportement habituel de l'enfant. Puis on cote 10 items par rapport à ce comportement habituel, sur 40. Au-delà de 2, il y a un doute. Au-delà de 6, la douleur est certaine.", "s": "HUG, réseau douleur – Échelle Douleur Enfant San Salvadour : utilisation", "u": "https://www.hug.ch/sites/interhug/files/structures/reseau_douleur_/documents/le-bon-outil/echelle_san_salvadour_utilisation.pdf", "f": 11}, {"c": "Douleur", "q": "Pour une douleur aiguë légère à modérée chez l'enfant, quels antalgiques la HAS place-t-elle en premier, et faut-il les alterner ?", "a": "Paracétamol en 1re intention. Ibuprofène possible dès 3 mois. Si l'on utilise les deux, mieux vaut les associer que les alterner.", "s": "HAS 2016 – Prise en charge médicamenteuse de la douleur chez l'enfant : alternatives à la codéine", "u": "https://www.has-sante.fr/jcms/c_2010340/fr/prise-en-charge-medicamenteuse-de-la-douleur-chez-l-enfant-alternatives-a-la-codeine", "f": 41}, {"c": "Douleur", "q": "Quelles sont les caractéristiques typiques des « douleurs de croissance » ?", "a": "Enfant de 3 à 12 ans. Douleurs bilatérales des mollets ou des pieds, le soir ou la nuit (elles peuvent réveiller), jamais présentes le matin. Pas de boiterie. Examen normal (une hypermobilité est possible).", "s": "Paediatric Musculoskeletal Matters – Top tips for growing pains", "u": "https://pmmonline.org/doctor/pain-by-site/chronic-pain/growing-pains/top-tips-for-growing-pains", "f": 42}, {"c": "Douleur", "q": "Quels éléments doivent faire douter du diagnostic de douleurs de croissance ?", "a": "Douleur unilatérale ou articulaire, boiterie, douleur le matin, enfant fatigué ou fébrile, régression des acquis, présentation atypique. Il faut alors rechercher une infection, une tumeur ou une maltraitance.", "s": "Paediatric Musculoskeletal Matters – Top tips for growing pains", "u": "https://pmmonline.org/doctor/pain-by-site/chronic-pain/growing-pains/top-tips-for-growing-pains", "f": 42}, {"c": "Douleur", "q": "Lors d'un vaccin, quelle position est recommandée pour l'enfant de 3 ans et plus (recommandation HELPinKids) ?", "a": "Assis plutôt qu'allongé. Avant 3 ans, on le tient dans les bras. La présence d'un parent est recommandée jusqu'à 10 ans, et l'anesthésique local en crème jusqu'à 12 ans.", "s": "Taddio et al. 2015 (CMAJ) – Reducing pain during vaccine injections: clinical practice guideline", "u": "https://www.cmaj.ca/content/187/13/975", "f": 41}, {"c": "Douleur", "q": "Douleurs de croissance, hypermobilité douloureuse, SDRC : quel fil rouge relie leur prise en charge ?", "a": "Un diagnostic posé sur un tableau typique, avec la recherche de tout signe atypique. Bouger plutôt qu'arrêter ou immobiliser. Expliquer à l'enfant et à sa famille. Mesurer le retentissement (école, maison, loisirs) et pas seulement l'intensité. Associer une approche psychologique quand la douleur dure.", "s": "Weissmann & Uziel 2016 (Pediatric Rheumatology) – Pediatric complex regional pain syndrome: a review", "u": "https://ped-rheum.biomedcentral.com/articles/10.1186/s12969-016-0090-8", "g": 1, "f": 42}, {"c": "Douleur", "q": "Échelle des visages FPS-R : combien de visages, comment la coter et quel mot éviter dans la consigne ?", "a": "6 visages, cotés 0-2-4-6-8-10 de gauche à droite (utilisable environ de 4 à 16 ans). On dit « avoir mal » et on évite « content » ou « triste » : on mesure ce que l'enfant ressent, pas l'expression du visage.", "s": "IASP – Faces Pain Scale – Revised (FPS-R)", "u": "https://www.iasp-pain.org/resources/faces-pain-scale-revised/", "f": 41}, {"c": "Douleur", "q": "Que font les thérapies psychologiques (TCC, relaxation, hypnose, biofeedback) dans la douleur chronique de l'enfant ?", "a": "Elles réduisent la douleur à court terme, mais cet effet ne persiste pas au suivi. Le handicap fonctionnel s'améliore (pendant et après le traitement dans les douleurs chroniques mixtes, et au suivi pour les céphalées). Certitude faible à très faible. (Référence : revue Cochrane 2018.)", "s": "Cochrane 2018 (Fisher et al.) – Psychological therapies for chronic and recurrent pain in children and adolescents (CD003968)", "u": "https://cochrane.org/evidence/CD003968_psychological-therapies-management-chronic-and-recurrent-pain-children-and-adolescents", "f": 42}, {"c": "Douleur", "q": "Syndrome douloureux régional complexe (SDRC) chez l'enfant : quel profil typique, et quel traitement en 1re intention ?", "a": "Plutôt une adolescente d'environ 12 ans, avec une atteinte du membre inférieur (souvent le pied). Diagnostic clinique (critères de Budapest, non validés formellement chez l'enfant). 1re intention : kinésithérapie intensive associée à une TCC, dans une prise en charge pluridisciplinaire.", "s": "Weissmann & Uziel 2016 (Pediatric Rheumatology) – Pediatric complex regional pain syndrome: a review", "u": "https://ped-rheum.biomedcentral.com/articles/10.1186/s12969-016-0090-8", "f": 42}, {"c": "Douleur", "q": "Le SDRC de l'enfant a-t-il un meilleur pronostic que chez l'adulte, et les rechutes sont-elles fréquentes ?", "a": "Pronostic plutôt meilleur : dans un programme d'exercices intensifs, 88 % des enfants suivis environ 5 ans n'avaient plus de symptômes. Mais les rechutes sont fréquentes (environ 30 %), surtout dans les 6 mois suivant le traitement.", "s": "Weissmann & Uziel 2016 (Pediatric Rheumatology) – Pediatric complex regional pain syndrome: a review", "u": "https://ped-rheum.biomedcentral.com/articles/10.1186/s12969-016-0090-8", "f": 42}, {"c": "Douleur", "q": "Functional Disability Inventory (FDI) : que mesure-t-il et comment est-il coté ?", "a": "Le retentissement de la douleur sur les activités quotidiennes (école, maison, loisirs) de l'enfant de 8 à 17 ans environ. 15 items cotés de 0 à 4, total sur 60 : plus le score est élevé, plus le handicap est important.", "s": "Claar & Walker 2006 – Functional assessment of pediatric pain patients: psychometric properties of the Functional Disability Inventory", "u": "https://pubmed.ncbi.nlm.nih.gov/16480823/", "f": 42}, {"c": "Douleur", "q": "Sur quels critères se pose le diagnostic de SDRC chez l'enfant ?", "a": "Les critères de Budapest : une douleur disproportionnée et des signes dans plusieurs catégories (sensitifs, vasomoteurs, sudomoteurs et œdème, moteurs et trophiques). Aucun autre diagnostic ne doit mieux expliquer le tableau. Ces critères ne sont pas validés formellement chez l'enfant.", "s": "Weissmann & Uziel 2016 (Pediatric Rheumatology) – Pediatric complex regional pain syndrome: a review", "u": "https://ped-rheum.biomedcentral.com/articles/10.1186/s12969-016-0090-8", "f": 42}, {"c": "Méthodes et évaluation", "q": "Que décrit la classification de Graf ?", "a": "La morphologie du cotyle à l'échographie de hanche, du type I (hanche mature) au type IV (hanche luxée).", "s": "AAOS – CPG Pediatric developmental dysplasia of the hip", "u": "https://www.aaos.org/quality/quality-programs/pediatric-developmental-dysplasia-of-the-hip/", "f": 17}, {"c": "Méthodes et évaluation", "q": "Plagiocéphalie positionnelle : comment suivre l'évolution de l'asymétrie d'un bilan à l'autre ?", "a": "Par la différence entre les deux diagonales du crâne, mesurée de la même façon à chaque bilan. Le périmètre crânien se mesure comme chez tout nourrisson. Les radiographies ne servent qu'en cas de doute sur une synostose, ou si la déformation s'aggrave à un âge où elle devrait s'atténuer.", "s": "Cummings, Société canadienne de pédiatrie 2011 (Paediatr Child Health) – La plagiocéphalie positionnelle", "u": "https://doi.org/10.1093/pch/16.8.493", "f": 4}, {"c": "Méthodes et évaluation", "q": "Torticolis congénital : comment mesurer les amplitudes du cou ?", "a": "La rotation et l'inclinaison passives, nourrisson sur le dos, mesurées des deux côtés et comparées. On palpe aussi le sterno-cléido-mastoïdien à la recherche d'une masse ou d'une corde fibreuse.", "s": "APTA 2018 – Physical therapy management of congenital muscular torticollis (résumé)", "u": "https://www.guidelinecentral.com/guideline/8564", "f": 4}, {"c": "Méthodes et évaluation", "q": "Comment la classification de Dimeglio mesure-t-elle la sévérité d'un pied bot varus équin ?", "a": "Quatre déformations réductibles sont cotées de 0 à 4 : équin, varus de l'arrière-pied, rotation du bloc calcanéo-pédieux, adduction de l'avant-pied. Un point s'ajoute pour chaque signe : pli postérieur, pli interne, cavus marqué, hypertonie ou fibrose. Score sur 20 : grade I sous 5, II de 5 à 9, III de 10 à 14, IV de 15 à 20.", "s": "Vandergugten, Acquaviva & Docquier (UCLouvain) – Pied bot varus équin : classification de Dimeglio, méthode fonctionnelle et méthode de Ponseti", "u": "https://oer.uclouvain.be/jspui/bitstream/20.500.12279/258/1/Raphael%20Acquaviva_Pied%20bot%20varus%20équin.pdf", "f": 18}, {"c": "Méthodes et évaluation", "q": "HINE, mouvements généraux, SINDA, AIMS : lesquels sont des examens neurologiques, lesquels décrivent la motricité ?", "a": "Le HINE (2 à 24 mois) et l'échelle neurologique de la SINDA (6 semaines à 12 mois) sont des examens neurologiques standardisés. Les mouvements généraux s'observent en vidéo : ils décrivent la qualité de la motricité spontanée jusqu'à environ 5 mois. L'AIMS décrit la motricité spontanée de 0 à 18 mois, en 4 positions, en percentiles. Les trois premiers servent au repérage précoce de la PC. L'AIMS sert au suivi du développement moteur.", "s": "Novak et al. 2017 – Early, accurate diagnosis and early intervention in CP (JAMA Pediatrics)", "u": "https://cpresource.org/topic/early-diagnosis/early-accurate-diagnosis-and-early-intervention-cerebral-palsy-advances", "f": 3}, {"c": "Méthodes et évaluation", "q": "Un parent demande de « l'ostéopathie crânienne » pour son nourrisson. Que dit l'Ordre des MK ?", "a": "L'ostéopathie crânienne « n'est pas un soin conforme aux données scientifiques ». Sa pratique par un kinésithérapeute « constitue une dérive thérapeutique », et il est contraire à la déontologie d'en proposer. L'avis cite les fortes réserves de l'Académie nationale de médecine sur ces pratiques chez le nouveau-né.", "s": "CNO des masseurs-kinésithérapeutes – Avis n° 2024-05 relatif à l'ostéopathie crânienne", "u": "https://www.ordremk.fr/wp-content/uploads/2024/12/avis-cno-2024-05-relatif-a-losteopathie-cranienne.pdf", "f": 47}, {"c": "Méthodes et évaluation", "q": "Qu'évalue la Bayley-4, et à quel âge ?", "a": "Le développement de 16 jours à 42 mois : cognition, langage, motricité (fine et globale), socio-émotionnel et comportement adaptatif.", "s": "Pearson – Bayley Scales of Infant and Toddler Development, 4e éd.", "u": "https://www.pearsonassessments.com/en-us/Store/Professional-Assessments/Cognition-%26-Neuro/Bayley-Scales-of-Infant-and-Toddler-Development-%7C-Fourth-Edition/p/100001996", "f": 3}, {"c": "Méthodes et évaluation", "q": "GAS : que représentent les niveaux −2 à +2, et quelles qualités pour un bon objectif ?", "a": "−2 niveau initial. −1 progrès moindre qu'attendu. 0 attendu. +1 mieux. +2 beaucoup mieux (variante pathologies évolutives : initial à −1). Objectif SMART, une seule variable, niveaux équidistants sans chevauchement ni trou, co-construit.", "s": "Krasny-Pacini et al. – Goal Attainment Scaling in rehabilitation: a literature-based update", "u": "https://hal.sorbonne-universite.fr/hal-01513662v1/document", "f": 43}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que la MCID, et pourquoi est-elle importante avec la GMFM ?", "a": "La MCID est le plus petit changement perçu comme réellement important. La MDC est le plus petit changement qui dépasse l'erreur de mesure. Pour la GMFM-66, CanChild indique qu'aucune MCID n'a été établie scientifiquement : on considère le changement comme réel quand les intervalles de confiance à 95 % de deux évaluations (calculés par le logiciel GMAE) ne se chevauchent pas. On compare aussi l'évolution aux courbes de développement moteur attendues selon le niveau GMFCS, pour ne pas conclure à un progrès sur du bruit.", "s": "CanChild – GMFM Scoring (cotation, NT, interprétation du changement à la GMFM-66)", "u": "https://canchild.ca/en/resources/321-gmfm-scoring", "f": 44}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que le T-score de la GAS ?", "a": "Un score global calculé à partir des niveaux atteints sur plusieurs échelles (formule de Kiresuk et Sherman) : il est centré sur 50, avec un écart-type de 10. Un T-score de 50 correspond à l'atteinte attendue des objectifs. Au-dessus, les objectifs sont dépassés, en dessous ils ne sont pas atteints.", "s": "Krasny-Pacini et al. – Goal Attainment Scaling in rehabilitation: a literature-based update", "u": "https://hal.sorbonne-universite.fr/hal-01513662v1/document", "f": 43}, {"c": "Méthodes et évaluation", "q": "Dans une GAS, quand placer le niveau initial à −1 plutôt qu'à −2 ?", "a": "Quand une aggravation est possible (pathologie évolutive) : −2 représente alors une régression par rapport au niveau initial.", "s": "Krasny-Pacini et al. – Goal Attainment Scaling in rehabilitation: a literature-based update", "u": "https://hal.sorbonne-universite.fr/hal-01513662v1/document", "f": 43}, {"c": "Méthodes et évaluation", "q": "Sur quel cadre conceptuel la GMFCS-E&R s'appuie-t-elle ?", "a": "La Classification internationale du fonctionnement (CIF) de l'OMS : elle tient compte de l'environnement et des facteurs personnels. Elle décrit 5 niveaux selon 5 tranches d'âge : avant 2 ans, 2-4 ans, 4-6 ans, 6-12 ans et 12-18 ans.", "s": "Palisano et al. 2007 – GMFCS-E&R (CanChild)", "u": "https://depts.washington.edu/dbpeds/Screening%20Tools/GMFCS-ER.pdf", "f": 7}, {"c": "Méthodes et évaluation", "q": "Que mesure le PEDI-CAT ?", "a": "Les capacités fonctionnelles de la naissance à 20 ans dans 4 domaines : activités quotidiennes, mobilité, social/cognitif et responsabilité (gestion des tâches complexes du quotidien), en version informatisée adaptative remplie par le parent ou le jeune.", "s": "Shirley Ryan AbilityLab – PEDI-CAT", "u": "https://www.sralab.org/rehabilitation-measures/pediatric-evaluation-disability-inventory-computer-adaptive-test", "f": 44}, {"c": "Méthodes et évaluation", "q": "Quelle échelle utiliser dans l'amyotrophie spinale chez l'enfant qui tient assis ou qui marche ?", "a": "La HFMSE (Hammersmith Functional Motor Scale Expanded) : 33 items cotés 0 à 2, soit un maximum de 66. Chez le nourrisson très faible, on utilise plutôt la CHOP INTEND.", "s": "Critical Path Institute – Hammersmith Functional Motor Scale Expanded (HFMSE)", "u": "https://rdcoas.c-path.org/orpheus_resource/hammersmith-functional-motor-scale-expanded/", "f": 27}, {"c": "Méthodes et évaluation", "q": "Dans le modèle des « feux tricolores » de Novak pour les interventions en paralysie cérébrale, que signifient le vert, le jaune et le rouge ?", "a": "Vert : « à faire », preuves de bonne qualité d'efficacité. Jaune : preuves faibles ou incertaines, on peut l'utiliser à condition de mesurer les résultats chez l'enfant. Rouge : « à ne pas faire », preuves d'inefficacité ou de nocivité. La couleur se donne pour un résultat précis : une même intervention peut être verte pour un objectif et jaune pour un autre. Le jaune se divise en « probablement à faire » et « probablement à ne pas faire ».", "s": "CanChild – Traffic Lights Model for Cerebral Palsy Interventions (Novak et al.)", "u": "https://canchild.ca/resources/346-traffic-lights-model-for-cerebral-palsy-interventions", "f": 47}, {"c": "Méthodes et évaluation", "q": "La thérapie crânio-sacrée a-t-elle montré un bénéfice, notamment chez l'enfant ?", "a": "Aucun bénéfice clinique démontré. Les deux essais pédiatriques inclus présentaient des défauts méthodologiques sérieux, et leurs résultats positifs sont probablement des faux positifs. (Référence : méta-analyse 2024.)", "s": "Méta-analyse 2024 (Healthcare) – Thérapie crânio-sacrée : efficacité clinique", "u": "https://pubmed.ncbi.nlm.nih.gov/38540643/", "f": 47}, {"c": "Méthodes et évaluation", "q": "Les parents d'un enfant suivi au cabinet vous demandent de la microkinésithérapie ou de la fasciathérapie « en plus ». Que dit l'Ordre des MK ?", "a": "Ce sont des « dérives thérapeutiques » contraires à la déontologie, au même titre que la kinésiologie, la biokinergie et les ostéopathies crânienne et viscérale : un kinésithérapeute ne doit pas les proposer, quel que soit l'âge du patient. L'avis n° 2020-01 précise que la microkinésithérapie est « illusoire et non éprouvée ».", "s": "CNO des masseurs-kinésithérapeutes – Avis n° 2018-05 relatif aux dérives thérapeutiques", "u": "https://www.ordremk.fr/wp-content/uploads/2017/05/avis-cno-n2018-05.pdf", "f": 47}, {"c": "Méthodes et évaluation", "q": "Paralysie du plexus brachial : quels outils pour suivre la récupération ?", "a": "L'échelle de mouvement actif (AMS, de 0 à 7 pour chaque mouvement) chez le nourrisson. Le score de Mallet pour l'épaule chez l'enfant plus grand. L'AHA pour l'usage spontané du membre dans le jeu.", "s": "Hand Surgery Resource – Brachial plexus birth palsy (synthèse)", "u": "https://www.handsurgeryresource.net/bpbp", "f": 28}, {"c": "Méthodes et évaluation", "q": "Après un traumatisme crânien, que doit observer le MK au bilan, en plus de la motricité ?", "a": "La fatigabilité, au fil de la séance et de la journée. Il garde aussi en tête les troubles invisibles (attention, mémoire, fonctions exécutives, comportement), évalués en équipe. Un enfant qui paraît « récupéré » sur le plan moteur peut rester très gêné au quotidien. La motricité se mesure avec les outils de la PC : GMFM, AHA, Melbourne, tests chronométrés.", "s": "Pediatric traumatic brain injury: medical management and physiotherapy (revue narrative)", "u": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC11486524/", "f": 9}, {"c": "Méthodes et évaluation", "q": "Comment savoir si un enfant a vraiment progressé ?", "a": "Il faut d'abord un bon objectif : la COPM aide à le trouver, la GAS à le graduer. Il faut ensuite que le changement dépasse l'erreur de mesure. Enfin, il faut distinguer ce que l'enfant peut faire en séance (capacité, GMFM) de ce qu'il fait au quotidien (performance).", "s": "Turner-Stokes 2009 (Clin Rehabil) – Goal attainment scaling (GAS) in rehabilitation : a practical guide", "u": "https://www.kcl.ac.uk/nmpc/assets/rehab/6.-goal-attainment-scaling-a-practical-guide.pdf", "g": 1, "f": 44}, {"c": "Méthodes et évaluation", "q": "Des parents vous parlent d'une approche vue sur internet. Comment la situer avec eux ?", "a": "On cherche ses preuves pour l'objectif visé : vert, à faire, jaune, à mesurer chez l'enfant, rouge, à ne pas faire. « Ça ne peut pas faire de mal » est rarement vrai : risques directs et perte de chance. Un résultat sans groupe contrôle en aveugle ne prouve rien. L'Ordre encadre la déontologie. On oriente vers les approches actives, intensives et orientées vers des objectifs.", "s": "Novak et al. 2020 (Curr Neurol Neurosci Rep 20:3) – State of the evidence traffic lights 2019 : systematic review of interventions for children with cerebral palsy", "u": "https://doi.org/10.1007/s11910-020-1022-z", "g": 1, "f": 47}, {"c": "Méthodes et évaluation", "q": "Comment estime-t-on la surface brûlée chez l'enfant ?", "a": "Avec une table adaptée à l'âge (Lund et Browder), car la tête de l'enfant représente une part plus grande du corps. Pour de petites brûlures dispersées, on utilise la paume de l'enfant. Une simple rougeur ne compte pas dans la surface.", "s": "Tran, Jacques & Holland 2019 (Aust J Gen Pract) – Assessment and management of minor burns in children", "u": "https://www1.racgp.org.au/ajgp/2019/september/minor-burns-in-children-2", "f": 23}, {"c": "Méthodes et évaluation", "q": "Comment évaluer une cicatrice de brûlure chez l'enfant ?", "a": "Avec une échelle répétée à chaque bilan, comme l'échelle de Vancouver (vascularisation, pigmentation, souplesse, épaisseur) ou la POSAS, qui ajoute l'avis de l'enfant. On note aussi les amplitudes des articulations voisines, les démangeaisons et la gêne fonctionnelle.", "s": "Harris et al. 2024 (Cochrane) – Pressure garments for preventing hypertrophic scarring after burn injury", "u": "https://www.cochrane.org/evidence/CD013530_pressure-garments-preventing-hypertrophic-scarring-after-burn-injury", "f": 23}, {"c": "Méthodes et évaluation", "q": "Enfant polyhandicapé : comment juger qu'une installation ou un appareil est adapté ?", "a": "Il sert un objectif précis. Il est symétrique et confortable, et laisse l'enfant regarder, manger et interagir. La peau ne rougit pas aux points d'appui. Il s'essaie avant l'achat, se revoit avec la croissance, et il est réellement utilisé.", "s": "HAS 2020 – L'accompagnement de la personne polyhandicapée dans sa spécificité (synthèse)", "u": "https://has-sante.fr/upload/docs/application/pdf/2020-11/polyhandicap_synthese_vdef.pdf", "f": 11}, {"c": "Méthodes et évaluation", "q": "Classification fonctionnelle ou classification lésionnelle : quelle différence ? Donne un exemple de chaque.", "a": "Une classification fonctionnelle décrit ce que l'enfant fait au quotidien, au niveau des activités de la CIF : la GMFCS pour les déplacements, la MACS pour la manipulation. Une classification lésionnelle décrit une lésion ou un stade, sur une image ou à l'examen : Graf pour la hanche, Salter-Harris pour la physe. Elle guide le traitement et le pronostic.", "s": "Palisano et al. 2007 – GMFCS-E&R : descriptions par tranche d'âge (CanChild)", "u": "https://depts.washington.edu/dbpeds/Screening%20Tools/GMFCS-ER.pdf", "f": 46}, {"c": "Méthodes et évaluation", "q": "Comment décrire un enfant avec une PC grâce aux classifications, et à quoi cela sert-il ?", "a": "On donne un niveau par domaine : GMFCS pour les déplacements, MACS ou Mini-MACS pour les mains, CFCS pour la communication, EDACS pour l'alimentation, VFCS pour la vision. Le niveau est choisi avec quelqu'un qui connaît bien l'enfant, selon ce qu'il fait d'habitude. Ce profil permet de se comprendre en équipe, de prédire, de surveiller (les hanches selon la GMFCS) et de choisir objectifs et aides. Il ne mesure pas les progrès : pour cela, on utilise la GMFM ou la GAS.", "s": "Palisano et al. 2007 – GMFCS-E&R : descriptions par tranche d'âge (CanChild)", "u": "https://depts.washington.edu/dbpeds/Screening%20Tools/GMFCS-ER.pdf", "g": 1, "f": 46}, {"c": "Méthodes et évaluation", "q": "Précautions sternales après une sternotomie chez l'enfant : existe-t-il une règle commune ?", "a": "Non. Leur contenu et leur durée varient beaucoup d'un centre à l'autre : une enquête dans 35 centres nord-américains n'a trouvé aucun consensus, et aucune étude ne les relie aux résultats. On suit le protocole de l'équipe chirurgicale.", "s": "PAC3 2024 (World J Pediatr Congenit Heart Surg) – Early wound and sternal management following pediatric cardiac surgery", "u": "https://read.qxmd.com/read/38263797/early-wound-and-sternal-management-following-pediatric-cardiac-surgery", "f": 33}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que le syndrome post-réanimation de l'enfant (PICS-p) ?", "a": "Un ensemble de séquelles qui durent après un séjour en réanimation : physiques (mobilité, fonction), cognitives, émotionnelles (stress post-traumatique chez 35 à 62 %) et sociales. Il concerne aussi la famille. Jusqu'à 20 % des enfants gardent des séquelles 1 à 2 ans après.", "s": "Choong 2020 (ICU Management & Practice) – Post-intensive care syndrome: the paediatric perspective", "u": "https://healthmanagement.org/uploads/article_attachment/post-intensive-care-syndrome-the-paediatric.pdf", "f": 39}, {"c": "Méthodes et évaluation", "q": "Faut-il mobiliser tôt un enfant en réanimation ?", "a": "Oui, quand son état le permet. Les recommandations PANDEM (2022) suggèrent une mobilisation précoce avec un protocole standardisé : critères pour commencer, contre-indications, seuils de sécurité. La recommandation est faible faute d'essais, mais le programme PICU Up!, chez 200 enfants, n'a montré aucun incident lié à la mobilisation.", "s": "Smith et al. 2022 (Pediatr Crit Care Med) – PANDEM guidelines (SCCM)", "u": "https://sccm.org/clinical-resources/guidelines/guidelines/pandem-guidelines-for-infants-and-children", "f": 39}, {"c": "Méthodes et évaluation", "q": "Combien d'enfants sortent de réanimation avec une nouvelle déficience fonctionnelle ?", "a": "Dans une cohorte américaine de plus de 5 000 enfants, 4,8 %, soit deux fois plus que de décès. La nouvelle déficience était définie par une hausse d'au moins 3 points sur la Functional Status Scale.", "s": "Pollack et al. 2014 (Pediatr Crit Care Med) – New morbidities during pediatric critical care", "u": "https://researchworks.creighton.edu/esploro/outputs/journalArticle/Pediatric-intensive-care-outcomes-Development-of/991006162954002656", "f": 39}, {"c": "Méthodes et évaluation", "q": "Enfant en réanimation depuis deux semaines : que fait le MK pendant et après le séjour ?", "a": "Pendant le séjour, il vérifie chaque jour avec l'équipe si l'enfant peut être mobilisé, et le fait progresser par paliers, du lit à la marche, avec les parents. Il participe à la prévention du délire et réserve la kiné respiratoire aux indications claires. Après la sortie, il poursuit la récupération physique, prépare le retour à l'école et prévient la famille que fatigue et faiblesse peuvent durer.", "s": "Smith et al. 2022 (Pediatr Crit Care Med) – PANDEM guidelines (SCCM)", "u": "https://sccm.org/clinical-resources/guidelines/guidelines/pandem-guidelines-for-infants-and-children", "g": 1, "f": 39}, {"c": "Méthodes et évaluation", "q": "Quels sont les principes des soins centrés sur la famille ?", "a": "Les parents connaissent le mieux leur enfant : ce sont les experts de ses capacités et de ses besoins. Chaque famille est différente, et la famille reste la constante dans la vie de l'enfant. Famille et professionnels décident donc ensemble, en tenant compte des forces et des besoins de toute la famille.", "s": "CanChild – Family-centred service", "u": "https://canchild.ca/research-in-practice/family-centred-service", "f": 43}, {"c": "Méthodes et évaluation", "q": "Que sont les « F-words » de Rosenbaum et Gorter ?", "a": "Six mots anglais tirés de la CIF pour penser l'enfant au-delà de sa déficience : Functioning (ce qu'il fait), Family, Fitness (forme physique et mentale), Fun, Friends et Future. Ils aident à chercher des objectifs du côté de l'activité et de la participation.", "s": "Rosenbaum & Gorter 2011 (Child Care Health Dev) – The « F-words » in childhood disability", "u": "https://www.canchild.ca/f-words", "f": 43}, {"c": "Méthodes et évaluation", "q": "MCRO : qui répond, et comment se cotent les priorités ?", "a": "L'enfant lui-même s'il le peut. Avant 8 ans environ, ou s'il communique peu, ce sont les parents. Chaque activité citée est cotée en importance, puis jusqu'à 5 priorités sont cotées de 1 à 10 en rendement et en satisfaction. Un gain de 2 points est jugé cliniquement important.", "s": "Cerebral Palsy Alliance – Canadian Occupational Performance Measure", "u": "https://cerebralpalsy.org.au/cerebral-palsy/assessments-outcome-measures/canadian-occupational-performance-measure/", "f": 43}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce qu'un effet plafond, et pourquoi gêne-t-il le suivi d'un enfant ?", "a": "On parle d'effet plafond quand plus de 15 % des enfants obtiennent le score maximal d'un outil. À ce niveau, l'outil ne voit plus les progrès : l'enfant a l'air stable alors qu'il progresse. On choisit alors un outil plus exigeant.", "s": "Terwee et al. 2007 (J Clin Epidemiol) – Quality criteria for measurement properties", "u": "https://research.vu.nl/ws/files/2901670/267479.pdf", "f": 44}, {"c": "Méthodes et évaluation", "q": "Comment calcule-t-on le changement minimal détectable (MDC) ?", "a": "À partir de l'erreur standard de mesure (SEM), qui reflète l'écart entre deux mesures chez un enfant qui n'a pas changé : MDC = 1,96 × √2 × SEM. Un changement plus petit que le MDC peut n'être que de l'erreur de mesure.", "s": "Terwee et al. 2007 (J Clin Epidemiol) – Quality criteria for measurement properties", "u": "https://research.vu.nl/ws/files/2901670/267479.pdf", "f": 44}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que la fidélité d'un outil de mesure ?", "a": "Sa capacité à distinguer les enfants entre eux malgré l'erreur de mesure. Elle se vérifie entre deux passations et entre deux évaluateurs, souvent par un coefficient de corrélation intraclasse (ICC). Un ICC d'au moins 0,70 est jugé acceptable.", "s": "Terwee et al. 2007 (J Clin Epidemiol) – Quality criteria for measurement properties", "u": "https://research.vu.nl/ws/files/2901670/267479.pdf", "f": 44}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que la SINDA, et à quel âge l'utilise-t-on ?", "a": "La Standardized Infant NeuroDevelopmental Assessment (Hadders-Algra, 2019). Elle s'utilise de 6 semaines à 12 mois d'âge corrigé. Elle comprend trois échelles : neurologique, développementale et socio-émotionnelle. L'échelle neurologique compte 28 items et se passe en moins de 10 minutes. Elle prédit bien une évolution atypique à 2 ans.", "s": "Hadders-Algra et al. 2019 (DMCN) – Reliability and predictive validity of the SINDA neurological scale", "u": "https://pedpalascnetlibrary.omeka.net/items/show/16534", "f": 3}, {"c": "Méthodes et évaluation", "q": "Quelle différence entre GMFM-88 et GMFM-66 ?", "a": "La GMFM-88 a 88 items en 5 dimensions. La GMFM-66 en garde 66, analysés par modèle de Rasch : le logiciel GMAE donne un score à intervalles égaux (avec son intervalle de confiance) utilisé pour les courbes de développement moteur. Elle n'est validée que dans la paralysie cérébrale.", "s": "CanChild – GMFM Scoring (cotation, NT, interprétation du changement à la GMFM-66)", "u": "https://canchild.ca/en/resources/321-gmfm-scoring", "f": 44}, {"c": "Méthodes et évaluation", "q": "Comment est cotée la GMFM ?", "a": "Chaque item est coté par observation : 0 n'initie pas, 1 initie, 2 réalise partiellement, 3 réalise entièrement, selon les critères précis du manuel. NT (non testé) si l'enfant refuse ou si l'item n'est pas fait : compté 0 dans la GMFM-88, estimé par le logiciel dans la GMFM-66.", "s": "CanChild – GMFM Scoring (cotation, NT, interprétation du changement à la GMFM-66)", "u": "https://canchild.ca/en/resources/321-gmfm-scoring", "f": 44}, {"c": "Méthodes et évaluation", "q": "Quelles sont les 5 dimensions de la GMFM-88 ?", "a": "A : couché et retournements. B : assis. C : quatre pattes et à genoux. D : debout. E : marche, course et saut.", "s": "CanChild – Gross Motor Function Measure (GMFM)", "u": "https://canchild.ca/resources/44-gross-motor-function-measure-gmfm", "f": 44}, {"c": "Méthodes et évaluation", "q": "La GMFM mesure-t-elle ce que l'enfant fait au quotidien ?", "a": "Non : elle mesure sa capacité, c'est-à-dire ce qu'il peut faire dans un environnement standardisé, à la demande. La performance quotidienne se mesure avec d'autres outils (PEDI, FMS).", "s": "CanChild – Gross Motor Function Measure (GMFM)", "u": "https://canchild.ca/resources/44-gross-motor-function-measure-gmfm", "f": 44}, {"c": "Méthodes et évaluation", "q": "Comment examiner le tonus d'un enfant de façon structurée ?", "a": "Articulation par articulation, enfant détendu, segment soutenu, tête dans l'axe. Palper le muscle au repos. Tester couché, assis et debout, et pendant que l'enfant est distrait. Mobiliser à trois vitesses et noter un éventuel accrochage. Inverser brusquement le mouvement. Faire bouger un autre membre pour démasquer une dystonie. (Référence : consensus de Sanger 2003.)", "s": "Sanger et al. 2003 (Pediatrics) – Classification and definition of disorders causing hypertonia in childhood", "u": "https://doi.org/10.1542/peds.111.1.e89", "f": 8}, {"c": "Méthodes et évaluation", "q": "Qu'évalue l'Assisting Hand Assessment (AHA) ?", "a": "L'utilisation spontanée de la main atteinte en activité bimanuelle chez l'enfant avec atteinte unilatérale (PC, plexus brachial), à partir d'un jeu filmé. Les résultats sont convertis en unités AHA de 0 à 100 (modèle de Rasch). Il existe une Mini-AHA pour les tout-petits.", "s": "Karolinska Institutet – The Assisting Hand Assessment: development, psychometrics and longitudinal use", "u": "https://openarchive.ki.se/xmlui/handle/10616/38166", "f": 10}, {"c": "Méthodes et évaluation", "q": "Quelle différence entre la Melbourne Assessment 2 et l'AHA ?", "a": "La Melbourne mesure la capacité unimanuelle (ce que la main atteinte peut faire seule, sur demande). L'AHA mesure la performance bimanuelle spontanée (comment l'enfant utilise sa main dans le jeu).", "s": "Royal Children's Hospital Melbourne – The Melbourne Assessment 2", "u": "https://rch.org.au/melbourneassessment/", "f": 10}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que la MFM (Mesure de Fonction Motrice) ?", "a": "Une échelle française validée pour les maladies neuromusculaires. La MFM-32 comporte 32 items répartis en 3 domaines : D1 station debout et transferts, D2 motricité axiale et proximale, D3 motricité distale. La MFM-20 (20 items issus de la MFM-32) est validée chez l'enfant de moins de 7 ans.", "s": "MFM-NMD – Fiche pédagogique et programme de formation MFM (2025)", "u": "https://mfm-nmd.org/wp-content/uploads/2025/07/Fiche-pedagogique-MFM_programme-formation_V3_2025_12_12.pdf", "f": 27}, {"c": "Méthodes et évaluation", "q": "Comment est cotée la MFM, et faut-il une formation ?", "a": "Chaque item est coté de 0 à 3. Le résultat s'exprime en pourcentage du score maximal, global et par domaine. Une formation spécifique est recommandée pour l'utiliser de façon fiable.", "s": "MFM-NMD – Fiche pédagogique et programme de formation MFM (2025)", "u": "https://mfm-nmd.org/wp-content/uploads/2025/07/Fiche-pedagogique-MFM_programme-formation_V3_2025_12_12.pdf", "f": 27}, {"c": "Méthodes et évaluation", "q": "Comment interpréter le test de Silfverskiöld ?", "a": "On mesure la dorsiflexion genou tendu puis genou fléchi, arrière-pied maintenu (légère inversion) pour ne pas mesurer un faux mouvement du médio-pied. Si elle augmente nettement genou fléchi, ce sont surtout les gastrocnémiens qui sont courts. Si elle reste limitée, le soléaire est aussi en cause.", "s": "Prone-position modified Silfverskiöld test: feasibility and reliability", "u": "https://pubmed.ncbi.nlm.nih.gov/41732786/", "f": 45}, {"c": "Méthodes et évaluation", "q": "À quoi sert le test de Thomas ?", "a": "À rechercher un flessum de hanche (raideur des fléchisseurs, dont le psoas). La hanche opposée est fléchie au maximum pour effacer la lordose, et on observe si la cuisse testée reste décollée de la table.", "s": "Repeatability and comparison of clinical tests in children with spastic diplegia (Fisioterapia em Movimento)", "u": "https://scielo.br/j/fm/a/tCSd5cpTRFM3BSLD6rMCbKL/?lang=en", "f": 45}, {"c": "Méthodes et évaluation", "q": "Syndrome de Guillain-Barré : qu'est-ce que l'échelle de Hughes ?", "a": "Une échelle de handicap de 0 (normal) à 6. Le niveau 2 correspond à 10 mètres de marche sans aide, le niveau 4 à un patient au lit ou au fauteuil. Elle complète le testing muscle par muscle (score MRC).", "s": "Leonhard et al. 2019 (Nat Rev Neurol) – Diagnosis and management of Guillain–Barré syndrome in ten steps", "u": "https://doi.org/10.1038/s41582-019-0250-9", "f": 28}, {"c": "Méthodes et évaluation", "q": "Tests cliniques et mesures fonctionnelles : pourquoi standardiser, et que décrit chaque type de mesure ?", "a": "Comparer deux mesures prises sans protocole commun n'a pas de sens. Les tests de longueur musculaire (Silfverskiöld, Thomas) se font toujours dans la même position. Les tests chronométrés (Timed Up and Go, test de marche de 6 minutes) mesurent une capacité. La FMS décrit ce que l'enfant fait au quotidien sur 5, 50 et 500 mètres.", "s": "Williams et al. – Investigation of the Timed Up & Go test in children", "u": "https://findanexpert.unimelb.edu.au/scholarlywork/273339-investigation-of-the-timed-'up-&-go'-test-in-children", "g": 1, "f": 45}, {"c": "Méthodes et évaluation", "q": "Après un programme sur tapis ou en exosquelette, comment mesurer l'effet ?", "a": "Hors de l'appareil : test de marche de 10 mètres pour la vitesse, test de marche de 6 minutes pour l'endurance, GMFM-66 (dimensions D et E), et objectifs de l'enfant avec la GAS ou la COPM. Une bonne marche dans la machine ne prouve pas une meilleure marche au quotidien.", "s": "Chiu, Ada & Bania 2020 (Cochrane) – Mechanically assisted walking training for walking, participation, and quality of life in children with cerebral palsy", "u": "https://www.cochrane.org/evidence/CD013114_mechanically-assisted-walking-training-children-cerebral-palsy", "f": 15}, {"c": "Méthodes et évaluation", "q": "Comment adapter une séance de kinésithérapie à un enfant autiste ?", "a": "Rendre la séance prévisible, avec un emploi du temps en images. Donner des consignes courtes, montrées plutôt que dites. Partir des centres d'intérêt de l'enfant. Adapter le bruit, la lumière et le contact. Avancer par petites étapes, avec des pauses. Ces principes viennent surtout de la pratique clinique.", "s": "HAS 2018 – Trouble du spectre de l'autisme : signes d'alerte, repérage, diagnostic et évaluation chez l'enfant et l'adolescent", "u": "https://afpa.org/content/uploads/2018/02/201802161645160.reco_enfant.pdf", "f": 6}, {"c": "Méthodes et évaluation", "q": "Qu'évalue la Melbourne Assessment 2 ?", "a": "La qualité du mouvement unilatéral du membre supérieur chez l'enfant avec une PC (environ 2,5 à 15 ans), à partir de tâches filmées, selon 4 sous-échelles : amplitude, précision, dextérité et fluidité.", "s": "Royal Children's Hospital Melbourne – The Melbourne Assessment 2", "u": "https://rch.org.au/melbourneassessment/", "f": 10}, {"c": "Méthodes et évaluation", "q": "Après une fracture du membre supérieur chez le jeune enfant, comment tester rapidement les nerfs de la main ?", "a": "De façon ludique. Radial : « pouce en l'air ». Médian : serrer le poing. Interosseux antérieur : faire le signe « OK ». Ulnaire : écarter les doigts « en étoile ». On teste aussi la sensibilité : première commissure dorsale, pulpe de l'index, pulpe de l'auriculaire. Toute anomalie nouvelle impose un avis médical sans délai.", "s": "Children's Healthcare of Atlanta 2022 – Management of an isolated supracondylar humerus fracture (examen neurovasculaire)", "u": "https://choa.org/-/media/Files/Childrens/medical-professionals/clinical-practice-guidelines/supracondylar-humerus-fracture-ed", "f": 22}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que la North Star Ambulatory Assessment (NSAA) ?", "a": "L'échelle fonctionnelle de référence chez le garçon atteint de DMD qui marche : 17 items (se lever du sol, sauter, monter une marche…) cotés 0 (impossible seul), 1 (réalisé avec compensation) ou 2 (normal), pour un total de 34, en une dizaine de minutes. Un changement d'environ 2 à 3,5 points est considéré comme cliniquement important selon les études.", "s": "Shirley Ryan AbilityLab – North Star Ambulatory Assessment (cotation, MCID)", "u": "https://www.sralab.org/rehabilitation-measures/north-star-ambulatory-assessment", "f": 27}, {"c": "Méthodes et évaluation", "q": "Comment se fait le Timed Up and Go chez l'enfant ?", "a": "On chronomètre l'enfant qui se lève d'une chaise, marche 3 mètres, fait demi-tour et se rassoit, « le plus vite possible ». Chez le jeune enfant, une cible à toucher au mur (une étoile) aide à motiver. Le test est fiable et utilisé notamment dans la PC. Chez les 3-5 ans, garder le meilleur essai : un changement de moins d'environ 2 secondes peut n'être que de la variabilité.", "s": "Eur J Pediatr 2020 – Fiabilité d'un Timed Up and Go modifié chez l'enfant de 3 à 5 ans", "u": "https://link.springer.com/10.1007/s00431-020-03638-z", "f": 45}, {"c": "Méthodes et évaluation", "q": "À quoi servent les indices globaux de marche (type Gillette Gait Index, GDI, GPS) ?", "a": "À résumer en un seul score l'écart de la marche d'un enfant par rapport à une marche normale, à partir de l'analyse 3D. GDI : 100 = marche typique, chaque tranche de 10 points en dessous correspond à un écart-type. GPS : moyenne des écarts de 9 variables cinématiques, en degrés, avec une différence cliniquement importante d'environ 1,6° (Baker 2012). Utiles pour suivre l'évolution et comparer avant et après un traitement.", "s": "Baker et al. 2012 (Gait & Posture) – The minimal clinically important difference for the Gait Profile Score (référence citée par HAS-Motion)", "u": "https://wiki.has-motion.com/Sift_-_Gait_Profile_Score", "f": 13}, {"c": "Méthodes et évaluation", "q": "Après un traitement, le GDI d'un enfant passe de 70 à 80. Comment l'interpréter ?", "a": "Un GDI de 100 correspond à une marche typique, et 10 points valent un écart-type : la marche s'est rapprochée de la normale d'environ un écart-type. Mais l'indice dit combien la marche s'écarte de la normale, pas où. Pour savoir quelle articulation a changé, on regarde les courbes ou les scores par variable du GPS.", "s": "Baker et al. 2012 (Gait & Posture) – The minimal clinically important difference for the Gait Profile Score (référence citée par HAS-Motion)", "u": "https://wiki.has-motion.com/Sift_-_Gait_Profile_Score", "f": 13}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que la Functional Mobility Scale (FMS) ?", "a": "Elle décrit la mobilité habituelle sur 3 distances : 5 m (domicile), 50 m (école) et 500 m (communauté), cotées de 1 (fauteuil) à 6 (marche autonome sur tout terrain) selon l'aide technique utilisée, plus C (se déplace à quatre pattes) et N (ne fait pas la distance). Elle se cote en interrogeant l'enfant ou le parent : c'est ce qu'il fait réellement, pas ce qu'il pourrait faire.", "s": "Royal Children's Hospital Melbourne – Functional Mobility Scale (FMS)", "u": "https://www.rch.org.au/uploadedFiles/Main/Content/ortho/MOBILITYSCALE.pdf", "f": 45}, {"c": "Méthodes et évaluation", "q": "La dynamométrie manuelle est-elle fiable chez l'enfant avec une PC ?", "a": "Oui, à condition de standardiser le protocole (position, point d'application, consignes, répétitions). Elle permet de suivre la force de façon quantifiée.", "s": "Reliability of hand-held dynamometry and functional strength tests in children with CP", "u": "https://researchinformation.umcutrecht.nl/en/publications/reliability-of-hand-held-dynamometry-and-functional-strength-test/", "f": 45}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que le BOT-2 ?", "a": "Une batterie de compétences motrices de 4 à 21 ans, en 8 sous-tests : précision et intégration motrices fines, dextérité, coordination bilatérale, équilibre, vitesse et agilité, coordination des membres supérieurs, force. Une 3e édition (BOT-3, 4-25 ans) la remplace progressivement.", "s": "Bruininks & Bruininks 2005 (Pearson) – Bruininks-Oseretsky Test of Motor Proficiency, 2e éd. (BOT-2), fiche Shirley Ryan AbilityLab", "u": "https://www.sralab.org/rehabilitation-measures/bruininks-oseretsky-test-motor-proficiency-second-edition", "f": 5}, {"c": "Méthodes et évaluation", "q": "Avant de proposer un robot de marche sur tapis à un enfant, quels critères pratiques vérifier ?", "a": "Un fémur d'au moins 23 cm et un poids de plus de 15 kg. Pas de limitation importante d'amplitude ni de défaut d'axe des membres inférieurs. Un âge d'au moins 5 ans pour un programme intensif. Un bilan neuro-orthopédique avant la première séance, et des orthèses bien ajustées si la cheville est instable.", "s": "HAS 2021 – Rééducation et réadaptation de la fonction motrice de l'appareil locomoteur des personnes diagnostiquées de paralysie cérébrale (argumentaire)", "u": "https://www.has-sante.fr/upload/docs/application/pdf/2021-12/_reco355_argumentaire_paralysie_cerebrale_cd_2021_10_21_post-endossement_lg.pdf", "f": 15}, {"c": "Méthodes et évaluation", "q": "Pendant une séance de robot de marche, l'enfant a de plus en plus mal. Que faire ?", "a": "Arrêter le robot au moins un jour et examiner la région douloureuse. Une légère douleur musculaire est fréquente aux premières séances. Si la plainte persiste à la 2e ou 3e séance malgré les réglages, l'indication est rediscutée.", "s": "HAS 2021 – Rééducation et réadaptation de la fonction motrice de l'appareil locomoteur des personnes diagnostiquées de paralysie cérébrale (argumentaire)", "u": "https://www.has-sante.fr/upload/docs/application/pdf/2021-12/_reco355_argumentaire_paralysie_cerebrale_cd_2021_10_21_post-endossement_lg.pdf", "f": 15}, {"c": "Méthodes et évaluation", "q": "Que mesure l'échelle SARA, et comment se lit son score ?", "a": "Elle mesure la sévérité d'une ataxie, en 8 items : marche, station debout, assis, parole, et épreuves de coordination des membres. Le score va de 0 à 40. Plus il est haut, plus l'ataxie est sévère. C'est l'échelle utilisée dans les essais de rééducation.", "s": "Schmitz-Hübsch et al. 2006 (Neurology) – Scale for the Assessment and Rating of Ataxia (SARA)", "u": "https://pubmed.ncbi.nlm.nih.gov/?term=Scale+for+the+assessment+and+rating+of+ataxia+Schmitz-Hübsch+2006", "f": 30}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que la Pediatric Balance Scale ?", "a": "Une adaptation pédiatrique de l'échelle de Berg : 14 items d'équilibre cotés 0 à 4, maximum 56, pour l'enfant d'âge scolaire.", "s": "Shirley Ryan AbilityLab – Pediatric Balance Scale", "u": "https://www.sralab.org/rehabilitation-measures/pediatric-balance-scale", "f": 45}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que le TDC, et quel outil d'évaluation standardisé peut-on utiliser ?", "a": "Trouble neurodéveloppemental : coordination nettement inférieure à l'attendu, retentissement quotidien et scolaire, début précoce, sans autre explication. Outils : M-ABC (référence, 3e édition parue en 2023), BOT, DCDQ. Approches orientées tâche : CO-OP, NTT.", "s": "Blank et al. 2019 – International recommendations on DCD (DMCN)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6850610", "f": 5}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que l'approche CO-OP, et pour quels enfants ?", "a": "Cognitive Orientation to daily Occupational Performance (Polatajko). Approche cognitive orientée tâche : 3 objectifs choisis par l'enfant, stratégie « But-Plan-Fais-Vérifie », découverte guidée, ~10-12 séances, parents impliqués. Surtout TDC. Aussi PC légère, TSA sans DI. Dès 5-6 ans.", "s": "Blank et al. 2019 – International recommendations on DCD (DMCN)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6850610", "f": 5}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que la COPM, et en quoi complète-t-elle une GAS ?", "a": "Mesure canadienne du rendement occupationnel : entretien semi-structuré, jusqu'à 5 problèmes prioritaires cotés 1-10 en importance, rendement et satisfaction. Changement ≥ 2 points cliniquement significatif. COPM = trouver et prioriser les objectifs. GAS = graduer le résultat attendu.", "s": "Cerebral Palsy Alliance – Canadian Occupational Performance Measure", "u": "https://cerebralpalsy.org.au/cerebral-palsy/assessments-outcome-measures/canadian-occupational-performance-measure/", "f": 43}, {"c": "Méthodes et évaluation", "q": "Comment faire participer un enfant de 5 à 9 ans à la fixation de ses objectifs ?", "a": "Avec le PEGS (Perceived Efficacy and Goal Setting) : l'enfant trie des cartes illustrées d'activités (soins personnels, école, loisirs), repère celles qui lui sont difficiles et choisit celles qu'il veut travailler. Des questionnaires parallèles pour les parents et l'enseignant complètent les points de vue. Au-delà, la COPM permet de prioriser jusqu'à 5 problèmes.", "s": "CanChild – Perceived Efficacy and Goal Setting (PEGS)", "u": "https://canchild.ca/resources/48-perceived-efficacy-and-goal-setting-pegs", "f": 43}, {"c": "Méthodes et évaluation", "q": "Quels sont les domaines évalués par le M-ABC-2 ?", "a": "Dextérité manuelle, viser-attraper et équilibre. Un score au 5e percentile ou en dessous est en faveur d'un TDC. Entre le 6e et le 15e percentile, l'enfant est « à risque ». La M-ABC-3 (2023, 3-25 ans) la remplace progressivement.", "s": "Pearson – Movement Assessment Battery for Children, 3e éd. (2023)", "u": "https://www.pearsonclinical.co.uk/store/en/p/P100057001", "f": 5}, {"c": "Méthodes et évaluation", "q": "À partir de quel âge pose-t-on habituellement un diagnostic de TDC ?", "a": "En général à partir de 5 ans, en raison de la variabilité du développement moteur avant cet âge. Exception : entre 3 et 5 ans, si les difficultés sont marquées, que les autres causes sont écartées et que l'enfant a eu l'occasion d'apprendre, sur au moins deux évaluations espacées (par exemple M-ABC-2 à 3 mois d'intervalle).", "s": "CAOT – Early identification of DCD (fiche d'après les recommandations internationales 2019)", "u": "https://caot.ca/document/6144/DCD_EarlyID_InfoSheet_FNL.pdf", "f": 5}, {"c": "Méthodes et évaluation", "q": "Quelles interventions sont recommandées dans le TDC ?", "a": "Les approches orientées vers l'activité et la participation (CO-OP, entraînement orienté tâche), plutôt que les approches orientées vers des processus sous-jacents.", "s": "Blank et al. 2019 – International recommendations on DCD (DMCN)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6850610", "f": 5}, {"c": "Méthodes et évaluation", "q": "À quoi sert le test de marche de 6 minutes chez l'enfant ?", "a": "À mesurer l'endurance fonctionnelle. La distance se compare à des valeurs de référence selon l'âge et la taille. Il est utilisé dans les maladies neuromusculaires et respiratoires. Dans la DMD, il est fiable en multicentrique et une variation d'environ 30 m (28,5 à 31,7 m) est considérée comme cliniquement importante.", "s": "McDonald et al. 2013 (Muscle & Nerve) – The 6-minute walk test and other endpoints in DMD: reliability and MCID", "u": "https://www.scienceopen.com/document/vid/9693c816-211b-4ebe-a2c6-3a28363c02aa", "f": 45}, {"c": "Méthodes et évaluation", "q": "Un enfant de 7 ans « maladroit » est adressé. Quelle démarche, du repérage à l'intervention ?", "a": "On vérifie les critères du TDC : coordination nettement inférieure à l'attendu, retentissement quotidien et scolaire, début précoce, aucune autre explication. Le M-ABC-2 objective le trouble (5e percentile ou moins), le questionnaire DCDQ complète auprès des parents. On recherche un trouble associé comme le TDAH. L'intervention est orientée vers la tâche, par exemple l'approche CO-OP.", "s": "Blank et al. 2019 – International recommendations on DCD (DMCN)", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6850610", "g": 1, "f": 5}, {"c": "Méthodes et évaluation", "q": "Que contient un calendrier mictionnel, et quelles valeurs retenir ?", "a": "La fréquence et les volumes des mictions sur 48 heures de jour, et les fuites sur 7 nuits. Uriner 8 fois ou plus par jour est une fréquence augmentée, 3 fois ou moins une fréquence diminuée. La capacité vésicale attendue vaut 30 × (âge + 1) mL entre 4 et 12 ans.", "s": "Austin et al. 2015 (Neurourol Urodyn) – The standardization of terminology of lower urinary tract function in children and adolescents: update report from the ICCS", "u": "https://www.ics.org/folder/standardisation/current-ics-standardisations/lower-urinary-tract-function/d/lower-urinary-tract-function-in-children-and-adolescents-update-report/download", "f": 35}, {"c": "Méthodes et évaluation", "q": "Débitmétrie chez l'enfant : que suggèrent une courbe en cloche, en staccato et interrompue ?", "a": "En cloche : miction normale. En staccato (débit irrégulier mais continu) : contraction du plancher pelvien pendant la miction, ou dyssynergie. Interrompue (débit qui s'arrête entre des pics) : vessie hypoactive, l'enfant pousse pour uriner.", "s": "Austin et al. 2015 (Neurourol Urodyn) – The standardization of terminology of lower urinary tract function in children and adolescents: update report from the ICCS", "u": "https://www.ics.org/folder/standardisation/current-ics-standardisations/lower-urinary-tract-function/d/lower-urinary-tract-function-in-children-and-adolescents-update-report/download", "f": 35}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce que le signe de Hoover, et qu'indique-t-il ?", "a": "L'extension de la hanche faible, absente à la demande, réapparaît de façon automatique quand l'enfant fléchit l'autre hanche contre résistance. C'est un signe positif de faiblesse fonctionnelle.", "s": "Daum et al. 2014 (J Neurol Sci) – Positive signs of functional weakness", "u": "https://pubmed.ncbi.nlm.nih.gov/24656598/", "f": 12}, {"c": "Méthodes et évaluation", "q": "Qu'est-ce qu'OT'hope ?", "a": "Un outil français d'autodétermination des objectifs, créé en 2018 par deux ergothérapeutes, pour les enfants d'environ 5 à 18 ans. L'enfant trie 135 cartes d'activités (loisirs, école, vie quotidienne) en quatre colonnes, de « je sais faire » à « je ne sais pas faire », puis choisit 1 à 5 activités à travailler. Il prend environ 15 minutes. Aucune étude de validation n'est encore publiée.", "s": "Filippini 2022 (mémoire d'ergothérapie, ANFE) – OT'hope auprès du jeune traumatisé crânien", "u": "https://anfe.fr/wp-content/uploads/2022/11/FILIPPINIMathilde-Memoire-2022-0a7710da.pdf", "f": 43}, {"c": "Méthodes et évaluation", "q": "Comment construire un objectif de rééducation avec un enfant de 8 ans et ses parents ?", "a": "Partir de ce qui compte pour l'enfant et sa famille, dans l'esprit des soins centrés sur la famille. Repérer les activités difficiles avec un outil comme la MCRO, le PEGS ou OT'hope, et laisser l'enfant choisir ses priorités. Rédiger un objectif SMART, sur une seule variable, et le graduer avec la GAS sur 5 niveaux. À la date prévue, coter l'atteinte ensemble, puis garder, modifier ou remplacer l'objectif.", "s": "CanChild – Family-centred service", "u": "https://canchild.ca/research-in-practice/family-centred-service", "g": 1, "f": 43}, {"c": "Méthodes et évaluation", "q": "Examen du rachis : à quoi sert le fil à plomb tendu depuis C7 ?", "a": "De dos, son écart au pli interfessier traduit un déséquilibre frontal. De profil, on mesure les flèches cervicale et lombaire, qui décrivent le profil sagittal. La mesure se fait toujours de la même façon, pour comparer d'un bilan à l'autre.", "s": "Negrini et al. 2018 (Scoliosis Spinal Disord) – 2016 SOSORT guidelines: orthopaedic and rehabilitation treatment of idiopathic scoliosis during growth", "u": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5795289", "f": 20}];
window.QPK_FICHES = {"groupes": [["1. Développement et repérage", [1, 2, 3, 4, 5, 6]], ["2. Neurologie centrale", [7, 8, 9, 10, 11, 12]], ["3. Marche et appareillage", [13, 14, 15, 16]], ["4. Orthopédie et traumatologie", [17, 18, 19, 20, 21, 22, 23]], ["5. Sport", [24, 25, 26]], ["6. Neuromusculaire", [27, 28, 29, 30]], ["7. Maladies chroniques, génétiques et continence", [31, 32, 33, 34, 35]], ["8. Respiratoire et réanimation", [36, 37, 38, 39]], ["9. Douleur", [40, 41, 42]], ["10. Évaluation et méthodes", [43, 44, 45, 46, 47]]], "fils": [["La hanche", [4, 14, 17]], ["La marche et la boiterie", [13, 15, 16, 17, 18, 27]], ["Le rachis et la scoliose", [14, 20, 21, 27]], ["Rééduquer la motricité", [3, 5, 6, 10, 15, 24, 30]], ["Évaluer et mesurer", [7, 43, 44, 45, 46]], ["Le jeune sportif", [19, 20, 22, 25, 26]], ["Respirer et désencombrer", [29, 33, 36, 37, 38, 39]], ["Installer et appareiller", [11, 13, 14, 15, 16, 32]]], "titres": {"1": "Développement moteur", "2": "Prématuré et nouveau-né : soins de développement", "3": "Repérage précoce et intervention précoce", "4": "Torticolis et plagiocéphalie du nourrisson", "5": "Trouble développemental de la coordination", "6": "Trouble du spectre de l'autisme et motricité", "7": "Paralysie cérébrale : définition et classifications", "8": "Tonus : évaluer et traiter la spasticité", "9": "Lésions cérébrales acquises de l'enfant", "10": "Rééducation motrice intensive : les grandes approches", "11": "Polyhandicap : installation et appareillage", "12": "Troubles neurologiques fonctionnels", "13": "Analyse de la marche de l'enfant", "14": "Paralysie cérébrale : hanches et posture sur 24 heures", "15": "Tapis de marche et exosquelettes", "16": "Amputation et inégalité de longueur des membres", "17": "La hanche de l'enfant selon l'âge", "18": "Pied et troubles de rotation", "19": "Genoux et croissance", "20": "Rachis de l'enfant et de l'adolescent", "21": "Scoliose opérée : le parcours", "22": "Fractures de l'enfant en croissance", "23": "Brûlures de l'enfant", "24": "Activité physique et renforcement de l'enfant", "25": "Le jeune sportif : croissance, surmenage et retour au sport", "26": "Commotion cérébrale de l'enfant", "27": "Dystrophie de Duchenne et amyotrophie spinale", "28": "Paralysies flasques : POPB, spina bifida, SGB", "29": "Respiration dans les maladies neuromusculaires", "30": "Ataxies et Charcot-Marie-Tooth", "31": "Maladies chroniques de l'enfant", "32": "Trisomie 21, syndrome de Rett et arthrogrypose", "33": "Cardiopathies congénitales", "34": "Obésité et diabète de type 1", "35": "Troubles mictionnels et constipation de l'enfant", "36": "Bronchiolite du nourrisson", "37": "Mucoviscidose, dyskinésie ciliaire primitive et asthme", "38": "L'enfant trachéotomisé", "39": "Réanimation pédiatrique", "40": "Douleur : les concepts", "41": "Évaluer et soulager la douleur aiguë de l'enfant", "42": "Douleurs qui durent", "43": "Construire les objectifs avec l'enfant et sa famille", "44": "Mesurer le changement", "45": "Tests cliniques et mesures fonctionnelles", "46": "Les systèmes de classification en pédiatrie", "47": "Niveaux de preuve et pratiques non validées"}};
